            // Act
            var result = IsBalanced(expression);

            // Assert
            Assert.That(result, Is.EqualTo(false));
        }

        [Test]
        public void IsBalanced_UnbalancedWithExtraClosingBracket_ReturnsFalse()
        {
            // Arrange
            var expression = "{[()]}]";

            // Act
