namespace Algorithms.Numeric;

public static class JosephusProblem
{
    /// <summary>
    /// Calculates the winner in the Josephus problem.
    /// </summary>
    /// <param name="n">The number of people in the initial circle.</param>
    /// <param name="k">The count of each step. k-1 people are skipped and the k-th is executed.</param>
    /// <returns>The 1-indexed position where the player must choose in order to win the game.</returns>
    public static long FindWinner(long n, long k)
    {
        if (k <= 0)
        {
            throw new ArgumentException("The step cannot be smaller than 1");
        }

        if (k > n)
        {
            throw new ArgumentException("The step cannot be greater than the size of the group");
        }

        long winner = 0;
        for (long stepIndex = 1; stepIndex <= n; ++stepIndex)
        {
            winner = (winner + k) % stepIndex;
        }

        return winner + 1;
    }
}

namespace Algorithms.Numeric;

/// <summary>
///  In number theory, a Keith number or repfigit number is a natural number n in a given number base b with k digits such that
///  when a sequence is created such that the first k terms are the k digits of n and each subsequent term is the sum of the
///  previous k terms, n is part of the sequence.
/// </summary>
public static class KeithNumberChecker
{
    /// <summary>
    ///     Checks if a number is a Keith number or not.
    /// </summary>
    /// <param name="number">Number to check.</param>
    /// <returns>True if it is a Keith number; False otherwise.</returns>
    public static bool IsKeithNumber(int number)
    {
        if (number < 0)
        {
            throw new ArgumentException($"{nameof(number)} cannot be negative");
        }

        var tempNumber = number;

        var stringNumber = number.ToString();

        var digitsInNumber = stringNumber.Length;

        /* storing the terms of the series */
        var termsArray = new int[number];

        for (var i = digitsInNumber - 1; i >= 0; i--)
        {
            termsArray[i] = tempNumber % 10;
            tempNumber /= 10;
        }

        var sum = 0;
        var k = digitsInNumber;
        while (sum < number)
        {
            sum = 0;

            for (var j = 1; j <= digitsInNumber; j++)
            {
                sum += termsArray[k - j];
            }

            termsArray[k] = sum;
            k++;
        }

        return sum == number;
    }
}

namespace Algorithms.Numeric;

/// <summary>
/// A Krishnamurthy number is a number whose sum of the factorial of digits
/// is equal to the number itself.
///
/// For example, 145 is a Krishnamurthy number since: 1! + 4! + 5! = 1 + 24 + 120 = 145.
/// </summary>
public static class KrishnamurthyNumberChecker
{
    /// <summary>
    /// Check if a number is Krishnamurthy number or not.
    /// </summary>
    /// <param name="n">The number to check.</param>
    /// <returns>True if the number is Krishnamurthy, false otherwise.</returns>
    public static bool IsKMurthyNumber(int n)
    {
        int sumOfFactorials = 0;
        int tmp = n;

        if (n <= 0)
        {
            return false;
        }

        while (n != 0)
        {
            int factorial = (int)Factorial.Calculate(n % 10);
            sumOfFactorials += factorial;
            n = n / 10;
        }

        return tmp == sumOfFactorials;
    }
}

namespace Algorithms.Numeric;

/// <summary>
/// https://en.wikipedia.org/wiki/Miller-Rabin_primality_test
/// The Miller–Rabin primality test or Rabin–Miller primality test is a probabilistic primality test:
/// an algorithm which determines whether a given number is likely to be prime,
/// similar to the Fermat primality test and the Solovay–Strassen primality test.
/// It is of historical significance in the search for a polynomial-time deterministic primality test.
/// Its probabilistic variant remains widely used in practice, as one of the simplest and fastest tests known.
/// </summary>
public static class MillerRabinPrimalityChecker
{
    /// <summary>
    ///     Run the probabilistic primality test.
    ///     </summary>
    /// <param name="n">Number to check.</param>
    /// <param name="rounds">Number of rounds, the parameter determines the accuracy of the test, recommended value is Log2(n).</param>
    /// <param name="seed">Seed for random number generator.</param>
    /// <returns>True if is a highly likely prime number; False otherwise.</returns>
    /// <exception cref="ArgumentException">Error: number should be more than 3.</exception>
    public static bool IsProbablyPrimeNumber(BigInteger n, BigInteger rounds, int? seed = null)
    {
        Random rand = seed is null
            ? new()
            : new(seed.Value);
        return IsProbablyPrimeNumber(n, rounds, rand);
    }

    private static bool IsProbablyPrimeNumber(BigInteger n, BigInteger rounds, Random rand)
    {
        if (n <= 3)
        {
            throw new ArgumentException($"{nameof(n)} should be more than 3");
        }

        // Input #1: n > 3, an odd integer to be tested for primality
        // Input #2: k, the number of rounds of testing to perform, recommended k = Log2(n)
        // Output:   false = “composite”
        //           true  = “probably prime”

        // write n as 2r·d + 1 with d odd(by factoring out powers of 2 from n − 1)
        BigInteger r = 0;
        BigInteger d = n - 1;
        while (d % 2 == 0)
        {
            r++;
            d /= 2;
        }

        // as there is no native random function for BigInteger we suppose a random int number is sufficient
        int nMaxValue = (n > int.MaxValue) ? int.MaxValue : (int)n;
        BigInteger a = rand.Next(2, nMaxValue - 2); // ; pick a random integer a in the range[2, n − 2]

        while (rounds > 0)
        {
            rounds--;
            var x = BigInteger.ModPow(a, d, n);
            if (x == 1 || x == (n - 1))
            {
                continue;
            }

            BigInteger tempr = r - 1;
            while (tempr > 0 && (x != n - 1))
            {
                tempr--;
                x = BigInteger.ModPow(x, 2, n);
            }

            if (x == n - 1)
            {
                continue;
            }

            return false;
        }

        return true;
    }
}

namespace Algorithms.Numeric;

/// <summary>
///     Modular exponentiation is a type of exponentiation performed over a modulus
///     Modular exponentiation c is: c = b^e mod m where b is base, e is exponent, m is modulus
///     (Wiki: https://en.wikipedia.org/wiki/Modular_exponentiation).
/// </summary>
public class ModularExponentiation
{
    /// <summary>
    ///     Performs Modular Exponentiation on b, e, m.
    /// </summary>
    /// <param name="b">Base.</param>
    /// <param name="e">Exponent.</param>
    /// <param name="m">Modulus.</param>
    /// <returns>Modular Exponential.</returns>
    public int ModularPow(int b, int e, int m)
    {
        // initialize result in variable res
        int res = 1;
        if (m == 1)
        {
            // 1 divides every number
            return 0;
        }

        if (m <= 0)
        {
            // exponential not defined in this case
            throw new ArgumentException(string.Format("{0} is not a positive integer", m));
        }

        for (int i = 0; i < e; i++)
        {
            res = (res * b) % m;
        }

        return res;
    }
}

namespace Algorithms.Numeric;

/// <summary>
///     A Narcissistic number is equal to the sum of the cubes of its digits. For example, 370 is a
///     Narcissistic number because 3*3*3 + 7*7*7 + 0*0*0 = 370.
/// </summary>
public static class NarcissisticNumberChecker
{
    /// <summary>
    ///     Checks if a number is a Narcissistic number or not.
    /// </summary>
    /// <param name="number">Number to check.</param>
    /// <returns>True if is a Narcissistic number; False otherwise.</returns>
    public static bool IsNarcissistic(int number)
    {
        var sum = 0;
        var temp = number;
        var numberOfDigits = 0;
        while (temp != 0)
        {
            numberOfDigits++;
            temp /= 10;
        }

        temp = number;
        while (number > 0)
        {
            var remainder = number % 10;
            var power = (int)Math.Pow(remainder, numberOfDigits);

            sum += power;
            number /= 10;
        }

        return sum == temp;
    }
}

namespace Algorithms.Numeric;

/// <summary>
///     A perfect cube is an element of algebraic structure that is equal to the cube of another element.
/// </summary>
public static class PerfectCubeChecker
{
    /// <summary>
    ///     Checks if a number is a perfect cube or not.
    /// </summary>
    /// <param name="number">Number to check.</param>
    /// <returns>True if is a perfect cube; False otherwise.</returns>
    public static bool IsPerfectCube(int number)
    {
        if (number < 0)
        {
            number = -number;
        }

        var cubeRoot = Math.Round(Math.Pow(number, 1.0 / 3.0));
        return Math.Abs(cubeRoot * cubeRoot * cubeRoot - number) < 1e-6;
    }

    /// <summary>
    ///     Checks if a number is a perfect cube or not using binary search.
    /// </summary>
    /// <param name="number">Number to check.</param>
    /// <returns>True if is a perfect cube; False otherwise.</returns>
    public static bool IsPerfectCubeBinarySearch(int number)
    {
        if (number < 0)
        {
            number = -number;
        }

        int left = 0;
        int right = number;
        while (left <= right)
        {
            int mid = left + (right - left) / 2;
            int midCubed = mid * mid * mid;
            if (midCubed == number)
            {
                return true;
            }
            else if (midCubed < number)
            {
                left = mid + 1;
            }
            else
            {
                right = mid - 1;
            }
        }

        return false;
    }
}

namespace Algorithms.Numeric;

/// <summary>
///     In number theory, a perfect number is a positive integer that is equal to the sum of its positive
///     divisors, excluding the number itself.For instance, 6 has divisors 1, 2 and 3 (excluding
///     itself), and 1 + 2 + 3 = 6, so 6 is a perfect number.
/// </summary>
public static class PerfectNumberChecker
{
    /// <summary>
    ///     Checks if a number is a perfect number or not.
    /// </summary>
    /// <param name="number">Number to check.</param>
    /// <returns>True if is a perfect number; False otherwise.</returns>
    /// <exception cref="ArgumentException">Error number is not on interval (0.0; int.MaxValue).</exception>
    public static bool IsPerfectNumber(int number)
    {
        if (number < 0)
        {
            throw new ArgumentException($"{nameof(number)} cannot be negative");
        }

        var sum = 0; /* sum of its positive divisors */
        for (var i = 1; i < number; ++i)
        {
            if (number % i == 0)
            {
                sum += i;
            }
        }

        return sum == number;
    }
}

namespace Algorithms.Numeric;

/// <summary>
///     A perfect square is an element of algebraic structure that is equal to the square of another element.
/// </summary>
public static class PerfectSquareChecker
{
    /// <summary>
    ///     Checks if a number is a perfect square or not.
    /// </summary>
    /// <param name="number">Number too check.</param>
    /// <returns>True if is a perfect square; False otherwise.</returns>
    public static bool IsPerfectSquare(int number)
    {
        if (number < 0)
        {
            return false;
        }

        var sqrt = (int)Math.Sqrt(number);
        return sqrt * sqrt == number;
    }
}

namespace Algorithms.Numeric;

/// <summary>
///     A prime number (or a prime) is a natural number greater than 1 that is not a product of two smaller natural numbers.
/// </summary>
public static class PrimeChecker
{
    /// <summary>
    ///     Checks if a number is a prime number or not using optimized trial division.
    ///     This method avoids checking multiples of 2 and 3, optimizing the loop by checking
    ///     divisors of the form 6k ± 1 up to the square root of the number.
    /// </summary>
    /// <param name="number">The integer number to check.</param>
    /// <returns>True if the number is prime; False otherwise.</returns>
    public static bool IsPrime(int number)
    {
        // Numbers less than or equal to 1 are not prime.
        if (number <= 1)
        {
            return false;
        }

        // 2 and 3 are the first two prime numbers.
        if (number <= 3)
        {
            return true;
        }

        // Check for divisibility by 2 and 3.
        if (number % 2 == 0 || number % 3 == 0)
        {
            return false;
        }

        // Check for divisibility by numbers of the form 6k ± 1 up to sqrt(number).
        // The loop increments by 6 to skip known non-prime divisors.
        for (int i = 5; i <= number / i; i = i + 6)
        {
            // Check 6k - 1
            if (number % i == 0)
            {
                return false;
            }

            // Check 6k + 1
            if (number % (i + 2) == 0)
            {
                return false;
            }
        }

        // If no divisors are found, the number is prime.
        return true;
    }
}

namespace Algorithms.Numeric;

/// <summary>
///     Implementation of the Rectified Linear Unit (ReLU) function.
///     ReLU is defined as: ReLU(x) = max(0, x).
///     It is commonly used as an activation function in neural networks.
/// </summary>
public static class Relu
{
    /// <summary>
    ///     Compute the Rectified Linear Unit (ReLU) for a single value.
    /// </summary>
    /// <param name="input">The input real number.</param>
    /// <returns>The output real number (>= 0).</returns>
    public static double Compute(double input)
    {
        return Math.Max(0.0, input);
    }

    /// <summary>
    ///     Compute the Rectified Linear Unit (ReLU) element-wise for a vector.
    /// </summary>
    /// <param name="input">The input vector of real numbers.</param>
    /// <returns>The output vector where each element is max(0, input[i]).</returns>
    public static double[] Compute(double[] input)
    {
        if (input is null)
        {
            throw new ArgumentNullException(nameof(input));
        }

        if (input.Length == 0)
        {
            throw new ArgumentException("Array is empty.");
        }

        var output = new double[input.Length];

        for (var i = 0; i < input.Length; i++)
        {
            output[i] = Math.Max(0.0, input[i]);
        }

        return output;
    }
}

namespace Algorithms.Numeric;

/// <summary>
///     In numerical analysis, the Runge–Kutta methods are a family of implicit and explicit iterative methods,
///     used in temporal discretization for the approximate solutions of simultaneous nonlinear equations.
///     The most widely known member of the Runge–Kutta family is generally referred to as
///     "RK4", the "classic Runge–Kutta method" or simply as "the Runge–Kutta method".
///     </summary>
public static class RungeKuttaMethod
{
    /// <summary>
    ///     Loops through all the steps until xEnd is reached, adds a point for each step and then
    ///     returns all the points.
    /// </summary>
    /// <param name="xStart">Initial conditions x-value.</param>
    /// <param name="xEnd">Last x-value.</param>
    /// <param name="stepSize">Step-size on the x-axis.</param>
    /// <param name="yStart">Initial conditions y-value.</param>
    /// <param name="function">The right hand side of the differential equation.</param>
    /// <returns>The solution of the Cauchy problem.</returns>
    public static List<double[]> ClassicRungeKuttaMethod(
        double xStart,
        double xEnd,
        double stepSize,
        double yStart,
        Func<double, double, double> function)
    {
        if (xStart >= xEnd)
        {
            throw new ArgumentOutOfRangeException(
                nameof(xEnd),
                $"{nameof(xEnd)} should be greater than {nameof(xStart)}");
        }

        if (stepSize <= 0)
        {
            throw new ArgumentOutOfRangeException(
                nameof(stepSize),
                $"{nameof(stepSize)} should be greater than zero");
        }

        List<double[]> points = [];
        double[] firstPoint = [xStart, yStart];
        points.Add(firstPoint);

        var yCurrent = yStart;
        var xCurrent = xStart;

        while (xCurrent < xEnd)
        {
            var k1 = function(xCurrent, yCurrent);
            var k2 = function(xCurrent + 0.5 * stepSize, yCurrent + 0.5 * stepSize * k1);
            var k3 = function(xCurrent + 0.5 * stepSize, yCurrent + 0.5 * stepSize * k2);
            var k4 = function(xCurrent + stepSize, yCurrent + stepSize * k3);

            yCurrent += (1.0 / 6.0) * stepSize * (k1 + 2 * k2 + 2 * k3 + k4);
            xCurrent += stepSize;

            double[] newPoint = [xCurrent, yCurrent];
            points.Add(newPoint);
        }

        return points;
    }
}

namespace Algorithms.Numeric.Series;

/// <summary>
///     Maclaurin series calculates nonlinear functions approximation
///     starting from point x = 0 in a form of infinite power series:
///     f(x) = f(0) + f'(0) * x + ... + (f'n(0) * (x ^ n)) / n! + ...,
///     where n is natural number.
/// </summary>
public static class Maclaurin
{
    /// <summary>
    ///     Calculates approximation of e^x function:
    ///     e^x = 1 + x + x^2 / 2! + ... + x^n / n! + ...,
    ///     where n is number of terms (natural number),
    ///     and x is given point (rational number).
    /// </summary>
    /// <param name="x">Given point.</param>
    /// <param name="n">The number of terms in polynomial.</param>
    /// <returns>Approximated value of the function in the given point.</returns>
    public static double Exp(double x, int n) =>
        Enumerable.Range(0, n).Sum(i => ExpTerm(x, i));

    /// <summary>
    ///     Calculates approximation of sin(x) function:
    ///     sin(x) = x - x^3 / 3! + ... + (-1)^n * x^(2*n + 1) / (2*n + 1)! + ...,
    ///     where n is number of terms (natural number),
    ///     and x is given point (rational number).
    /// </summary>
    /// <param name="x">Given point.</param>
    /// <param name="n">The number of terms in polynomial.</param>
    /// <returns>Approximated value of the function in the given point.</returns>
    public static double Sin(double x, int n) =>
        Enumerable.Range(0, n).Sum(i => SinTerm(x, i));

    /// <summary>
    ///     Calculates approximation of cos(x) function:
    ///     cos(x) = 1 - x^2 / 2! + ... + (-1)^n * x^(2*n) / (2*n)! + ...,
    ///     where n is number of terms (natural number),
    ///     and x is given point (rational number).
    /// </summary>
    /// <param name="x">Given point.</param>
    /// <param name="n">The number of terms in polynomial.</param>
    /// <returns>Approximated value of the function in the given point.</returns>
    public static double Cos(double x, int n) =>
        Enumerable.Range(0, n).Sum(i => CosTerm(x, i));

    /// <summary>
    ///     Calculates approximation of e^x function:
    ///     e^x = 1 + x + x^2 / 2! + ... + x^n / n! + ...,
    ///     and x is given point (rational number).
    /// </summary>
    /// <param name="x">Given point.</param>
    /// <param name="error">Last term error value.</param>
    /// <returns>Approximated value of the function in the given point.</returns>
    /// <exception cref="ArgumentException">Error value is not on interval (0.0; 1.0).</exception>
    public static double Exp(double x, double error = 0.00001) => ErrorTermWrapper(x, error, ExpTerm);

    /// <summary>
    ///     Calculates approximation of sin(x) function:
    ///     sin(x) = x - x^3 / 3! + ... + (-1)^n * x^(2*n + 1) / (2*n + 1)! + ...,
    ///     and x is given point (rational number).
    /// </summary>
    /// <param name="x">Given point.</param>
    /// <param name="error">Last term error value.</param>
    /// <returns>Approximated value of the function in the given point.</returns>
    /// <exception cref="ArgumentException">Error value is not on interval (0.0; 1.0).</exception>
    public static double Sin(double x, double error = 0.00001) => ErrorTermWrapper(x, error, SinTerm);

    /// <summary>
    ///     Calculates approximation of cos(x) function:
    ///     cos(x) = 1 - x^2 / 2! + ... + (-1)^n * x^(2*n) / (2*n)! + ...,
    ///     and x is given point (rational number).
    /// </summary>
    /// <param name="x">Given point.</param>
    /// <param name="error">Last term error value.</param>
    /// <returns>Approximated value of the function in the given point.</returns>
    /// <exception cref="ArgumentException">Error value is not on interval (0.0; 1.0).</exception>
    public static double Cos(double x, double error = 0.00001) => ErrorTermWrapper(x, error, CosTerm);

    /// <summary>
    ///     Wrapper function for calculating approximation with estimated
    ///     count of terms, where last term value is less than given error.
    /// </summary>
    /// <param name="x">Given point.</param>
    /// <param name="error">Last term error value.</param>
    /// <param name="term">Indexed term of approximation series.</param>
    /// <returns>Approximated value of the function in the given point.</returns>
    /// <exception cref="ArgumentException">Error value is not on interval (0.0; 1.0).</exception>
    private static double ErrorTermWrapper(double x, double error, Func<double, int, double> term)
    {
        if (error <= 0.0 || error >= 1.0)
        {
            throw new ArgumentException("Error value is not on interval (0.0; 1.0).");
        }

        var i = 0;
        var termCoefficient = 0.0;
        var result = 0.0;

        do
        {
            result += termCoefficient;
            termCoefficient = term(x, i);
            i++;
        }
        while (Math.Abs(termCoefficient) > error);

        return result;
    }

    /// <summary>
    ///     Single term for e^x function approximation: x^i / i!.
    /// </summary>
    /// <param name="x">Given point.</param>
    /// <param name="i">Term index from 0 to n.</param>
    /// <returns>Single term value.</returns>
    private static double ExpTerm(double x, int i) => Math.Pow(x, i) / (long)Factorial.Calculate(i);

    /// <summary>
    ///     Single term for sin(x) function approximation: (-1)^i * x^(2*i + 1) / (2*i + 1)!.
    /// </summary>
    /// <param name="x">Given point.</param>
    /// <param name="i">Term index from 0 to n.</param>
    /// <returns>Single term value.</returns>
    private static double SinTerm(double x, int i) =>
        Math.Pow(-1, i) / ((long)Factorial.Calculate(2 * i + 1)) * Math.Pow(x, 2 * i + 1);

    /// <summary>
    ///     Single term for cos(x) function approximation: (-1)^i * x^(2*i) / (2*i)!.
    /// </summary>
    /// <param name="x">Given point.</param>
    /// <param name="i">Term index from 0 to n.</param>
    /// <returns>Single term value.</returns>
    private static double CosTerm(double x, int i) =>
        Math.Pow(-1, i) / ((long)Factorial.Calculate(2 * i)) * Math.Pow(x, 2 * i);
}

using System;

namespace Algorithms.Numeric;

/// <summary>
///     Provides the Sigmoid (Logistic) function, commonly used as an activation
///     function in neural networks to squash values into the range (0, 1).
///     Formula: sigma(x) = 1 / (1 + e^(-x)).
/// </summary>
public static class Sigmoid
{
    /// <summary>
    ///     Calculates the value of the Sigmoid function for a given input x.
    /// </summary>
    /// <param name="x">The input number.</param>
    /// <returns>The Sigmoid value, a double between 0 and 1.</returns>
    public static double Calculate(double x)
    {
        // The Sigmoid function is 1 / (1 + e^(-x))
        // We use Math.Exp(-x) to calculate e^(-x)
        double exponent = Math.Exp(-x);

        // The result is 1.0 divided by (1.0 + exponent)
        return 1.0 / (1.0 + exponent);
    }
}

namespace Algorithms.Numeric;

/// <summary>
///     Implementation of the SoftMax function.
///     Its a function that takes as input a vector of K real numbers, and normalizes
///     it into a probability distribution consisting of K probabilities proportional
///     to the exponentials of the input numbers. After softmax, the elements of the vector always sum up to 1.
///     https://en.wikipedia.org/wiki/Softmax_function.
/// </summary>
public static class SoftMax
{
    /// <summary>
    ///    Compute the SoftMax function.
    ///    The SoftMax function is defined as:
    ///    softmax(x_i) = exp(x_i) / sum(exp(x_j)) for j = 1 to n
    ///    where x_i is the i-th element of the input vector.
    ///    The elements of the output vector are the probabilities of the input vector, the output sums up to 1.
    /// </summary>
    /// <param name="input">The input vector of real numbers.</param>
    /// <returns>The output vector of real numbers.</returns>
    public static double[] Compute(double[] input)
    {
        if (input.Length == 0)
        {
            throw new ArgumentException("Array is empty.");
        }

        var exponentVector = new double[input.Length];
        var sum = 0.0;
        for (var index = 0; index < input.Length; index++)
        {
            exponentVector[index] = Math.Exp(input[index]);
            sum += exponentVector[index];
        }

        for (var index = 0; index < input.Length; index++)
        {
            exponentVector[index] /= sum;
        }

        return exponentVector;
    }
}

using System;

namespace Algorithms.Numeric;

/// <summary>
///     Provides functionality to calculate the sum of the digits of an integer.
/// </summary>
public static class SumOfDigits
{
    /// <summary>
    ///     Calculates the sum of the digits of a non-negative integer.
    ///     The method iteratively uses the modulus operator (%) to get the last digit
    ///     and the division operator (/) to drop the last digit until the number is 0.
    /// </summary>
    /// <param name="number">The non-negative integer whose digits are to be summed.</param>
    /// <returns>The sum of the digits of the input number.</returns>
    /// <exception cref="ArgumentException">Thrown if the input number is negative.</exception>
    public static int Calculate(int number)
    {
        if (number < 0)
        {
            throw new ArgumentException("Input must be a non-negative integer.", nameof(number));
        }

        if (number == 0)
        {
            return 0;
        }

        int sum = 0;
        int currentNumber = number;

        // Loop until the number becomes 0
        while (currentNumber > 0)
        {
            // Get the last digit (e.g., 123 % 10 = 3)
            int digit = currentNumber % 10;

            // Add the digit to the sum
            sum += digit;

            // Remove the last digit (e.g., 123 / 10 = 12)
            currentNumber /= 10;
        }

        return sum;
    }
}

namespace Algorithms.Numeric;

/// <summary>
///     Implementation of the Hyperbolic Tangent (Tanh) function.
///     Tanh is an activation function that takes a real number as input and squashes
///     the output to a range between -1 and 1.
///     It is defined as: tanh(x) = (exp(x) - exp(-x)) / (exp(x) + exp(-x)).
///     https://en.wikipedia.org/wiki/Hyperbolic_function#Hyperbolic_tangent.
/// </summary>
public static class Tanh
{
    /// <summary>
    ///     Compute the Hyperbolic Tangent (Tanh) function for a single value.
    ///     The Math.Tanh() method is used for efficient and accurate computation.
    /// </summary>
    /// <param name="input">The input real number.</param>
    /// <returns>The output real number in the range [-1, 1].</returns>
    public static double Compute(double input)
    {
        // For a single double, we can directly use the optimized Math.Tanh method.
        return Math.Tanh(input);
    }

    /// <summary>
    ///     Compute the Hyperbolic Tangent (Tanh) function element-wise for a vector.
    /// </summary>
    /// <param name="input">The input vector of real numbers.</param>
    /// <returns>The output vector of real numbers, where each element is in the range [-1, 1].</returns>
    public static double[] Compute(double[] input)
    {
        if (input is null)
        {
            throw new ArgumentNullException(nameof(input));
        }

        if (input.Length == 0)
        {
            throw new ArgumentException("Array is empty.");
        }

        var outputVector = new double[input.Length];

        for (var index = 0; index < input.Length; index++)
        {
            // Apply Tanh to each element using the optimized Math.Tanh method.
            outputVector[index] = Math.Tanh(input[index]);
        }

        return outputVector;
    }
}

namespace Algorithms.Other;

/// <summary>
/// Almost all real complex decision-making task is described by more than one criterion.
/// There are different methods to select the best decisions from the defined set of decisions.
/// This class contains implementations of the popular convolution methods: linear and maxmin.
/// </summary>
public static class DecisionsConvolutions
{
    /// <summary>
    /// This method implements the linear method of decision selection. It is based on
    /// the calculation of the "value" for each decision and the selection of the most
    /// valuable one.
    /// </summary>
    /// <param name="matrix">Contains a collection of the criteria sets.</param>
    /// <param name="priorities">Contains a set of priorities for each criterion.</param>
    /// <returns>The most effective decision that is represented by a set of criterias.</returns>
    public static List<decimal> Linear(List<List<decimal>> matrix, List<decimal> priorities)
    {
        var decisionValues = new List<decimal>();

        foreach (var decision in matrix)
        {
            decimal sum = 0;
            for (int i = 0; i < decision.Count; i++)
            {
                sum += decision[i] * priorities[i];
            }

            decisionValues.Add(sum);
        }

        decimal bestDecisionValue = decisionValues.Max();
        int bestDecisionIndex = decisionValues.IndexOf(bestDecisionValue);

        return matrix[bestDecisionIndex];
    }

    /// <summary>
    /// This method implements maxmin method of the decision selection. It is based on
    /// the calculation of the least criteria value and comparison of decisions based
    /// on the calculated results.
    /// </summary>
    /// <param name="matrix">Contains a collection of the criteria sets.</param>
    /// <param name="priorities">Contains a set of priorities for each criterion.</param>
    /// <returns>The most effective decision that is represented by a set of criterias.</returns>
    public static List<decimal> MaxMin(List<List<decimal>> matrix, List<decimal> priorities)
    {
        var decisionValues = new List<decimal>();

        foreach (var decision in matrix)
        {
            decimal minValue = decimal.MaxValue;
            for (int i = 0; i < decision.Count; i++)
            {
                decimal result = decision[i] * priorities[i];
                if (result < minValue)
                {
                    minValue = result;
                }
            }

            decisionValues.Add(minValue);
        }

        decimal bestDecisionValue = decisionValues.Max();
        int bestDecisionIndex = decisionValues.IndexOf(bestDecisionValue);

        return matrix[bestDecisionIndex];
    }
}

namespace Algorithms.Other;

/// <summary>
///     Fermat's prime tester https://en.wikipedia.org/wiki/Fermat_primality_test.
/// </summary>
public static class FermatPrimeChecker
{
    /// <summary>
    ///     Checks if input number is a probable prime.
    /// </summary>
    /// <param name="numberToTest">Input number.</param>
    /// <param name="timesToCheck">Number of times to check.</param>
    /// <returns>True if is a prime; False otherwise.</returns>
    public static bool IsPrime(int numberToTest, int timesToCheck)
    {
        // You have to use BigInteger for two reasons:
        //   1. The pow operation between two int numbers usually overflows an int
        //   2. The pow and modular operation is very optimized
        var numberToTestBigInteger = new BigInteger(numberToTest);
        var exponentBigInteger = new BigInteger(numberToTest - 1);

        // Create a random number generator using the current time as seed
        var r = new Random(default(DateTime).Millisecond);

        var iterator = 1;
        var prime = true;

        while (iterator < timesToCheck && prime)
        {
            var randomNumber = r.Next(1, numberToTest);
            var randomNumberBigInteger = new BigInteger(randomNumber);
            if (BigInteger.ModPow(randomNumberBigInteger, exponentBigInteger, numberToTestBigInteger) != 1)
            {
                prime = false;
            }

            iterator++;
        }

        return prime;
    }
}

namespace Algorithms.Other;

/// <summary>
/// The Gaussian method (coordinate descent method) refers to zero-order methods in which only the value
/// of the function Q(X) at different points in the space of variables is used to organize the search
/// for the extremum. This reduces the overall computational cost of finding the extremum. Also in
/// the Gaussian method, the procedures for finding and moving the operating point are simplified as
/// much as possible.
/// </summary>
public class GaussOptimization
{
    /// <summary>
    /// Implementation of function extremum search by the Gauss optimization algorithm.
    /// </summary>
    /// <param name="func">Function for which extremum has to be found.</param>
    /// <param name="n">This parameter identifies how much step size will be decreased each iteration.</param>
    /// <param name="step">The initial shift step.</param>
    /// <param name="eps">This value is used to control the accuracy of the optimization. In case if the error is less than eps,
    /// optimization will be stopped.</param>
    /// <param name="x1">The first function parameter.</param>
    /// <param name="x2">The second function parameter.</param>
    /// <returns>A tuple of coordinates of function extremum.</returns>
    public (double X1, double X2) Optimize(
        Func<double, double, double> func,
        double n,
        double step,
        double eps,
        double x1,
        double x2)
    {
        // The initial value of the error
        double error = 1;

        while (Math.Abs(error) > eps)
        {
            // Calculation of the function with coordinates that are calculated with shift
            double bottom = func(x1, x2 - step);
            double top = func(x1, x2 + step);
            double left = func(x1 - step, x2);
            double right = func(x1 + step, x2);

            // Determination of the best option.
            var possibleFunctionValues = new List<double> { bottom, top, left, right };
            double maxValue = possibleFunctionValues.Max();
            double maxValueIndex = possibleFunctionValues.IndexOf(maxValue);

            // Error evaluation
            error = maxValue - func(x1, x2);

            // Coordinates update for the best option
            switch (maxValueIndex)
            {
                case 0:
                    x2 -= step;
                    break;
                case 1:
                    x2 += step;
                    break;
                case 2:
                    x1 -= step;
                    break;
                default:
                    x1 += step;
                    break;
            }

            // Step reduction
            step /= n;
        }

        return (x1, x2);
    }
}

namespace Algorithms.Other;

public static class GeoLocation
{
    private const double EarthRadiusKm = 6371.01d;

    /// <summary>
    ///     Calculates spherical distance between 2 points given their latitude, longitude coordinates.
    ///     https://www.movable-type.co.uk/scripts/latlong.html.
    /// </summary>
    /// <param name="lat1">Latitude of point A.</param>
    /// <param name="lng1">Longitude of point A.</param>
    /// <param name="lat2">Latitude of point B.</param>
    /// <param name="lng2">Longitude of point B.</param>
    /// <returns>Spherical distance between A and B.</returns>
    public static double CalculateDistanceFromLatLng(double lat1, double lng1, double lat2, double lng2)
    {
        var pi180 = Math.PI / 180d;
        var lat1Radian = lat1 * pi180;
        var lng1Radian = lng1 * pi180;
        var lat2Radian = lat2 * pi180;
        var lng2Radian = lng2 * pi180;

        var diffLat = lat2Radian - lat1Radian;
        var diffLng = lng2Radian - lng1Radian;

        var haversine =
            Math.Sin(diffLat / 2) * Math.Sin(diffLat / 2)
            + Math.Cos(lat1Radian) * Math.Cos(lat2Radian) * Math.Sin(diffLng / 2) * Math.Sin(diffLng / 2);
        var distance = EarthRadiusKm * (2d * Math.Atan2(Math.Sqrt(haversine), Math.Sqrt(1 - haversine)));

        return distance * 1000; // Convert from km -> m
    }
}

