namespace Algorithms.Problems.KnightTour;

/// <summary>
/// Computes a (single) Knight's Tour on an <c>n × n</c> chessboard using
/// depth-first search (DFS) with backtracking.
/// </summary>
/// <remarks>
/// <para>
/// A Knight's Tour is a sequence of knight moves that visits every square exactly once.
/// This implementation returns the first tour it finds (if any), starting from whichever
/// starting cell leads to a solution first. It explores every board square as a potential
/// starting position in row-major order.
/// </para>
/// <para>
/// The algorithm is a plain backtracking search—no heuristics (e.g., Warnsdorff’s rule)
/// are applied. As a result, runtime can grow exponentially with <c>n</c> and become
/// impractical on larger boards.
/// </para>
/// <para>
/// <b>Solvability (square boards):</b>
/// A (non-closed) tour exists for <c>n = 1</c> and for all <c>n ≥ 5</c>.
/// There is no tour for <c>n ∈ {2, 3, 4}</c>. This implementation throws an
/// <see cref="ArgumentException"/> if no tour is found.
/// </para>
/// <para>
/// <b>Coordinate convention:</b> The board is indexed as <c>[row, column]</c>,
/// zero-based, with <c>(0,0)</c> in the top-left corner.
/// </para>
/// </remarks>
public sealed class OpenKnightTour
{
    /// <summary>
    /// Attempts to find a Knight's Tour on an <c>n × n</c> board.
    /// </summary>
    /// <param name="n">Board size (number of rows/columns). Must be positive.</param>
    /// <returns>
    /// A 2D array of size <c>n × n</c> where each cell contains the
    /// 1-based visit order (from <c>1</c> to <c>n*n</c>) of the knight.
    /// </returns>
    /// <exception cref="ArgumentException">
    /// Thrown when <paramref name="n"/> ≤ 0, or when no tour exists / is found for the given <paramref name="n"/>.
    /// </exception>
    /// <remarks>
    /// <para>
    /// This routine tries every square as a starting point. As soon as a complete tour is found,
    /// the filled board is returned. If no tour is found, an exception is thrown.
    /// </para>
    /// <para>
    /// <b>Performance:</b> Exponential in the worst case. For larger boards, consider adding
    /// Warnsdorff’s heuristic (choose next moves with the fewest onward moves) or a hybrid approach.
    /// </para>
    /// </remarks>
    public int[,] Tour(int n)
    {
        if (n <= 0)
        {
            throw new ArgumentException("Board size must be positive.", nameof(n));
        }

        var board = new int[n, n];

        // Try every square as a starting point.
        for (var r = 0; r < n; r++)
        {
            for (var c = 0; c < n; c++)
            {
                board[r, c] = 1; // first step
                if (KnightTourHelper(board, (r, c), 1))
                {
                    return board;
                }

                board[r, c] = 0; // backtrack and try next start
            }
        }

        throw new ArgumentException($"Knight Tour cannot be performed on a board of size {n}.");
    }

    /// <summary>
    /// Recursively extends the current partial tour from <paramref name="pos"/> after placing
    /// move number <paramref name="current"/> in that position.
    /// </summary>
    /// <param name="board">The board with placed move numbers; <c>0</c> means unvisited.</param>
    /// <param name="pos">Current knight position (<c>Row</c>, <c>Col</c>).</param>
    /// <param name="current">The move number just placed at <paramref name="pos"/>.</param>
    /// <returns><c>true</c> if a full tour is completed; <c>false</c> otherwise.</returns>
    /// <remarks>
    /// Tries each legal next move in a fixed order (no heuristics). If a move leads to a dead end,
    /// it backtracks by resetting the target cell to <c>0</c> and tries the next candidate.
    /// </remarks>
    private bool KnightTourHelper(int[,] board, (int Row, int Col) pos, int current)
    {
        if (IsComplete(board))
        {
            return true;
        }

        foreach (var (nr, nc) in GetValidMoves(pos, board.GetLength(0)))
        {
            if (board[nr, nc] == 0)
            {
                board[nr, nc] = current + 1;

                if (KnightTourHelper(board, (nr, nc), current + 1))
                {
                    return true;
                }

                board[nr, nc] = 0; // backtrack
            }
        }

        return false;
    }

    /// <summary>
    /// Computes all legal knight moves from <paramref name="position"/> on an <c>n × n</c> board.
    /// </summary>
    /// <param name="position">Current position (<c>R</c>, <c>C</c>).</param>
    /// <param name="n">Board dimension (rows = columns = <paramref name="n"/>).</param>
    /// <returns>
    /// An enumeration of on-board destination coordinates. Order is fixed and unoptimized:
    /// <c>(+1,+2), (-1,+2), (+1,-2), (-1,-2), (+2,+1), (+2,-1), (-2,+1), (-2,-1)</c>.
    /// </returns>
    /// <remarks>
    /// Keeping a deterministic order makes the search reproducible, but it’s not necessarily fast.
    /// To accelerate, pre-sort by onward-degree (Warnsdorff) or by a custom heuristic.
    /// </remarks>
    private IEnumerable<(int R, int C)> GetValidMoves((int R, int C) position, int n)
    {
        var r = position.R;
        var c = position.C;

        var candidates = new (int Dr, int Dc)[]
        {
            (1,  2), (-1,  2), (1, -2), (-1, -2),
            (2,  1), (2, -1), (-2,  1), (-2, -1),
        };

        foreach (var (dr, dc) in candidates)
        {
            var nr = r + dr;
            var nc = c + dc;

            if (nr >= 0 && nr < n && nc >= 0 && nc < n)
            {
                yield return (nr, nc);
            }
        }
    }

    /// <summary>
    /// Checks whether the tour is complete; i.e., every cell is non-zero.
    /// </summary>
    /// <param name="board">The board to check.</param>
    /// <returns><c>true</c> if all cells have been visited; otherwise, <c>false</c>.</returns>
    /// <remarks>
    /// A complete board means the knight has visited exactly <c>n × n</c> distinct cells.
    /// </remarks>
    private bool IsComplete(int[,] board)
    {
        var n = board.GetLength(0);
        for (var row = 0; row < n; row++)
        {
            for (var col = 0; col < n; col++)
            {
                if (board[row, col] == 0)
                {
                    return false;
                }
            }
        }

        return true;
    }
}

namespace Algorithms.Problems.NQueens;

public class BacktrackingNQueensSolver
{
    /// <summary>
    ///     Solves N-Queen Problem given a n dimension chessboard and using backtracking with recursion algorithm.
    ///     If we find a dead-end within or current solution we go back and try another position for queen.
    /// </summary>
    /// <param name="n">Number of rows.</param>
    /// <returns>All solutions.</returns>
    public IEnumerable<bool[,]> BacktrackSolve(int n)
    {
        if (n < 0)
        {
            throw new ArgumentException(nameof(n));
        }

        return BacktrackSolve(new bool[n, n], 0);
    }

    private static IEnumerable<bool[,]> BacktrackSolve(bool[,] board, int col)
    {
        var solutions = col < board.GetLength(0) - 1
            ? HandleIntermediateColumn(board, col)
            : HandleLastColumn(board);
        return solutions;
    }

    private static IEnumerable<bool[,]> HandleIntermediateColumn(bool[,] board, int col)
    {
        // To start placing queens on possible spaces within the board.
        for (var i = 0; i < board.GetLength(0); i++)
        {
            if (CanPlace(board, i, col))
            {
                board[i, col] = true;

                foreach (var solution in BacktrackSolve(board, col + 1))
                {
                    yield return solution;
                }

                board[i, col] = false;
            }
        }
    }

    private static IEnumerable<bool[,]> HandleLastColumn(bool[,] board)
    {
        var n = board.GetLength(0);
        for (var i = 0; i < n; i++)
        {
            if (CanPlace(board, i, n - 1))
            {
                board[i, n - 1] = true;

                yield return (bool[,])board.Clone();

                board[i, n - 1] = false;
            }
        }
    }

    /// <summary>
    ///     Checks whether current queen can be placed in current position,
    ///     outside attacking range of another queen.
    /// </summary>
    /// <param name="board">Source board.</param>
    /// <param name="row">Row coordinate.</param>
    /// <param name="col">Col coordinate.</param>
    /// <returns>true if queen can be placed in given chessboard coordinates; false otherwise.</returns>
    private static bool CanPlace(bool[,] board, int row, int col)
    {
        // To check whether there are any queens on current row.
        for (var i = 0; i < col; i++)
        {
            if (board[row, i])
            {
                return false;
            }
        }

        // To check diagonal attack top-left range.
        for (int i = row - 1, j = col - 1; i >= 0 && j >= 0; i--, j--)
        {
            if (board[i, j])
            {
                return false;
            }
        }

        // To check diagonal attack bottom-left range.
        for (int i = row + 1, j = col - 1; j >= 0 && i < board.GetLength(0); i++, j--)
        {
            if (board[i, j])
            {
                return false;
            }
        }

        // Return true if it can use position.
        return true;
    }
}

namespace Algorithms.Problems.StableMarriage;

public class Accepter
{
    public Proposer? EngagedTo { get; set; }

    public List<Proposer> PreferenceOrder { get; set; } = [];

    public bool PrefersOverCurrent(Proposer newProposer) =>
        EngagedTo is null ||
        PreferenceOrder.IndexOf(newProposer) < PreferenceOrder.IndexOf(EngagedTo);
}

namespace Algorithms.Problems.StableMarriage;

public static class GaleShapley
{
    /// <summary>
    ///     Finds a stable matching between two equal sets of elements (fills EngagedTo properties).
    ///     time complexity: O(n^2), where n - array size.
    ///     Guarantees:
    ///     - Everyone is matched
    ///     - Matches are stable (there is no better accepter, for any given proposer, which would accept a new match).
    ///     Presented and proven by David Gale and Lloyd Shapley in 1962.
    /// </summary>
    public static void Match(Proposer[] proposers, Accepter[] accepters)
    {
        if (proposers.Length != accepters.Length)
        {
            throw new ArgumentException("Collections must have equal count");
        }

        while (proposers.Any(m => !IsEngaged(m)))
        {
            DoSingleMatchingRound(proposers.Where(m => !IsEngaged(m)));
        }
    }

    private static bool IsEngaged(Proposer proposer) => proposer.EngagedTo is not null;

    private static void DoSingleMatchingRound(IEnumerable<Proposer> proposers)
    {
        foreach (var newProposer in proposers)
        {
            var accepter = newProposer.PreferenceOrder.First!.Value;

            if (accepter.EngagedTo is null)
            {
                Engage(newProposer, accepter);
            }
            else
            {
                if (accepter.PrefersOverCurrent(newProposer))
                {
                    Free(accepter.EngagedTo);
                    Engage(newProposer, accepter);
                }
            }

            newProposer.PreferenceOrder.RemoveFirst();
        }
    }

    private static void Free(Proposer proposer)
    {
        proposer.EngagedTo = null;
    }

    private static void Engage(Proposer proposer, Accepter accepter)
    {
        proposer.EngagedTo = accepter;
        accepter.EngagedTo = proposer;
    }
}

