namespace Algorithms.Problems.TravelingSalesman;

/// <summary>
/// Provides methods to solve the Traveling Salesman Problem (TSP) using brute-force and nearest neighbor heuristics.
/// The TSP is a classic optimization problem in which a salesman must visit each city exactly once and return to the starting city, minimizing the total travel distance.
/// </summary>
public static class TravelingSalesmanSolver
{
    /// <summary>
    /// Solves the TSP using brute-force search. This method checks all possible permutations of cities to find the shortest possible route.
    /// WARNING: This approach is only feasible for small numbers of cities due to factorial time complexity.
    /// </summary>
    /// <param name="distanceMatrix">A square matrix where element [i, j] represents the distance from city i to city j.</param>
    /// <returns>A tuple containing the minimal route (as an array of city indices) and the minimal total distance.</returns>
    public static (int[] Route, double Distance) SolveBruteForce(double[,] distanceMatrix)
    {
        int n = distanceMatrix.GetLength(0);
        if (n != distanceMatrix.GetLength(1))
        {
            throw new ArgumentException("Distance matrix must be square.");
        }

        if (n < 2)
        {
            throw new ArgumentException("At least two cities are required.");
        }

        var cities = Enumerable.Range(0, n).ToArray();
        double minDistance = double.MaxValue;
        int[]? bestRoute = null;

        foreach (var perm in Permute(cities.Skip(1).ToArray()))
        {
            var route = new int[n + 1];
            route[0] = 0;
            for (int i = 0; i < perm.Length; i++)
            {
                route[i + 1] = perm[i];
            }

            // Ensure route ends at city 0
            route[n] = 0;

            double dist = 0;
            for (int i = 0; i < n; i++)
            {
                dist += distanceMatrix[route[i], route[i + 1]];
            }

            if (dist < minDistance)
            {
                minDistance = dist;
                bestRoute = (int[])route.Clone();
            }
        }

        return (bestRoute ?? Array.Empty<int>(), minDistance);
    }

    /// <summary>
    /// Solves the TSP using the nearest neighbor heuristic. This method builds a route by always visiting the nearest unvisited city next.
    /// This approach is much faster but may not find the optimal solution.
    /// </summary>
    /// <param name="distanceMatrix">A square matrix where element [i, j] represents the distance from city i to city j.</param>
    /// <param name="start">The starting city index.</param>
    /// <returns>A tuple containing the route (as an array of city indices) and the total distance.</returns>
    public static (int[] Route, double Distance) SolveNearestNeighbor(double[,] distanceMatrix, int start = 0)
    {
        int n = distanceMatrix.GetLength(0);
        if (n != distanceMatrix.GetLength(1))
        {
            throw new ArgumentException("Distance matrix must be square.");
        }

        if (start < 0 || start >= n)
        {
            throw new ArgumentOutOfRangeException(nameof(start));
        }

        var visited = new bool[n];
        List<int> route = [start];
        visited[start] = true;
        double totalDistance = 0;
        int current = start;
        for (int step = 1; step < n; step++)
        {
            double minDist = double.MaxValue;
            int next = -1;
            for (int j = 0; j < n; j++)
            {
                if (!visited[j] && distanceMatrix[current, j] < minDist)
                {
                    minDist = distanceMatrix[current, j];
                    next = j;
                }
            }

            if (next == -1)
            {
                throw new InvalidOperationException("No unvisited cities remain.");
            }

            route.Add(next);
            visited[next] = true;
            totalDistance += minDist;
            current = next;
        }

        totalDistance += distanceMatrix[current, start];
        route.Add(start);
        return (route.ToArray(), totalDistance);
    }

    /// <summary>
    /// Generates all permutations of the input array.
    /// Used for brute-force TSP solution.
    /// </summary>
    private static IEnumerable<int[]> Permute(int[] arr)
    {
        if (arr.Length == 1)
        {
            yield return arr;
            yield break;
        }

        for (int i = 0; i < arr.Length; i++)
        {
            var rest = arr.Where((_, idx) => idx != i).ToArray();
            foreach (var perm in Permute(rest))
            {
                yield return [arr[i], ..perm];
            }
        }
    }
}

namespace Algorithms.RecommenderSystem;

public class CollaborativeFiltering(ISimilarityCalculator similarityCalculator)
{
    private readonly ISimilarityCalculator similarityCalculator = similarityCalculator;

    /// <summary>
    /// Method to calculate similarity between two users using Pearson correlation.
    /// </summary>
    /// <param name="user1Ratings">Rating of User 1.</param>
    /// <param name="user2Ratings">Rating of User 2.</param>
    /// <returns>double value to reflect the index of similarity between two users.</returns>
    public double CalculateSimilarity(Dictionary<string, double> user1Ratings, Dictionary<string, double> user2Ratings)
    {
        var commonItems = user1Ratings.Keys.Intersect(user2Ratings.Keys).ToList();
        if (commonItems.Count == 0)
        {
            return 0;
        }

        var user1Scores = commonItems.Select(item => user1Ratings[item]).ToArray();
        var user2Scores = commonItems.Select(item => user2Ratings[item]).ToArray();

        var avgUser1 = user1Scores.Average();
        var avgUser2 = user2Scores.Average();

        double numerator = 0;
        double sumSquare1 = 0;
        double sumSquare2 = 0;
        double epsilon = 1e-10;

        for (var i = 0; i < commonItems.Count; i++)
        {
            var diff1 = user1Scores[i] - avgUser1;
            var diff2 = user2Scores[i] - avgUser2;

            numerator += diff1 * diff2;
            sumSquare1 += diff1 * diff1;
            sumSquare2 += diff2 * diff2;
        }

        var denominator = Math.Sqrt(sumSquare1 * sumSquare2);
        return Math.Abs(denominator) < epsilon ? 0 : numerator / denominator;
    }

    /// <summary>
    /// Predict a rating for a specific item by a target user.
    /// </summary>
    /// <param name="targetItem">The item for which the rating needs to be predicted.</param>
    /// <param name="targetUser">The user for whom the rating is being predicted.</param>
    /// <param name="ratings">
    /// A dictionary containing user ratings where:
    /// - The key is the user's identifier (string).
    /// - The value is another dictionary where the key is the item identifier (string), and the value is the rating given by the user (double).
    /// </param>
    /// <returns>The predicted rating for the target item by the target user.
    /// If there is insufficient data to predict a rating, the method returns 0.
    /// </returns>
    public double PredictRating(string targetItem, string targetUser, Dictionary<string, Dictionary<string, double>> ratings)
    {
        var targetUserRatings = ratings[targetUser];
        double totalSimilarity = 0;
        double weightedSum = 0;
        double epsilon = 1e-10;

        foreach (var otherUser in ratings.Keys.Where(u => u != targetUser))
        {
            var otherUserRatings = ratings[otherUser];
            if (otherUserRatings.ContainsKey(targetItem))
            {
                var similarity = similarityCalculator.CalculateSimilarity(targetUserRatings, otherUserRatings);
                totalSimilarity += Math.Abs(similarity);
                weightedSum += similarity * otherUserRatings[targetItem];
            }
        }

        return Math.Abs(totalSimilarity) < epsilon ? 0 : weightedSum / totalSimilarity;
    }
}

