/// <summary>
///     Naive Shuffle is a simple and incorrect shuffling algorithm
///     that randomly swaps every element with any other element in the array.
/// </summary>
/// <typeparam name="T">Type array input.</typeparam>
public class NaiveShuffler<T> : IShuffler<T>
{
    /// <summary>
    /// First, it loop from 0 to n - 1.
    /// Next, it will randomly pick any j in the array.
    /// Lastly, it will swap array[i] with array[j].
    /// </summary>
    /// <param name="array">Array to shuffle.</param>
    /// <param name="seed">Random generator seed. Used to repeat the shuffle.</param>
    public void Shuffle(T[] array, int? seed = null)
    {
        var random = seed is null ? new Random() : new Random(seed.Value);
        for (int i = 0; i < array.Length; i++)
        {
            int j = random.Next(array.Length);
            T temp = array[i];
            array[i] = array[j];
            array[j] = temp;
        }
    }
}

namespace Algorithms.Shufflers;

/// <summary>
///     Recursive Shuffler is a recursive version of
///     Fisher-Yates shuffle algorithm. This can only be used
///     for educational purposes due to stack depth limits.
/// </summary>
/// <typeparam name="T">Type array input.</typeparam>
public class RecursiveShuffler<T> : IShuffler<T>
{
    /// <summary>
    /// This is the public overload method that calls the private overload method.
    /// </summary>
    /// <param name="array">Array to shuffle.</param>
    /// <param name="seed">Random generator seed. Used to repeat the shuffle.</param>
    public void Shuffle(T[] array, int? seed = null)
    {
        Shuffle(array, array.Length - 1, seed);
    }

    /// <summary>
    /// First, it will check the length of the array on the base case.
    /// Next, if there's still items left, it will shuffle the sub-array.
    /// Lastly, it will randomly select index from 0 to number of items of the array
    /// then swap the elements array[items] and array[index].
    /// </summary>
    /// <param name="array">Array to shuffle.</param>
    /// <param name="items">Number of items in the array.</param>
    /// <param name="seed">Random generator seed. Used to repeat the shuffle.</param>
    private void Shuffle(T[] array, int items, int? seed)
    {
        if (items <= 0)
        {
            return;
        }

        Shuffle(array, items - 1, seed);
        var random = seed is null ? new Random() : new Random(seed.Value);
        int index = random.Next(items + 1);
        (array[items], array[index]) = (array[index], array[items]);
        (array[items], array[index]) = (array[index], array[items]);
    }
}

namespace Algorithms.Sorters.Comparison;

/// <summary>
/// A basic implementation of the TimSort algorithm for sorting arrays.
/// </summary>
/// <typeparam name="T">The type of elements in the array.</typeparam>
/// <remarks>
/// Initializes a new instance of the <see cref="BasicTimSorter{T}"/> class.
/// </remarks>
/// <param name="comparer">The comparer to use for comparing elements.</param>
public class BasicTimSorter<T>(IComparer<T> comparer)
{
    private readonly int minRuns = 32;
    private readonly IComparer<T> comparer = comparer ?? Comparer<T>.Default;

    /// <summary>
    /// Sorts the specified array using the TimSort algorithm.
    /// </summary>
    /// <param name="array">The array to sort.</param>
    public void Sort(T[] array)
    {
        var n = array.Length;

        // Step 1: Sort small pieces of the array using Insertion Sort
        for (var i = 0; i < n; i += minRuns)
        {
            InsertionSort(array, i, Math.Min(i + minRuns - 1, n - 1));
        }

        // Step 2: Merge sorted runs using Merge Sort
        for (var size = minRuns; size < n; size *= 2)
        {
            for (var left = 0; left < n; left += 2 * size)
            {
                var mid = left + size - 1;
                var right = Math.Min(left + 2 * size - 1, n - 1);

                if (mid < right)
                {
                    Merge(array, left, mid, right);
                }
            }
        }
    }

    /// <summary>
    /// Sorts a portion of the array using the Insertion Sort algorithm.
    /// </summary>
    /// <param name="array">The array to sort.</param>
    /// <param name="left">The starting index of the portion to sort.</param>
    /// <param name="right">The ending index of the portion to sort.</param>
    private void InsertionSort(T[] array, int left, int right)
    {
        for (var i = left + 1; i <= right; i++)
        {
            var key = array[i];
            var j = i - 1;

            // Move elements of array[0..i-1], that are greater than key,
            // to one position ahead of their current position
            while (j >= left && comparer.Compare(array[j], key) > 0)
            {
                array[j + 1] = array[j];
                j--;
            }

            array[j + 1] = key;
        }
    }

    /// <summary>
    /// Merges two sorted subarrays into a single sorted subarray.
    /// </summary>
    /// <param name="array">The array containing the subarrays to merge.</param>
    /// <param name="left">The starting index of the first subarray.</param>
    /// <param name="mid">The ending index of the first subarray.</param>
    /// <param name="right">The ending index of the second subarray.</param>
    private void Merge(T[] array, int left, int mid, int right)
    {
        // Create segments for left and right subarrays
        var leftSegment = new ArraySegment<T>(array, left, mid - left + 1);
        var rightSegment = new ArraySegment<T>(array, mid + 1, right - mid);

        // Convert segments to arrays
        var leftArray = leftSegment.ToArray();
        var rightArray = rightSegment.ToArray();

        var i = 0;
        var j = 0;
        var k = left;

        // Merge the two subarrays back into the main array
        while (i < leftArray.Length && j < rightArray.Length)
        {
            array[k++] = comparer.Compare(leftArray[i], rightArray[j]) <= 0 ? leftArray[i++] : rightArray[j++];
        }

        // Copy remaining elements from leftArray, if any
        while (i < leftArray.Length)
        {
            array[k++] = leftArray[i++];
        }

        // Copy remaining elements from rightArray, if any
        while (j < rightArray.Length)
        {
            array[k++] = rightArray[j++];
        }
    }
}

namespace Algorithms.Sorters.Comparison;

/// <summary>
///     Class that implements binary insertion sort algorithm.
/// </summary>
/// <typeparam name="T">Type of array element.</typeparam>
public class BinaryInsertionSorter<T> : IComparisonSorter<T>
{
    /// <summary>
    ///     Sorts array using specified comparer,
    ///     variant of insertion sort where binary search is used to find place for next element
    ///     internal, in-place, unstable,
    ///     time complexity: O(n^2),
    ///     space complexity: O(1),
    ///     where n - array length.
    /// </summary>
    /// <param name="array">Array to sort.</param>
    /// <param name="comparer">Compares elements.</param>
    public void Sort(T[] array, IComparer<T> comparer)
    {
        for (var i = 1; i < array.Length; i++)
        {
            var target = array[i];
            var moveIndex = i - 1;
            var targetInsertLocation = BinarySearch(array, 0, moveIndex, target, comparer);
            Array.Copy(array, targetInsertLocation, array, targetInsertLocation + 1, i - targetInsertLocation);

            array[targetInsertLocation] = target;
        }
    }

    /// <summary>Implementation of Binary Search using an iterative approach.</summary>
    /// <param name="array">
    ///     An array of values sorted in ascending order between the index values left and right to search
    ///     through.
    /// </param>
    /// <param name="from">Left index to search from (inclusive).</param>
    /// <param name="to">Right index to search to (inclusive).</param>
    /// <param name="target">The value to find placefor in the provided array.</param>
    /// <param name="comparer">Compares elements.</param>
    /// <returns>The index where to insert target value.</returns>
    private static int BinarySearch(T[] array, int from, int to, T target, IComparer<T> comparer)
    {
        var left = from;
        var right = to;
        while (right > left)
        {
            var middle = (left + right) / 2;
            var comparisonResult = comparer.Compare(target, array[middle]);

            if (comparisonResult == 0)
            {
                return middle + 1;
            }

            if (comparisonResult > 0)
            {
                left = middle + 1;
            }
            else
            {
                right = middle - 1;
            }
        }

        return comparer.Compare(target, array[left]) < 0 ? left : left + 1;
    }
}

namespace Algorithms.Sorters.Comparison;

/// <summary>
///     Class that implements bogo sort algorithm.
/// </summary>
/// <typeparam name="T">Type of array element.</typeparam>
public class BogoSorter<T> : IComparisonSorter<T>
{
    private readonly Random random = new();

    /// <summary>
    ///     Sorts array using specified comparer,
    ///     randomly shuffles elements until array is sorted,
    ///     internal, in-place, unstable,
    ///     worst-case time complexity: unbounded (infinite),
    ///     average time complexity: O((n+1)!),
    ///     space complexity: O(n),
    ///     where n - array length.
    /// </summary>
    /// <param name="array">Array to sort.</param>
    /// <param name="comparer">Compares elements.</param>
    public void Sort(T[] array, IComparer<T> comparer)
    {
        while (!IsSorted(array, comparer))
        {
            Shuffle(array);
        }
    }

    private bool IsSorted(T[] array, IComparer<T> comparer)
    {
        for (var i = 0; i < array.Length - 1; i++)
        {
            if (comparer.Compare(array[i], array[i + 1]) > 0)
            {
                return false;
            }
        }

        return true;
    }

    private void Shuffle(T[] array)
    {
        var taken = new bool[array.Length];
        var newArray = new T[array.Length];
        for (var i = 0; i < array.Length; i++)
        {
            int nextPos;
            do
            {
                nextPos = random.Next(0, int.MaxValue) % array.Length;
            }
            while (taken[nextPos]);

            taken[nextPos] = true;
            newArray[nextPos] = array[i];
        }

        for (var i = 0; i < array.Length; i++)
        {
            array[i] = newArray[i];
        }
    }
}

namespace Algorithms.Sorters.Comparison;

/// <summary>
///     Cocktail Sort is a variation of Bubble sort, where Cocktail
///     Sort traverses through a given array in both directions alternatively.
/// </summary>
/// <typeparam name="T">Array input type.</typeparam>
public class CocktailSorter<T> : IComparisonSorter<T>
{
    /// <summary>
    ///     Sorts array using Cocktail sort algorithm.
    /// </summary>
    /// <param name="array">Input array.</param>
    /// <param name="comparer">Type of comparer for array elements.</param>
    public void Sort(T[] array, IComparer<T> comparer) => CocktailSort(array, comparer);

    private static void CocktailSort(IList<T> array, IComparer<T> comparer)
    {
        var swapped = true;

        var startIndex = 0;
        var endIndex = array.Count - 1;

        while (swapped)
        {
            for (var i = startIndex; i < endIndex; i++)
            {
                if (comparer.Compare(array[i], array[i + 1]) != 1)
                {
                    continue;
                }

                var highValue = array[i];
                array[i] = array[i + 1];
                array[i + 1] = highValue;
            }

            endIndex--;
            swapped = false;

            for (var i = endIndex; i > startIndex; i--)
            {
                if (comparer.Compare(array[i], array[i - 1]) != -1)
                {
                    continue;
                }

                var highValue = array[i];
                array[i] = array[i - 1];
                array[i - 1] = highValue;

                swapped = true;
            }

            startIndex++;
        }
    }
}

namespace Algorithms.Sorters.Comparison;

/// <summary>
///     Comb sort is a relatively simple sorting algorithm that improves on bubble sort.
/// </summary>
/// <typeparam name="T">Type of array element.</typeparam>
public class CombSorter<T>(double shrinkFactor = 1.3) : IComparisonSorter<T>
{
    private double ShrinkFactor { get; } = shrinkFactor;

    /// <summary>
    ///     Sorts array using specified comparer,
    ///     internal, in-place, unstable,
    ///     worst case performance: O(n^2),
    ///     best case performance: O(n log(n)),
    ///     average performance: O(n^2 / 2^p),
    ///     space complexity: O(1),
    ///     where n - array length and p - number of increments.
    ///     See <a href="https://en.wikipedia.org/wiki/Comb_sort">here</a> for more info.
    /// </summary>
    /// <param name="array">Array to sort.</param>
    /// <param name="comparer">Compares elements.</param>
    public void Sort(T[] array, IComparer<T> comparer)
    {
        var gap = array.Length;
        var sorted = false;
        while (!sorted)
        {
            gap = (int)Math.Floor(gap / ShrinkFactor);
            if (gap <= 1)
            {
                gap = 1;
                sorted = true;
            }

            for (var i = 0; i < array.Length - gap; i++)
            {
                if (comparer.Compare(array[i], array[i + gap]) > 0)
                {
                    (array[i], array[i + gap]) = (array[i + gap], array[i]);
                    sorted = false;
                }
            }
        }
    }
}

namespace Algorithms.Sorters.Comparison;

/// <summary>
///     Cycle sort is an in-place, unstable sorting algorithm,
///     a comparison sort that is theoretically optimal in terms of the total
///     number of writes to the original array.
///     It is based on the idea that the permutation to be sorted can be factored
///     into cycles, which can individually be rotated to give a sorted result.
/// </summary>
/// <typeparam name="T">Type array input.</typeparam>
public class CycleSorter<T> : IComparisonSorter<T>
{
    /// <summary>
    ///     Sorts input array using Cycle sort.
    /// </summary>
    /// <param name="array">Input array.</param>
    /// <param name="comparer">Integer comparer.</param>
    public void Sort(T[] array, IComparer<T> comparer)
    {
        for (var i = 0; i < array.Length - 1; i++)
        {
            MoveCycle(array, i, comparer);
        }
    }

    private static void MoveCycle(T[] array, int startingIndex, IComparer<T> comparer)
    {
        var item = array[startingIndex];
        var pos = startingIndex + CountSmallerElements(array, startingIndex + 1, item, comparer);

        if (pos == startingIndex)
        {
            return;
        }

        pos = SkipSameElements(array, pos, item, comparer);

        var temp = array[pos];
        array[pos] = item;
        item = temp;

        while (pos != startingIndex)
        {
            pos = startingIndex + CountSmallerElements(array, startingIndex + 1, item, comparer);
            pos = SkipSameElements(array, pos, item, comparer);

            temp = array[pos];
            array[pos] = item;
            item = temp;
        }
    }

    private static int SkipSameElements(T[] array, int nextIndex, T item, IComparer<T> comparer)
    {
        while (comparer.Compare(array[nextIndex], item) == 0)
        {
            nextIndex++;
        }

        return nextIndex;
    }

    private static int CountSmallerElements(T[] array, int startingIndex, T element, IComparer<T> comparer)
    {
        var smallerElements = 0;
        for (var i = startingIndex; i < array.Length; i++)
        {
            if (comparer.Compare(array[i], element) < 0)
            {
                smallerElements++;
            }
        }

        return smallerElements;
    }
}

