namespace Algorithms.Sorters.String;

/// <summary>
///     Radix sort is a non-comparative sorting algorithm. It avoids comparison by creating
///     and distributing elements into buckets according to their radix.
///     Radix sorts can be implemented to start at either the most significant digit (MSD)
///     or least significant digit (LSD).
///     MSD radix sorts are most suitable for sorting array of strings with variable length
///     in lexicographical order.
/// </summary>
public class MsdRadixStringSorter : IStringSorter
{
    /// <summary>
    ///     Sort array of strings using MSD radix sort algorithm.
    /// </summary>
    /// <param name="array">Array to sort.</param>
    public void Sort(string[] array) => Sort(array, 0, array.Length - 1, 0, new string[array.Length]);

    private static void Sort(string[] array, int l, int r, int d, string[] temp)
    {
        if (l >= r)
        {
            return;
        }

        const int k = 256;

        var count = new int[k + 2];
        for (var i = l; i <= r; i++)
        {
            var j = Key(array[i]);
            count[j + 2]++;
        }

        for (var i = 1; i < count.Length; i++)
        {
            count[i] += count[i - 1];
        }

        for (var i = l; i <= r; i++)
        {
            var j = Key(array[i]);
            temp[count[j + 1]++] = array[i];
        }

        for (var i = l; i <= r; i++)
        {
            array[i] = temp[i - l];
        }

        for (var i = 0; i < k; i++)
        {
            Sort(array, l + count[i], l + count[i + 1] - 1, d + 1, temp);
        }

        int Key(string s) => d >= s.Length ? -1 : s[d];
    }
}

namespace Algorithms.Sorters.Utils;

public static class GallopingStrategy<T>
{
    public static int GallopLeft(T[] array, T key, int baseIndex, int length, IComparer<T> comparer)
    {
        if (array.Length == 0)
        {
            return 0;
        }

        var (offset, lastOfs) = comparer.Compare(key, array[baseIndex]) > 0
       ? RightRun(array, key, baseIndex, length, 0, comparer)
       : LeftRun(array, key, baseIndex, 0, comparer);

        return FinalOffset(array, key, baseIndex, offset, lastOfs, 1, comparer);
    }

    public static int GallopRight(T[] array, T key, int baseIndex, int length, IComparer<T> comparer)
    {
        if (array.Length == 0)
        {
            return 0;
        }

        var (offset, lastOfs) = comparer.Compare(key, array[baseIndex]) < 0
        ? LeftRun(array, key, baseIndex, length, comparer)
        : RightRun(array, key, baseIndex, length, 0, comparer);

        return FinalOffset(array, key, baseIndex, offset, lastOfs, 0, comparer);
    }

    public static int BoundLeftShift(int shiftable) => (shiftable << 1) < 0
    ? (shiftable << 1) + 1
    : int.MaxValue;

    private static (int Offset, int LastOfs) LeftRun(T[] array, T key, int baseIndex, int hint, IComparer<T> comparer)
    {
        var maxOfs = hint + 1;
        var (offset, tmp) = (1, 0);

        while (offset < maxOfs && comparer.Compare(key, array[baseIndex + hint - offset]) < 0)
        {
            tmp = offset;
            offset = BoundLeftShift(offset);
        }

        if (offset > maxOfs)
        {
            offset = maxOfs;
        }

        var lastOfs = hint - offset;
        offset = hint - tmp;

        return (offset, lastOfs);
    }

    private static (int Offset, int LastOfs) RightRun(T[] array, T key, int baseIndex, int len, int hint, IComparer<T> comparer)
    {
        var (offset, lastOfs) = (1, 0);
        var maxOfs = len - hint;
        while (offset < maxOfs && comparer.Compare(key, array[baseIndex + hint + offset]) > 0)
        {
            lastOfs = offset;
            offset = BoundLeftShift(offset);
        }

        if (offset > maxOfs)
        {
            offset = maxOfs;
        }

        offset += hint;
        lastOfs += hint;

        return (offset, lastOfs);
    }

    private static int FinalOffset(T[] array, T key, int baseIndex, int offset, int lastOfs, int lt, IComparer<T> comparer)
    {
        lastOfs++;
        while (lastOfs < offset)
        {
            var m = lastOfs + (int)((uint)(offset - lastOfs) >> 1);

            if (comparer.Compare(key, array[baseIndex + m]) < lt)
            {
                offset = m;
            }
            else
            {
                lastOfs = m + 1;
            }
        }

        return offset;
    }
}

namespace Algorithms.Stack;

/// <summary>
///     It checks if an expression has matching and balanced parentheses.
/// @author Mohit Singh. <a href="https://github.com/mohit-gogitter">mohit-gogitter</a>
/// </summary>
public class BalancedParenthesesChecker
{
    private static readonly Dictionary<char, char> ParenthesesMap = new Dictionary<char, char>
        {
            { '(', ')' },
            { '{', '}' },
            { '[', ']' },
        };

    /// <summary>
    /// Determines if a given string expression containing brackets is balanced.
    /// A string is considered balanced if all opening brackets have corresponding closing brackets
    /// in the correct order. The supported brackets are '()', '{}', and '[]'.
    /// </summary>
    /// <param name="expression">
    /// The input string expression containing the brackets to check for balance.
    /// </param>
    /// <returns>
    /// <c>true</c> if the brackets in the expression are balanced; otherwise, <c>false</c>.
    /// </returns>
    /// <exception cref="ArgumentException">
    /// Thrown when the input expression contains invalid characters or is null/empty.
    /// Only '(', ')', '{', '}', '[', ']' characters are allowed.
    /// </exception>
    public bool IsBalanced(string expression)
    {
        if (string.IsNullOrEmpty(expression))
        {
            throw new ArgumentException("The input expression cannot be null or empty.");
        }

        Stack<char> stack = new Stack<char>();
        foreach (char c in expression)
        {
            if (IsOpeningParenthesis(c))
            {
                stack.Push(c);
            }
            else if (IsClosingParenthesis(c))
            {
                if (!IsBalancedClosing(stack, c))
                {
                    return false;
                }
            }
            else
            {
                throw new ArgumentException($"Invalid character '{c}' found in the expression.");
            }
        }

        return stack.Count == 0;
    }

    private static bool IsOpeningParenthesis(char c)
    {
        return c == '(' || c == '{' || c == '[';
    }

    private static bool IsClosingParenthesis(char c)
    {
        return c == ')' || c == '}' || c == ']';
    }

    private static bool IsBalancedClosing(Stack<char> stack, char close)
    {
        if (stack.Count == 0)
        {
            return false;
        }

        char open = stack.Pop();
        return IsMatchingPair(open, close);
    }

    private static bool IsMatchingPair(char open, char close)
    {
        return ParenthesesMap.ContainsKey(open) && ParenthesesMap[open] == close;
    }
}

using System;
using System.Diagnostics.CodeAnalysis;

namespace Algorithms.Stack
{
    /// <summary>
    /// The Code focuses on Converting an Infix Expression to a Postfix Expression and Evaluates the value for the expression.
    /// @author Aalok Choudhari. <a href="https://github.com/kaloa2025">kaloa2025</a>
    /// </summary>
    public static class InfixToPostfix
    {
        /// <summary>
        /// <param name="initialInfixExpression"> Infix Expression String to Convert.</param>
        /// <returns>Postfix Expression.</returns>
        /// <exception cref="ArgumentException">
        /// Thrown when the input expression contains invalid characters or is null/empty.
        /// Only following characters are allowed : Parentheses['(',')'], Operands[a-z,A-Z,0-9], Operators['+','-','*','/','^'].
        /// </exception>
        /// </summary>
        public static string InfixToPostfixConversion(string initialInfixExpression)
        {
            ValidateInfix(initialInfixExpression);

            Stack<char> stack = new Stack<char>();
            StringBuilder postfixExpression = new StringBuilder();

            foreach (char c in initialInfixExpression)
            {
                if (char.IsWhiteSpace(c))
                {
                    continue;
                }

                if (!IsValidCharacter(c))
                {
                    throw new ArgumentException($"Invalid character {c}.");
                }

                ProcessInfixCharacter(c, stack, postfixExpression);
            }

            EmptyRemainingStack(stack, postfixExpression);
            return postfixExpression.ToString();
        }

        /// <summary>
        /// <param name="postfixExpression"> Postfix Expression String to Evaluate.</param>
        /// <returns>Postfix Expression's Calculated value.</returns>
        /// <exception cref="ArgumentException">
        /// Thrown when the input expression contains invalid characters or is null/empty.
        /// </exception>
        /// <exception cref="InvalidOperationException">
        /// Validates expression to have sufficient operands for performing operation.
        /// </exception>
        /// </summary>
        public static int PostfixExpressionEvaluation(string postfixExpression)
        {
            ValidatePostfix(postfixExpression);

            Stack<int> stack = new Stack<int>();
            foreach (char ch in postfixExpression)
            {
                if(char.IsWhiteSpace(ch))
                {
                    continue;
                }

                if(char.IsDigit(ch))
                {
                    stack.Push(ch - '0');
                    continue;
                }

                if (IsOperator(ch))
                {
                    EvaluateOperator(stack, ch);
                    continue;
                }

                throw new InvalidOperationException($"Invalid character in expression: {ch}");
            }

            if (stack.Count != 1)
            {
                throw new InvalidOperationException("Invalid postfix expression: Leftover operands.");
            }

            return stack.Pop();
        }

        private static void ProcessInfixCharacter(char c, Stack<char> stack, StringBuilder postfixExpression)
        {
            if (IsOperand(c))
            {
                postfixExpression.Append(c);
                return;
            }

            if (c == '(')
            {
                stack.Push(c);
                return;
            }

            if (c == ')')
            {
                ProcessClosingParenthesis(stack, postfixExpression);
                return;
            }

            ProcessOperator(c, stack, postfixExpression);
        }

        private static void ProcessClosingParenthesis(Stack<char> stack, StringBuilder postfixExpression)
        {
            while (stack.Count > 0 && stack.Peek() != '(')
            {
                postfixExpression.Append(stack.Pop());
            }

            if (stack.Count == 0)
            {
                throw new InvalidOperationException("Mismatched parentheses in expression.");
            }

            stack.Pop();
        }

        private static void ProcessOperator(char c, Stack<char> stack, StringBuilder postfixExpression)
        {
            while (stack.Count > 0 && stack.Peek() != '(' && Precedence(stack.Peek()) >= Precedence(c))
            {
                postfixExpression.Append(stack.Pop());
            }

            stack.Push(c);
        }

        private static void EmptyRemainingStack(Stack<char> stack, StringBuilder postfix)
        {
            while (stack.Count > 0)
            {
                if (stack.Peek() is '(' or ')')
                {
                    throw new InvalidOperationException("Mismatched parentheses.");
                }

                postfix.Append(stack.Pop());
            }
        }

        private static void EvaluateOperator(Stack<int> stack, char op)
        {
            if (stack.Count < 2)
            {
                throw new InvalidOperationException("Insufficient operands");
            }

            int b = stack.Pop();
            int a = stack.Pop();

            if (op == '/' && b == 0)
            {
                throw new DivideByZeroException("Cannot divide by zero");
            }

            int result = op switch
            {
                '+' => a + b,
                '-' => a - b,
                '*' => a * b,
                '/' => a / b,
                '^' => (int)Math.Pow(a, b),
                _ => throw new InvalidOperationException($"Unknown operator {op}"),
            };

            stack.Push(result);
        }

        private static void ValidateInfix(string expr)
        {
            if (string.IsNullOrEmpty(expr) || string.IsNullOrWhiteSpace(expr))
            {
                throw new ArgumentException("Infix cannot be null or empty.");
            }
        }

        private static void ValidatePostfix(string expr)
        {
            if (string.IsNullOrEmpty(expr) || string.IsNullOrWhiteSpace(expr))
            {
                throw new ArgumentException("Postfix cannot be null or empty.");
            }
        }

        /// <summary>
        /// Decided Operator Precedence.
        /// <param name="operatorChar"> Operator character whose precedence is asked.</param>
        /// <returns>Precedence rank of parameter operator character.</returns>
        /// </summary>
        [ExcludeFromCodeCoverage]
        private static int Precedence(char operatorChar)
        {
            if (operatorChar == '^')
            {
                return 3;
            }

            if (operatorChar == '*' || operatorChar == '/')
            {
                return 2;
            }

            if (operatorChar == '+' || operatorChar == '-')
            {
                return 1;
            }

            return 0;
        }

        /// <summary>
        /// Checks for character if its an Operand.
        /// <param name="ch"> Character asked to verify whether its an operand.</param>
        /// <returns>True if its a digit or a Letter.</returns>
        /// </summary>
        private static bool IsOperand(char ch) => char.IsLetterOrDigit(ch);

        private static readonly HashSet<char> Operators = new() { '+', '-', '*', '/', '^' };

        /// <summary>
        /// Checks Operator.
        /// <param name="ch"> Character asked to verify whether its an operator.</param>
        /// <returns>True if its allowded operator character.</returns>
        /// </summary>
        private static bool IsOperator(char ch) => Operators.Contains(ch);

        /// <summary>
        /// Checks Valid Character.
        /// <param name="c"> Character asked to verify whether its an valid Character for expression.</param>
        /// <returns>True if its allowded character.</returns>
        /// </summary>
        private static bool IsValidCharacter(char c) => IsOperand(c) || IsOperator(c) || IsParenthesis(c);

        private static bool IsParenthesis(char c) => c == '(' || c == ')';
    }
}

namespace Algorithms.Stack;

/// <summary>
///     For each element in an array, the utility finds the next greater element on the right side using a stack.
/// @author Mohit Singh. <a href="https://github.com/mohit-gogitter">mohit-gogitter</a>
/// </summary>
public class NextGreaterElement
{
    /// <summary>
    /// Finds the next greater element for each element in the input array.
    /// The next greater element for an element x is the first element greater than x to its right.
    /// If there is no greater element, -1 is returned for that element.
    /// </summary>
    /// <param name="nums">The array of integers to find the next greater elements for.</param>
    /// <returns>An array where each index contains the next greater element of the corresponding element in the input array, or -1 if no such element exists.</returns>
    /// <exception cref="ArgumentNullException">Thrown when the input array is null.</exception>
    public int[] FindNextGreaterElement(int[] nums)
    {
        int[] result = new int[nums.Length];
        Stack<int> stack = new Stack<int>();

        // Initialize all elements in the result array to -1
        for (int i = 0; i < nums.Length; i++)
        {
            result[i] = -1;
        }

        for (int i = 0; i < nums.Length; i++)
        {
            // While the stack is not empty and the current element is greater than the element
            // corresponding to the index stored at the top of the stack
            while (stack.Count > 0 && nums[i] > nums[stack.Peek()])
            {
                int index = stack.Pop();
                result[index] = nums[i]; // Set the next greater element
            }

            stack.Push(i); // Push current index to stack
        }

        return result;
    }
}

namespace Algorithms.Stack;

/// <summary>
///     Reverses the elements in a stack using recursion.
/// @author Mohit Singh. <a href="https://github.com/mohit-gogitter">mohit-gogitter</a>
/// </summary>
public class ReverseStack
{
    /// <summary>
    /// Recursively reverses the elements of the specified stack.
    /// </summary>
    /// <typeparam name="T">The type of elements in the stack.</typeparam>
    /// <param name="stack">The stack to be reversed. This parameter cannot be null.</param>
    /// <exception cref="ArgumentNullException">Thrown when the stack parameter is null.</exception>
    public void Reverse<T>(Stack<T> stack)
    {
        if (stack.Count == 0)
        {
            return;
        }

        T temp = stack.Pop();
        Reverse(stack);
        InsertAtBottom(stack, temp);
    }

    private void InsertAtBottom<T>(Stack<T> stack, T value)
    {
        if (stack.Count == 0)
        {
            stack.Push(value);
        }
        else
        {
            T temp = stack.Pop();
            InsertAtBottom(stack, value);
            stack.Push(temp);
        }
    }
}

namespace Algorithms.Strings;

/// <summary>
///     Implements simple algorithms on strings.
/// </summary>
public static class GeneralStringAlgorithms
{
    /// <summary>
    ///     Finds character that creates longest consecutive substring with single character.
    /// </summary>
    /// <param name="input">String to find in.</param>
    /// <returns>Tuple containing char and number of times it appeared in a row.</returns>
    public static Tuple<char, int> FindLongestConsecutiveCharacters(string input)
    {
        var maxChar = input[0];

        var max = 1;
        var current = 1;

        for (var i = 1; i < input.Length; i++)
        {
            if (input[i] == input[i - 1])
            {
                current++;
                if (current > max)
                {
                    max = current;
                    maxChar = input[i];
                }
            }
            else
            {
                current = 1;
            }
        }

        return new Tuple<char, int>(maxChar, max);
    }
}

namespace Algorithms.Strings;

/// <summary>
///     Manacher's Algorithm is used to find the longest palindromic substring in linear time O(n).
///     This algorithm is significantly more efficient than the naive O(n²) approach.
///
///     KEY CONCEPTS:
///     1. String Transformation: Inserts special characters to handle even/odd palindromes uniformly.
///     2. Palindrome Radius: For each position, stores how far the palindrome extends.
///     3. Center Expansion: Expands around each potential center to find palindromes.
///     4. Symmetry Property: Uses previously computed palindrome information to skip redundant checks.
///     5. Right Boundary Tracking: Maintains the rightmost boundary of any palindrome found.
///
///     WHY IT'S FAST:
///     The algorithm achieves O(n) time by ensuring each character is examined at most twice:
///     - Once when it's inside a known palindrome (using mirror property).
///     - Once when expanding beyond the known boundary.
///
///     Reference: "A New Linear-Time On-Line Algorithm for Finding the Smallest Initial Palindrome of a String"
///     by Glenn Manacher (1975), Journal of the ACM.
/// </summary>
public static class ManachersAlgorithm
{
    /// <summary>
    ///     Finds the longest palindromic substring using Manacher's Algorithm.
    ///
    ///     ALGORITHM STEPS:
    ///     1. PREPROCESSING: Transform "abc" to "^#a#b#c#$" to handle even/odd palindromes uniformly.
    ///        - ^ and $ are sentinels that prevent boundary checks.
    ///        - # characters create uniform spacing.
    ///
    ///     2. INITIALIZATION: Set up tracking variables.
    ///        - palindromeRadii[i]: How far palindrome extends from position i.
    ///        - center: Center of rightmost palindrome found.
    ///        - rightBoundary: Right edge of rightmost palindrome.
    ///
    ///     3. MAIN LOOP: For each position i in transformed string.
    ///        a) If i is within rightBoundary, use mirror property:
    ///           - mirror = 2 * center - i (symmetric position).
    ///           - Start with min(palindromeRadii[mirror], rightBoundary - i).
    ///        b) Expand palindrome by comparing characters on both sides.
    ///        c) Update center and rightBoundary if palindrome extends further right.
    ///        d) Track the longest palindrome found.
    ///
    ///     4. EXTRACTION: Convert transformed coordinates back to original string.
    ///
    ///     Time Complexity: O(n) - Each character examined at most twice.
    ///     Space Complexity: O(n) - For transformed string and radius array.
    /// </summary>
    /// <param name="input">The input string to search for palindromes.</param>
    /// <returns>The longest palindromic substring found in the input.</returns>
    /// <exception cref="ArgumentException">Thrown when the input string is null.</exception>
    /// <example>
    ///     Input: "babad".
    ///     Output: "bab" or "aba" (both are valid longest palindromes with length 3).
    ///
    ///     Detailed Example:
    ///     Input: "abaxyz".
    ///     Transformed: "^#a#b#a#x#y#z#$".
    ///     Process finds "aba" at indices 1-3 with radius 3 in transformed string.
    ///     Maps back to indices 0-2 in original string.
    ///     Output: "aba".
    /// </example>
    public static string FindLongestPalindrome(string input)
    {
        // Validate input
        if (input == null)
        {
            throw new ArgumentException("Input string cannot be null.", nameof(input));
        }

        // Handle edge cases
        if (input.Length == 0)
        {
            return string.Empty;
        }

        if (input.Length == 1)
        {
            return input;
        }

        // STEP 1: Transform the string to handle even-length palindromes uniformly
        // Example: "abc" becomes "^#a#b#c#$"
        //
        // WHY THIS WORKS:
        // - Original "aba" (odd): Center is 'b' at index 1.
        // - Original "abba" (even): No single center character.
        // - Transformed "#a#b#b#a#": Both have clear centers (the middle #).
        //
        // SENTINELS (^ and $):
        // - Prevent index out of bounds during expansion.
        // - Never match any character, so expansion stops naturally.
        string transformed = PreprocessString(input);
        int n = transformed.Length;

        // STEP 2: Initialize data structures

        // palindromeRadii[i] = radius of palindrome centered at position i.
        // Example: If transformed[i] is center of "#a#b#a#", radius = 3.
        // (3 characters on each side match).
        int[] palindromeRadii = new int[n];

        // Track the rightmost palindrome boundary for optimization.
        // center: Position of the palindrome that extends furthest right.
        // rightBoundary: The rightmost index covered by that palindrome.
        // These help us use symmetry to avoid redundant comparisons.
        int center = 0;
        int rightBoundary = 0;

        // Track the longest palindrome found during the scan.
        // maxLength: Radius of the longest palindrome.
        // maxCenter: Position where the longest palindrome is centered.
        int maxLength = 0;
        int maxCenter = 0;

        // STEP 3: Process each position in the transformed string.
        // Skip first and last positions (sentinels ^ and $).
        for (int i = 1; i < n - 1; i++)
        {
            // OPTIMIZATION: Use mirror property for positions within known palindrome
            //
            // If we have a palindrome centered at 'center' extending to 'rightBoundary':
            //     center - radius ... center ... center + radius
            //                 mirror    i
            //
            // The mirror position reflects i across the center:
            // mirror = center - (i - center) = 2 * center - i.
            int mirror = 2 * center - i;

            // KEY INSIGHT: If i is within rightBoundary, we can use symmetry.
            // The palindrome at position i might be similar to the one at mirror position.
            if (i < rightBoundary)
            {
                // We can safely copy the radius from the mirror position, BUT:
                // 1. palindromeRadii[mirror]: What we know from the mirror side.
                // 2. rightBoundary - i: We can't assume anything beyond rightBoundary.
                //
                // Take the minimum because:
                // - If mirror's palindrome fits within bounds, we can use it.
                // - If it extends beyond, we only know up to rightBoundary.
                palindromeRadii[i] = Math.Min(rightBoundary - i, palindromeRadii[mirror]);
            }

            // EXPANSION PHASE: Try to extend the palindrome further.
            // We start from palindromeRadii[i] (not 0) to avoid redundant checks.
            // This is why the algorithm is O(n) - we never re-check characters.
            //
            // Example: If palindromeRadii[i] = 2, we already know:
            // transformed[i-2] == transformed[i+2] and
            // transformed[i-1] == transformed[i+1].
            // So we start checking at distance 3.
            //
            // The sentinels (^ and $) guarantee we never go out of bounds.
            // Expansion stops naturally when characters don't match.
            while (transformed[i + palindromeRadii[i] + 1] == transformed[i - palindromeRadii[i] - 1])
            {
                palindromeRadii[i]++;
            }

            // UPDATE TRACKING: If this palindrome extends further right than any before.
            //
            // WHY THIS MATTERS:
            // By tracking the rightmost boundary, we can use the mirror property
            // for future positions, avoiding redundant character comparisons.
            //
            // Example: If we find a large palindrome early, all positions within it
            // can benefit from the symmetry property.
            if (i + palindromeRadii[i] > rightBoundary)
            {
                center = i;  // This position is now our reference center.
                rightBoundary = i + palindromeRadii[i];  // Update the rightmost boundary.
            }

            // TRACK MAXIMUM: Remember the longest palindrome found so far.
            // We need both the length and position to extract it later.
            if (palindromeRadii[i] > maxLength)
            {
                maxLength = palindromeRadii[i];  // Radius of longest palindrome.
                maxCenter = i;  // Where it's centered in transformed string.
            }
        }

        // STEP 4: Extract the longest palindrome from the original string.
        //
        // COORDINATE MAPPING:
        // Transformed string has format: ^#a#b#c#$.
        // Position in transformed -> Position in original: (pos - 1) / 2.
        //
        // Example: "aba" -> "^#a#b#a#$".
        // - maxCenter = 4 (the middle 'b' in transformed).
        // - maxLength = 3 (radius).
        // - Original center = (4 - 1) / 2 = 1 (index of 'b' in "aba").
        // - Start = (maxCenter - maxLength) / 2 = (4 - 3) / 2 = 0.
        // - Length = maxLength = 3.
        // - Result: input.Substring(0, 3) = "aba".
        int start = (maxCenter - maxLength) / 2;
        return input.Substring(start, maxLength);
    }

    /// <summary>
    ///     Finds the longest palindromic substring and returns detailed information.
    ///     This method provides more detailed information than FindLongestPalindrome,
    ///     including the exact starting position and length in the original string.
    ///
    ///     USE CASE:
    ///     When you need to know WHERE the palindrome is located, not just what it is.
    ///     Useful for highlighting, replacing, or further processing the palindrome.
    /// </summary>
    /// <param name="input">The input string to search for palindromes.</param>
    /// <returns>
    ///     A tuple containing:
    ///     - The longest palindromic substring
    ///     - The starting index of the longest palindrome in the original string
    ///     - The length of the longest palindrome.
    /// </returns>
    /// <exception cref="ArgumentException">Thrown when the input string is null.</exception>
    /// <example>
    ///     Input: "babad".
    ///     Output: (Palindrome: "bab", StartIndex: 0, Length: 3).
    /// </example>
    public static (string Palindrome, int StartIndex, int Length) FindLongestPalindromeWithDetails(string input)
    {
        // Validate input
        if (input == null)
        {
            throw new ArgumentException("Input string cannot be null.", nameof(input));
        }

        // Handle edge cases
        if (input.Length == 0)
        {
            return (string.Empty, 0, 0);
        }

        if (input.Length == 1)
        {
            return (input, 0, 1);
        }

        // Apply the same algorithm as FindLongestPalindrome.
        // (See detailed comments in that method for step-by-step explanation).
        string transformed = PreprocessString(input);
        int n = transformed.Length;
        int[] palindromeRadii = new int[n];
        int center = 0;
        int rightBoundary = 0;
        int maxLength = 0;
        int maxCenter = 0;

        // Main algorithm loop
        for (int i = 1; i < n - 1; i++)
        {
            // Use mirror property if within known palindrome.
            int mirror = 2 * center - i;

            if (i < rightBoundary)
            {
                palindromeRadii[i] = Math.Min(rightBoundary - i, palindromeRadii[mirror]);
            }

            // Expand palindrome.
            // Sentinels guarantee no out-of-bounds access.
            while (transformed[i + palindromeRadii[i] + 1] == transformed[i - palindromeRadii[i] - 1])
            {
                palindromeRadii[i]++;
            }

            // Update rightmost boundary.
            if (i + palindromeRadii[i] > rightBoundary)
            {
                center = i;
                rightBoundary = i + palindromeRadii[i];
            }

            // Track maximum.
            if (palindromeRadii[i] > maxLength)
            {
                maxLength = palindromeRadii[i];
                maxCenter = i;
            }
        }

        // Calculate the start index and extract the palindrome.
        // Map from transformed coordinates to original string coordinates.
        int startIndex = (maxCenter - maxLength) / 2;
        string palindrome = input.Substring(startIndex, maxLength);

        // Return all three pieces of information.
        return (palindrome, startIndex, maxLength);
    }

    /// <summary>
    ///     Checks if the entire string is a palindrome using Manacher's Algorithm.
    ///
    ///     EFFICIENCY:
    ///     - This approach: O(n) time using Manacher's algorithm.
    ///     - Naive approach: O(n) time for reversing + O(n) for comparison.
    ///     - Both are O(n), but this avoids creating a reversed copy.
    ///
    ///     LOGIC:
    ///     If the longest palindrome in the string equals the string length,
    ///     then the entire string must be a palindrome.
    /// </summary>
    /// <param name="input">The string to check.</param>
    /// <returns>True if the entire string is a palindrome, false otherwise.</returns>
    /// <exception cref="ArgumentException">Thrown when the input string is null.</exception>
    /// <example>
    ///     Input: "racecar".
    ///     Output: true.
    /// </example>
    public static bool IsPalindrome(string input)
    {
        if (input == null)
        {
            throw new ArgumentException("Input string cannot be null.", nameof(input));
        }

        // Strings of length 0 or 1 are always palindromes.
        if (input.Length <= 1)
        {
            return true;
        }

        // Find the longest palindrome in the string.
        // If it spans the entire string, then the string is a palindrome.
        var (_, _, length) = FindLongestPalindromeWithDetails(input);
        return length == input.Length;
    }

    /// <summary>
    ///     Preprocesses the input string by inserting special characters.
    ///     This transformation is the KEY to making Manacher's algorithm work efficiently.
    ///
    ///     PROBLEM IT SOLVES:
    ///     - Odd-length palindromes ("aba") have a center character.
    ///     - Even-length palindromes ("abba") have a center between characters.
    ///     - Without transformation, we'd need separate logic for each case.
    ///
    ///     SOLUTION:
    ///     Insert '#' between every character, making all palindromes odd-length.
    ///
    ///     EXAMPLES:
    ///     - "aba" (odd) -> "^#a#b#a#$" (center is 'b').
    ///     - "abba" (even) -> "^#a#b#b#a#$" (center is '#' between the two 'b's).
    ///
    ///     SENTINELS (^ and $):
    ///     - Placed at start and end.
    ///     - Never match any character (including each other).
    ///     - Automatically stop expansion without explicit boundary checks.
    ///     - Prevent IndexOutOfBoundsException.
    ///
    ///     COORDINATE MAPPING:
    ///     - Original index i maps to transformed index (2*i + 2).
    ///     - Transformed index j maps to original index (j - 1) / 2.
    /// </summary>
    /// <param name="input">The original input string.</param>
    /// <returns>The transformed string with inserted special characters.</returns>
    private static string PreprocessString(string input)
    {
        // Calculate the size of transformed string.
        // Original: n characters.
        // Transformed: ^ + # + (n chars with # between each) + # + $.
        // Total: 1 + 1 + n + (n-1) + 1 + 1 = 2n + 3.
        int n = input.Length;
        char[] transformed = new char[n * 2 + 3];

        // Place sentinels at boundaries.
        transformed[0] = '^'; // Start sentinel (never matches anything).
        transformed[n * 2 + 2] = '$'; // End sentinel (never matches anything).

        // Build the transformed string: #a#b#c#.
        // For input "abc":
        // Position 0: ^ (sentinel).
        // Position 1: # (separator).
        // Position 2: a (input[0]).
        // Position 3: # (separator).
        // Position 4: b (input[1]).
        // Position 5: # (separator).
        // Position 6: c (input[2]).
        // Position 7: # (separator).
        // Position 8: $ (sentinel).
        for (int i = 0; i < n; i++)
        {
            transformed[2 * i + 1] = '#';  // Separator before character.
            transformed[2 * i + 2] = input[i];  // Original character.
        }

        transformed[n * 2 + 1] = '#';  // Final separator.

        return new string(transformed);
    }
}

namespace Algorithms.Strings;

/// <summary>
///     Palindrome a series of characters or a string that when reversed,
///     equals the original string.
/// </summary>
public static class Palindrome
{
    /// <summary>
    ///     Function to check if a string is a palindrome.
    /// </summary>
    /// <param name="word">String being checked.</param>
    public static bool IsStringPalindrome(string word) =>
        TypifyString(word).Equals(TypifyString(ReverseString(word)));

    /// <summary>
    ///     Typify string to lower and remove white spaces.
    /// </summary>
    /// <param name="word">String to remove spaces.</param>
    /// <returns>Returns original string without spaces.</returns>
    private static string TypifyString(string word) =>
        Regex.Replace(word.ToLowerInvariant(), @"\s+", string.Empty);

    /// <summary>
    ///     Helper function that returns a reversed string inputed.
    /// </summary>
    /// <param name="s">String to be reversed.</param>
    /// <returns>Returns s reversed.</returns>
    private static string ReverseString(string s)
    {
        var arr = s.ToCharArray();
        Array.Reverse(arr);
        return new string(arr);
    }
}

namespace Algorithms.Strings.PatternMatching;

/// <summary>
/// The Bitap algorithm is a fuzzy string matching technique. It ains to find approximate matches of a pattern within a
/// text, allowing for a certain degree of mismatch (e.g., mistypes, minor variations etc.). It's knowd for its efficiency,
/// using bitwise operations for fast comparisons.
///
/// <para>
/// <b>How it works:</b>
/// <list type="number">
/// <item>
/// <term>Initialization</term>
/// <description>
/// Bitmasks are created for each character in the pattern. These bitmasks are essentially binary numbers where each bit
/// represents a specific character's position within the pattern. An initial state variable <c>R</c> is set to all 1s,
/// indicating that all characters in the pattern are initially unmatched.
/// </description>
/// </item>
/// <item>
/// <term>Iteration</term>
/// <description>
/// The algorithm iterates through each character in the text. For each character, the state <c>R</c> is updated using
/// bitwise operations (shifts and logical ORs). This update reflects whether the current character in the text matches
/// the corresponding character in the pattern.
/// </description>
/// </item>
/// <item>
/// <term>Matching</term>
/// <description>
/// After each iteration, the algorithm checks if the least significant bit of <c>R</c> is set to 1.
/// If it is, it means there's a potential match at that position, with a mismatch distance that's within the allowed
/// threshold.
/// </description>
/// </item>
/// </list>
/// </para>
/// <para>
/// <b> Finding Matches </b>
/// </para>
/// <para>
/// If the least significant bit of <c>R</c> is 1, it means a potential match is found.
/// The number of leading zeros in <c>R</c> indicates the mismatch distance.
/// If this distance is within the allowed threshold, it's considered a valid match.
/// </para>
/// </summary>
public static class Bitap
{
    /// <summary>
    /// <para>
    /// This function implements the Bitap algorithm for finding exact matches of a pattern within a text.
    /// It aims to find the first occurrence of the pattern in the text, allowing for no mismatches.
    /// </para>
    /// <para>
    /// The algorithm iterates through each character in the text. For each character, the state <c>R</c> is updated using
    /// bitwise operations (shifts and logical ORs). This update reflects whether the current character in the text matches
    /// the corresponding character in the pattern.
    /// </para>
    /// <para>
    /// After each iteration, the algorithm checks if the least significant bit of <c>R</c> is set to 1.
    /// If it is, it means there's a potential match at that position, with a mismatch distance of 0.
    /// The function returns the index of the first occurrence of the pattern in the text, or -1 if not found.
    /// </para>
    /// <para>
    /// The function throws an <see cref="ArgumentException"/> if the pattern is longer than 31 characters.
    /// This is because the maximum length of the pattern is 31, because if it's longer than that,
    /// we won't be able to represent the pattern mask in an int.
    /// </para>
    /// </summary>
    /// <param name="text">The text to search in.</param>
    /// <param name="pattern">The pattern to search for.</param>
    /// <returns>The index of the first occurrence of the pattern in the text, or -1 if not found.</returns>
    /// <exception cref="ArgumentException">The pattern is longer than 31 characters.</exception>
    public static int FindExactPattern(string text, string pattern)
    {
        // The length of the pattern.
        var len = pattern.Length;

        // An array of integers that will be used to mask the pattern.
        // The pattern mask is a bitmask that we will use to search for the pattern characters
        // in the text. We'll set the bit corresponding to the character in the pattern
        // to 0, and then use bitwise operations to check for the pattern.
        var patternMask = new int[128];
        int index;

        // Check if the pattern is empty.
        if (string.IsNullOrEmpty(pattern))
        {
            return 0;
        }

        // Check if the pattern is longer than 31 characters.
        if (len > 31)
        {
            throw new ArgumentException("The pattern is longer than 31 characters.");
        }

        // Initialize the register <c>R</c> to all 1s.
        var r = ~1;

        // Initialize the pattern mask to all 1s.
        for (index = 0; index <= 127; ++index)
        {
            patternMask[index] = ~0;
        }

        // Set the bits corresponding to the characters in the pattern to 0 in the pattern mask.
        for (index = 0; index < len; ++index)
        {
            patternMask[pattern[index]] &= ~(1 << index);
        }

        // Iterate through each character in the text.
        for (index = 0; index < text.Length; ++index)
        {
            // Update the state <c>R</c> by ORing the pattern mask with the character in the text,
            // and then shift it to the left by 1.
            r |= patternMask[text[index]];
            r <<= 1;

            // Check if the least significant bit of <c>R</c> is set to 1.
            // If there's a potential match at that position, with a mismatch distance of 0,
            // return the index of the first occurrence of the pattern in the text.
            if ((r & 1 << len) == 0)
            {
                return index - len + 1;
            }
        }

        // If no match is found, return -1.
        return -1;
    }

    /// <summary>
    /// Finds the first occurrence of a pattern in a given text with a given threshold for mismatches.
    /// </summary>
    /// <param name="text">The text to search in.</param>
    /// <param name="pattern">The pattern to search for.</param>
    /// <param name="threshold">The maximum number of mismatches allowed.</param>
    /// <returns>The index of the first occurrence of the pattern in the text, or -1 if not found.</returns>
    public static int FindFuzzyPattern(string text, string pattern, int threshold)
    {
        // Create a pattern mask for each character in the pattern.
        // The pattern mask is a bitmask that we will use to search for the pattern characters
        // in the text. We'll set the bit corresponding to the character in the pattern
        // to 0, and then use bitwise operations to check for the pattern.
        var patternMask = new int[128];

        // Create a register array.
        // The register array is used to keep track of the pattern mask as we search for the pattern.
        // We'll start with a register that has all bits set to 1, because all bits in the pattern mask
        // will be set to 1 initially.
        var r = new int[(threshold + 1) * sizeof(int)];

        var len = pattern.Length;

        // Check for empty strings.
        // If the text is empty, return 0.
        // If the pattern is empty, return 0.
        if (string.IsNullOrEmpty(text))
        {
            return 0;
        }

        if (string.IsNullOrEmpty(pattern))
        {
            return 0;
        }

        // Check for a pattern that is too long.
        // If the pattern is longer than 31 characters, return -1.
        // The maximum length of the pattern is 31, because if it's longer than that,
        // we won't be able to represent the pattern mask in an int.
        if (len > 31)
        {
            return -1;
        }

        // Initialize the register.
        // Set the least significant bit in the register to 0 or 1
        // depending on whether the current character in the text matches the pattern.
        // This will make it easier to check for the pattern later.
        for (var i = 0; i <= threshold; ++i)
        {
            r[i] = ~1;
        }

        // Initialize the pattern mask.
        // Set the bit corresponding to each character in the pattern to 0 in the pattern mask.
        // This will make it easier to check for the pattern later.
        for (var i = 0; i <= 127; i++)
        {
            patternMask[i] = ~0;
        }

        // Set the pattern mask for each character in the pattern.
        // Use bitwise AND to clear the bit corresponding to the current character.
        for (var i = 0; i < len; ++i)
        {
            patternMask[pattern[i]] &= ~(1 << i);
        }

        // Search for the pattern in the text.
        // Loop through each character in the text.
        for (var i = 0; i < text.Length; ++i)
        {
            // Update the register.
            // Set the least significant bit in the register to 0 or 1
            // depending on whether the current character in the text matches the pattern.
            // This will make it easier to check for the pattern later.
            var oldR = r[0];

            r[0] |= patternMask[text[i]];
            r[0] <<= 1;

            // Update the other registers.
            // Set the least significant bit in each register to 0 or 1
            // depending on whether the current character in the text matches the pattern.
            // This will make it easier to check for the pattern later.
            for (var j = 1; j <= threshold; ++j)
            {
                var tmp = r[j];

                r[j] = (oldR & (r[j] | patternMask[text[i]])) << 1;
                oldR = tmp;
            }

            // If the pattern has been found, return the index.
            // Check the most significant bit in the register.
            // If it's 0, then the pattern has been found.
            if ((r[threshold] & 1 << len) == 0)
            {
                // The pattern has been found.
                // Return the index of the first character in the pattern.
                return i - len + 1;
            }
        }

        // The pattern has not been found.
        return -1;
    }
}

namespace Algorithms.Strings.PatternMatching;

/// <summary>
///     The idea:   You compare the pattern with the text from right to left.
///     If the text symbol that is compared with the rightmost pattern symbol
///     does not occur in the pattern at all, then the pattern can be shifted
///     by m positions behind this text symbol.
///     Complexity:
///     Time:   Preprocessing: O(m²)
///     Comparison: O(mn)
///     Space:  O(m + a)
///     where   m - pattern length
///     n - text length
///     a - alphabet length.
///     Source:     https://www.inf.hs-flensburg.de/lang/algorithmen/pattern/bmen.htm
///     https://en.wikipedia.org/wiki/Boyer%E2%80%93Moore_string-search_algorithm.
/// </summary>
public static class BoyerMoore
{
    /// <summary>
    ///     Finds the index of the first occurrence of the pattern <c>p</c> in <c>t</c>.
    /// </summary>
    /// <param name="t">Input text.</param>
    /// <param name="p">Search pattern.</param>
    /// <returns>Index of the pattern in text or -1 if the pattern  was not found.</returns>
    public static int FindFirstOccurrence(string t, string p)
    {
        // Pattern length
        var m = p.Length;

        // Text length
        var n = t.Length;

        // For each symbol of the alphabet, the position of its rightmost occurrence in the pattern,
        // or -1 if the symbol does not occur in the pattern.
        int[] badChar = BadCharacterRule(p, m);

        // Each entry goodSuffix[i] contains the shift distance of the pattern
        // if a mismatch at position i – 1 occurs, i.e. if the suffix of the pattern starting at position i has matched.
        int[] goodSuffix = GoodSuffixRule(p, m);

        // Index in text
        var i = 0;

        // Index in pattern
        int j;

        while (i <= n - m)
        {
            // Starting at end of pattern
            j = m - 1;

            // While matching
            while (j >= 0 && p[j] == t[i + j])
            {
                j--;
            }

            // Pattern found
            if (j < 0)
            {
                return i;
            }

            // Pattern is shifted by the maximum of the values
            // given by the good-suffix and the bad-character heuristics
            i += Math.Max(goodSuffix[j + 1], j - badChar[t[i + j]]);
        }

        // Pattern not found
        return -1;
    }

    /// <summary>
    ///     Finds out the position of its rightmost occurrence in the pattern for each symbol of the alphabet,
    ///     or -1 if the symbol does not occur in the pattern.
    /// </summary>
    /// <param name="p">Search pattern.</param>
    /// <param name="m">Length of the pattern.</param>
    /// <returns>Array of the named postition for each symbol of the alphabet.</returns>
    private static int[] BadCharacterRule(string p, int m)
    {
        // For each character (note that there are more than 256 characters)
        int[] badChar = new int[256];
        Array.Fill(badChar, -1);

        // Iterate from left to right over the pattern
        for (var j = 0; j < m; j++)
        {
            badChar[p[j]] = j;
        }

        return badChar;
    }

    /// <summary>
    ///     Finds out the shift distance of the pattern if a mismatch at position i – 1 occurs
    ///     for each character of the pattern, i.e. if the suffix of the pattern starting at position i has matched.
    /// </summary>
    /// <param name="p">Search pattern.</param>
    /// <param name="m">Length of the pattern.</param>
    /// <returns>Array of the named shift distance for each character of the pattern.</returns>
    private static int[] GoodSuffixRule(string p, int m)
    {
        // CASE 1
        // The matching suffix occurs somewhere else in the pattern
        // --> matching suffix is a border of a suffix of the pattern

        // f[i] contains starting position of the widest border of the suffix of the pattern beginning at position i
        int[] f = new int[p.Length + 1];

        // Suffix of p[m] has no border --> f[m] = m+1
        f[m] = m + 1;

        // Corresponding shift distance
        int[] s = new int[p.Length + 1];

        // Start of suffix including border of the pattern
        // (hint: https://www.inf.hs-flensburg.de/lang/algorithmen/pattern/kmpen.htm#section2)
        var i = m;

        // Start of suffix of the pattern
        var j = m + 1;

        while (i > 0)
        {
            // checking if a shorter border that is already known can be extended to the left by the same symbol
            while (j <= m && p[i - 1] != p[j - 1])
            {
                if (s[j] == 0)
                {
                    s[j] = j - i;
                }

                j = f[j];
            }

            --i;
            --j;
            f[i] = j;
        }

        // CASE 2
        // Only a part of the matching suffix occurs at the beginning of the pattern
        // (filling remaining entries)
        j = f[0];
        for (i = 0; i <= m; i++)
        {
            // Starting postition of the greates border
            if (s[i] == 0)
            {
                s[i] = j;
            }

            // From position i = j, it switches to the next narrower border f[j]
            if (i == j)
            {
                j = f[j];
            }
        }

        return s;
    }
}

// Implements the traditional naive string matching algorithm in C# for TheAlgorithms/C-Sharp.
namespace Algorithms.Strings.PatternMatching;

/// <summary>
///     Implements the traditional naive string matching algorithm in C#.
/// </summary>
public static class NaiveStringSearch
{
    /// <summary>
    ///     NaiveSearch(Content, Pattern) will return an array containing each index of Content in which Pattern appears.
    ///     Cost:  O(n*m).
    /// </summary>
    /// <param name="content">The text body across which to search for a given pattern.</param>
    /// <param name="pattern">The pattern against which to check the given text body.</param>
    /// <returns>Array containing each index of Content in which Pattern appears.</returns>
    public static int[] NaiveSearch(string content, string pattern)
    {
        var m = pattern.Length;
        var n = content.Length;
        List<int> indices = [];
        for (var e = 0; e <= n - m; e++)
        {
            int j;
            for (j = 0; j < m; j++)
            {
                if (content[e + j] != pattern[j])
                {
                    break;
                }
            }

            if (j == m)
            {
                indices.Add(e);
            }
        }

        return indices.ToArray();
    }
}

namespace Algorithms.Strings.PatternMatching;

/// <summary>
///     The idea: You calculate the hash for the pattern <c>p</c> and the hash values for all the prefixes of the text
///     <c>t</c>.
///     Now, you can compare a substring in constant time using the calculated hashes.
///     time complexity: O(p + t),
///     space complexity: O(t),
///     where   t - text length
///     p - pattern length.
/// </summary>
public static class RabinKarp
{
    /// <summary>
    ///     Finds the index of all occurrences of the pattern <c>p</c> int <c>t</c>.
    /// </summary>
    /// <returns>List of starting indices of the pattern in the text.</returns>
    public static List<int> FindAllOccurrences(string text, string pattern)
    {
        // Prime number
        const ulong p = 65537;

        // Modulo coefficient
        const ulong m = (ulong)1e9 + 7;

        // p_pow[i] = P^i mod M
        ulong[] pPow = new ulong[Math.Max(pattern.Length, text.Length)];
        pPow[0] = 1;
        for (var i = 1; i < pPow.Length; i++)
        {
            pPow[i] = pPow[i - 1] * p % m;
        }

        // hash_t[i] is the sum of the previous hash values of the letters (t[0], t[1], ..., t[i-1]) and the hash value of t[i] itself (mod M).
        // The hash value of a letter t[i] is equal to the product of t[i] and p_pow[i] (mod M).
        ulong[] hashT = new ulong[text.Length + 1];
        for (var i = 0; i < text.Length; i++)
        {
            hashT[i + 1] = (hashT[i] + text[i] * pPow[i]) % m;
        }

        // hash_s is equal to sum of the hash values of the pattern (mod M).
        ulong hashS = 0;
        for (var i = 0; i < pattern.Length; i++)
        {
            hashS = (hashS + pattern[i] * pPow[i]) % m;
        }

        // In the next step you iterate over the text with the pattern.
        List<int> occurrences = [];
        for (var i = 0; i + pattern.Length - 1 < text.Length; i++)
        {
            // In each step you calculate the hash value of the substring to be tested.
            // By storing the hash values of the letters as a prefixes you can do this in constant time.
            var currentHash = (hashT[i + pattern.Length] + m - hashT[i]) % m;

            // Now you can compare the hash value of the substring with the product of the hash value of the pattern and p_pow[i].
            if (currentHash == hashS * pPow[i] % m)
            {
                // If the hash values are identical, do a double-check in case a hash collision occurs.
                var j = 0;
                while (j < pattern.Length && text[i + j] == pattern[j])
                {
                    ++j;
                }

                if (j == pattern.Length)
                {
                    // If the hash values are identical and the double-check passes, a substring was found that matches the pattern.
                    // In this case you add the index i to the list of occurences.
                    occurrences.Add(i);
                }
            }
        }

        return occurrences;
    }
}

namespace Algorithms.Strings.PatternMatching;

/// <summary>
///     Implentation of regular expression matching with support for '.' and '*'.
///     '.' Matches any single character.
///     '*' Matches zero or more of the preceding element.
///     The matching should cover the entire input string (not partial).
/// </summary>
public static class WildCardMatcher
{
    /// <summary>
    ///    Using bottom-up dynamic programming for matching the input string with the pattern.
    ///
    ///    Time complexity: O(n*m), where n is the length of the input string and m is the length of the pattern.
    ///
    ///    Constrain: The pattern cannot start with '*'.
    /// </summary>
    /// <param name="inputString">The input string to match.</param>
    /// <param name="pattern">The pattern to match.</param>
    /// <returns>True if the input string matches the pattern, false otherwise.</returns>
    /// <exception cref="ArgumentException">Thrown when the pattern starts with '*'.</exception>
    public static bool MatchPattern(string inputString, string pattern)
    {
        if (pattern.Length > 0 && pattern[0] == '*')
        {
            throw new ArgumentException("Pattern cannot start with *");
        }

        var inputLength = inputString.Length + 1;
        var patternLength = pattern.Length + 1;

        // DP 2d matrix, where dp[i, j] is true if the first i characters in the input string match the first j characters in the pattern
        // This DP is initialized to all falses, as it is the default value for a boolean.
        var dp = new bool[inputLength, patternLength];

        // Empty string and empty pattern are a match
        dp[0, 0] = true;

        // Since the empty string can only match a pattern that has a * in it, we need to initialize the first row of the DP matrix
        for (var j = 1; j < patternLength; j++)
        {
            if (pattern[j - 1] == '*')
            {
                dp[0, j] = dp[0, j - 2];
            }
        }

        // Now using bottom-up approach to find for all remaining lenghts of input and pattern
        for (var i = 1; i < inputLength; i++)
        {
            for (var j = 1; j < patternLength; j++)
            {
                MatchRemainingLenghts(inputString, pattern, dp, i, j);
            }
        }

        return dp[inputLength - 1, patternLength - 1];
    }

    // Helper method to match the remaining lengths of the input string and the pattern
    // This method is called for all i and j where i > 0 and j > 0
    private static void MatchRemainingLenghts(string inputString, string pattern, bool[,] dp, int i, int j)
    {
        // If the characters match or the pattern has a ., then the result is the same as the previous positions.
        if (inputString[i - 1] == pattern[j - 1] || pattern[j - 1] == '.')
        {
            dp[i, j] = dp[i - 1, j - 1];
        }
        else if (pattern[j - 1] == '*')
        {
            MatchForZeroOrMore(inputString, pattern, dp, i, j);
        }
        else
        {
            // If the characters do not match, then the result is false, which is the default value.
        }
    }

    // Helper method to match for the "*" pattern.
    private static void MatchForZeroOrMore(string inputString, string pattern, bool[,] dp, int i, int j)
    {
        if (dp[i, j - 2])
        {
            dp[i, j] = true;
        }
        else if (inputString[i - 1] == pattern[j - 2] || pattern[j - 2] == '.')
        {
            dp[i, j] = dp[i - 1, j];
        }
        else
        {
            // Leave the default value of false
        }
    }
}

namespace Algorithms.Strings.PatternMatching;

/// <summary>Implementation Z-block substring search.
/// </summary>
public static class ZblockSubstringSearch
{
    /// <summary>
    ///     This algorithm finds all occurrences of a pattern in a text in linear time - O(m+n).
    /// </summary>
    public static int FindSubstring(string pattern, string text)
    {
        var concatStr = $"{pattern}${text}";
        var patternLength = pattern.Length;
        var n = concatStr.Length;
        var zArray = new int[n];

        var left = 0;
        var right = 0;

        for(var i = 1; i < n; i++)
        {
            if(i > right)
            {
                left = i;
                right = ComputeNewRightValue(concatStr, n, left, i);

                zArray[i] = right - left;
                right--;
            }
            else
            {
                var k = i - left;
                if (zArray[k] < (right - i + 1))
                {
                    zArray[i] = zArray[k];
                }
                else
                {
                    left = i;
                    right = ComputeNewRightValue(concatStr, n, left, right);
                    zArray[i] = right - left;
                    right--;
                }
            }
        }

        var found = 0;
        foreach(var z_value in zArray)
        {
            if(z_value == patternLength)
            {
                found++;
            }
        }

        return found;
    }

    private static int ComputeNewRightValue(string concatStr, int n, int left, int right)
    {
        while (right < n && concatStr[right - left].Equals(concatStr[right]))
        {
            right++;
        }

        return right;
    }
}

namespace Algorithms.Strings;

public static class Permutation
{
    /// <summary>
    /// Returns every anagram of a given word.
    /// </summary>
    /// <returns>List of anagrams.</returns>
    public static List<string> GetEveryUniquePermutation(string word)
    {
        if (word.Length < 2)
        {
            return
            [
                word,
            ];
        }

        var result = new HashSet<string>();

        for (var i = 0; i < word.Length; i++)
        {
            var temp = GetEveryUniquePermutation(word.Remove(i, 1));

            result.UnionWith(temp.Select(subPerm => word[i] + subPerm));
        }

        return result.ToList();
    }
}

namespace Algorithms.Strings.Similarity;

public static class CosineSimilarity
{
    /// <summary>
    /// Calculates the Cosine Similarity between two strings.
    /// Cosine Similarity is a measure of similarity between two non-zero vectors of an inner product space.
    /// It measures the cosine of the angle between the two vectors.
    /// </summary>
    /// <param name="left">The first string.</param>
    /// <param name="right">The second string.</param>
    /// <returns>
    /// A double value between 0 and 1 that represents the similarity
    /// of the two strings.
    /// </returns>
    public static double Calculate(string left, string right)
    {
        // Step 1: Get the vectors for the two strings
        // Each vector represents the frequency of each character in the string.
        var vectors = GetVectors(left.ToLowerInvariant(), right.ToLowerInvariant());
        var leftVector = vectors.LeftVector;
        var rightVector = vectors.RightVector;

        // Step 2: Calculate the intersection of the two vectors
        // The intersection is the set of characters that appear in both strings.
        var intersection = GetIntersection(leftVector, rightVector);

        // Step 3: Calculate the dot product of the two vectors
        // The dot product is the sum of the products of the corresponding values of the characters in the intersection.
        var dotProduct = DotProduct(leftVector, rightVector, intersection);

        // Step 4: Calculate the square magnitude of each vector
        // The magnitude is the square root of the sum of the squares of the values in the vector.
        var mLeft = 0.0;
        foreach (var value in leftVector.Values)
        {
            mLeft += value * value;
        }

        var mRight = 0.0;
        foreach (var value in rightVector.Values)
        {
            mRight += value * value;
        }

        // Step 5: Check if either vector is zero
        // If either vector is zero (i.e., all characters are unique), the Cosine Similarity is 0.
        if (mLeft <= 0 || mRight <= 0)
        {
            return 0.0;
        }

        // Step 6: Calculate and return the Cosine Similarity
        // The Cosine Similarity is the dot product divided by the product of the magnitudes.
        return dotProduct / (Math.Sqrt(mLeft) * Math.Sqrt(mRight));
    }

    /// <summary>
    /// Calculates the vectors for the given strings.
    /// </summary>
    /// <param name="left">The first string.</param>
    /// <param name="right">The second string.</param>
    /// <returns>A tuple containing the vectors for the two strings.</returns>
    private static (Dictionary<char, int> LeftVector, Dictionary<char, int> RightVector) GetVectors(string left, string right)
    {
        var leftVector = new Dictionary<char, int>();
        var rightVector = new Dictionary<char, int>();

        // Calculate the frequency of each character in the left string
        foreach (var character in left)
        {
            leftVector.TryGetValue(character, out var frequency);
            leftVector[character] = ++frequency;
        }

        // Calculate the frequency of each character in the right string
        foreach (var character in right)
        {
            rightVector.TryGetValue(character, out var frequency);
            rightVector[character] = ++frequency;
        }

        return (leftVector, rightVector);
    }

    /// <summary>
    /// Calculates the dot product between two vectors represented as dictionaries of character frequencies.
    /// The dot product is the sum of the products of the corresponding values of the characters in the intersection of the two vectors.
    /// </summary>
    /// <param name="leftVector">The vector of the left string.</param>
    /// <param name="rightVector">The vector of the right string.</param>
    /// <param name="intersection">The intersection of the two vectors, represented as a set of characters.</param>
    /// <returns>The dot product of the two vectors.</returns>
    private static double DotProduct(Dictionary<char, int> leftVector, Dictionary<char, int> rightVector, HashSet<char> intersection)
    {
        // Initialize the dot product to 0
        double dotProduct = 0;

        // Iterate over each character in the intersection of the two vectors
        foreach (var character in intersection)
        {
            // Calculate the product of the corresponding values of the characters in the left and right vectors
            dotProduct += leftVector[character] * rightVector[character];
        }

        // Return the dot product
        return dotProduct;
    }

    /// <summary>
    /// Calculates the intersection of two vectors, represented as dictionaries of character frequencies.
    /// </summary>
    /// <param name="leftVector">The vector of the left string.</param>
    /// <param name="rightVector">The vector of the right string.</param>
    /// <returns>A HashSet containing the characters that appear in both vectors.</returns>
    private static HashSet<char> GetIntersection(Dictionary<char, int> leftVector, Dictionary<char, int> rightVector)
    {
        // Initialize a HashSet to store the intersection of the two vectors.
        var intersection = new HashSet<char>();

        // Iterate over each key-value pair in the left vector.
        foreach (var kvp in leftVector)
        {
            // If the right vector contains the same key, add it to the intersection.
            if (rightVector.ContainsKey(kvp.Key))
            {
                intersection.Add(kvp.Key);
            }
        }

        return intersection;
    }
}

namespace Algorithms.Strings.Similarity;

public static class DamerauLevenshteinDistance
{
    /// <summary>
    /// Calculates the Damerau-Levenshtein distance between two strings.
    /// The Damerau-Levenshtein distance is a string metric for measuring the difference between two sequences.
    /// It is calculated as the minimum number of operations needed to transform one sequence into the other.
    /// The possible operations are insertion, deletion, substitution, and transposition.
    /// </summary>
    /// <param name="left">The first string.</param>
    /// <param name="right">The second string.</param>
    /// <returns>The Damerau-Levenshtein distance between the two strings.</returns>
    public static int Calculate(string left, string right)
    {
        // Get the lengths of the input strings.
        var leftSize = left.Length;
        var rightSize = right.Length;

        // Initialize a matrix of distances between the two strings.
        var distances = InitializeDistanceArray(leftSize, rightSize);

        // Iterate over each character in the left string.
        for (var i = 1; i < leftSize + 1; i++)
        {
            // Iterate over each character in the right string.
            for (var j = 1; j < rightSize + 1; j++)
            {
                // Calculate the cost of the current operation.
                // If the characters at the current positions are the same, the cost is 0.
                // Otherwise, the cost is 1.
                var cost = left[i - 1] == right[j - 1] ? 0 : 1;

                // Calculate the minimum distance by considering three possible operations:
                // deletion, insertion, and substitution.
                distances[i, j] = Math.Min(
                    Math.Min(// deletion
                        distances[i - 1, j] + 1, // delete the character from the left string
                        distances[i, j - 1] + 1), // insert the character into the right string
                    distances[i - 1, j - 1] + cost); // substitute the character in the left string with the character in the right string

                // If the current character in the left string is the same as the character
                // two positions to the left in the right string and the current character
                // in the right string is the same as the character one position to the right
                // in the left string, then we can also consider a transposition operation.
                if (i > 1 && j > 1 && left[i - 1] == right[j - 2] && left[i - 2] == right[j - 1])
                {
                    distances[i, j] = Math.Min(
                        distances[i, j], // current minimum distance
                        distances[i - 2, j - 2] + cost); // transpose the last two characters
                }
            }
        }

        // Return the distance between the two strings.
        return distances[leftSize, rightSize];
    }

    /// <summary>
    /// Initializes a matrix of distances between two string representations.
    ///
    /// This method creates a matrix of distances where the dimensions are one larger
    /// than the input strings. The first row of the matrix represents the distances
    /// when the left string is empty, and the first column represents the distances
    /// when the right string is empty. The values in the first row and first column
    /// are the lengths of the corresponding strings.
    ///
    /// The matrix is used by the Damerau-Levenshtein algorithm to calculate the
    /// minimum number of single-character edits (insertions, deletions, or substitutions)
    /// required to change one word into the other.
    /// The matrix is initialized with dimensions one larger than the input strings.
    /// The first row of the matrix represents the distances when the left string is empty.
    /// The first column of the matrix represents the distances when the right string is empty.
    /// The values in the first row and first column are the lengths of the corresponding strings.
    /// Initializes a matrix of distances between two strings representations.
    /// </summary>
    /// <param name="leftSize">The size of the left string.</param>
    /// <param name="rightSize">The size of the right string.</param>
    /// <returns>A matrix of distances.</returns>
    private static int[,] InitializeDistanceArray(int leftSize, int rightSize)
    {
        // Initialize a matrix of distances with dimensions one larger than the input strings.
        var matrix = new int[leftSize + 1, rightSize + 1];

        // Set the values in the first row to the lengths of the left string.
        // This represents the distance when the left string is empty.
        for (var i = 1; i < leftSize + 1; i++)
        {
            matrix[i, 0] = i;
        }

        // Set the values in the first column to the lengths of the right string.
        // This represents the distance when the right string is empty.
        for (var i = 1; i < rightSize + 1; i++)
        {
            matrix[0, i] = i;
        }

        // Return the initialized matrix of distances.
        return matrix;
    }
}

namespace Algorithms.Strings.Similarity;

/// <summary>
///     <para>
///         Hamming distance between two strings of equal length is the number of positions at which the corresponding symbols are different.
///         Time complexity is O(n) where n is the length of the string.
///     </para>
///     <para>
///         Wikipedia: https://en.wikipedia.org/wiki/Hamming_distance.
///     </para>
/// </summary>
public static class HammingDistance
{
    /// <summary>
    ///     Calculates Hamming distance between two strings of equal length.
    /// </summary>
    /// <param name="s1">First string.</param>
    /// <param name="s2">Second string.</param>
    /// <returns>Levenshtein distance between source and target strings.</returns>
    public static int Calculate(string s1, string s2)
    {
        if (s1.Length != s2.Length)
        {
            throw new ArgumentException("Strings must be equal length.");
        }

        var distance = 0;
        for (var i = 0; i < s1.Length; i++)
        {
            distance += s1[i] != s2[i] ? 1 : 0;
        }

        return distance;
    }
}

namespace Algorithms.Strings.Similarity;

/// <summary>
///  <para>
/// Jaccard distance is a measure of two sets of data are. It is calculated by subtracting the Jaccard similarity
/// coefficient from 1, or, equivalently by dividing the difference of the sizes of the union and intersection of two sets
/// by the size of the union.
/// </para>
/// <para>
/// For example, suppose we have two sets of words:
/// <list type="bullet">
/// <item>
/// A = {apple, banana, cherry, date}
/// </item>
/// <item>
/// B = {banana, cherry, elderberry, fig}
/// </item>
/// </list>
/// </para>
/// <para>
/// The number of common elements in both sets is 2 (banana and cherry). The number of elements in either set is 6
/// (apple, banana, cherry, date, elderberry, fig).
/// </para>
/// <para>
/// The Jaccard similarity coefficient is 2 / 6 = 0.333333 or 33.333% similarity.
/// </para>
/// <para>
/// The Jaccard distance is 1 - 0.33333 = 0.66667. This means that the two sets are about 67% different.
/// </para>
/// <para>
/// Jaccard distance is commonly used to calculate a matrix of clustering and multidimensional scaling of sample tests.
/// </para>
/// </summary>
public class JaccardDistance
{
    private readonly JaccardSimilarity jaccardSimilarity = new();

    /// <summary>
    /// Calculate the Jaccard distance between to strings.
    /// </summary>
    /// <param name="left">The first string.</param>
    /// <param name="right">The second string.</param>
    /// <returns>The Jaccard distance.</returns>
    public double Calculate(string left, string right)
    {
        return 1.0 - jaccardSimilarity.Calculate(left, right);
    }
}

namespace Algorithms.Strings.Similarity;

/// <summary>
///  <para>
/// Jaccard similarity is a statistic that measures how similar two sets of data are. It is calculated by dividing
/// the number of common elements in both sets by the number of elements in either set. More formally, it is the
/// quotient of the division of the size of the size of the intersection divided by the size of the union of two sets.
/// </para>
/// <para>
/// The result is a value between 0 and 1, where 0 means no similarity and 1 means perfect similarity.
/// </para>
/// <para>
/// For example, suppose we have two sets of words:
/// <list type="bullet">
/// <item>
/// A = {apple, banana, cherry, date}
/// </item>
/// <item>
/// B = {banana, cherry, elderberry, fig}
/// </item>
/// </list>
/// </para>
/// <para>
/// The number of common elements in both sets is 2 (banana and cherry). The number of elements in either set is 6
/// (apple, banana, cherry, date, elderberry, fig).
/// </para>
/// <para>
/// The Jaccard similarity coefficient is 2 / 6 = 0.333333 or 33.333% similarity.
/// </para>
/// </summary>
public class JaccardSimilarity
{
    /// <summary>
    /// Calculates the Jaccard similarity coefficient between two strings.
    /// </summary>
    /// <param name="left">The first string to compare.</param>
    /// <param name="right">The second string to compare.</param>
    /// <returns>A double value between 0 and 1 that represents the similarity of the two strings.</returns>
    /// <exception cref="ArgumentNullException">Thrown when either the input is null.</exception>
    /// <remarks>
    /// This method uses a HashSet to represent the sets of characters in the input strings.
    /// </remarks>
    public double Calculate(string left, string right)
    {
        // Validate the input strings before proceeding.
        ValidateInput(left, right);

        // Get the lengths of the input strings.
        var leftLength = left.Length;
        var rightLength = right.Length;

        // If both strings are empty, return 1.0 as the similarity coefficient.
        if (leftLength == 0 && rightLength == 0)
        {
            return 1.0d;
        }

        // If either string is empty, return 0.0 as the similarity coefficient.
        if (leftLength == 0 || rightLength == 0)
        {
            return 0.0d;
        }

        // Get the unique characters in each string.
        var leftSet = new HashSet<char>(left);
        var rightSet = new HashSet<char>(right);

        // Get the union of the two strings.
        var unionSet = new HashSet<char>(leftSet);
        foreach (var c in rightSet)
        {
            unionSet.Add(c);
        }

        // Calculate the intersection size of the two strings.
        var intersectionSize = leftSet.Count + rightSet.Count - unionSet.Count;

        // Return the Jaccard similarity coefficient as the ratio of intersection to union.
        return 1.0d * intersectionSize / unionSet.Count;
    }

    /// <summary>
    /// Validates the input strings and throws an exception if either is null.
    /// </summary>
    /// <param name="left">The first string to validate.</param>
    /// <param name="right">The second string to validate.</param>
    private void ValidateInput(string left, string right)
    {
        if (left == null || right == null)
        {
            var paramName = left == null ? nameof(left) : nameof(right);
            throw new ArgumentNullException(paramName, "Input cannot be null");
        }
    }
}

namespace Algorithms.Strings.Similarity;

/// <summary>
///     <para>
///         Jaro Similarity measures how similar two strings are.
///         Result is between 0 and 1 where 0 represnts that there is no similarity between strings and 1 represents equal strings.
///         Time complexity is O(a*b) where a is the length of the first string and b is the length of the second string.
///     </para>
///     <para>
///         Wikipedia: https://en.wikipedia.org/wiki/Jaro%E2%80%93Winkler_distance#Jaro_similarity.
///     </para>
/// </summary>
public static class JaroSimilarity
{
    /// <summary>
    ///     Calculates Jaro Similarity between two strings.
    /// </summary>
    /// <param name="s1">First string.</param>
    /// <param name="s2">Second string.</param>
    public static double Calculate(string s1, string s2)
    {
        if (s1 == s2)
        {
            return 1;
        }

        var longerString = s1.Length > s2.Length ? s1 : s2;
        var shorterString = s1.Length < s2.Length ? s1 : s2;

        // will look for matching characters in this range
        var matchingCharacterRange = Math.Max((longerString.Length / 2) - 1, 0);
        var matches = 0d;

        // true if i-th index of s1 was matched in s2
        var s1MatchedIndeces = new bool[s1.Length];

        // true if i-th index of s2 was matched in s1
        var s2MatchedIndeces = new bool[s2.Length];

        for (var i = 0; i < longerString.Length; i++)
        {
            var startIndex = Math.Max(i - matchingCharacterRange, 0);
            var endIndex = Math.Min(i + matchingCharacterRange, shorterString.Length - 1);
            for (var j = startIndex; j <= endIndex; j++)
            {
                if (s1[i] == s2[j] && !s2MatchedIndeces[j])
                {
                    matches++;
                    s1MatchedIndeces[i] = true;
                    s2MatchedIndeces[j] = true;
                    break;
                }
            }
        }

        if (matches == 0)
        {
            return 0;
        }

        var transpositions = CalculateTranspositions(s1, s2, s1MatchedIndeces, s2MatchedIndeces);

        return ((matches / s1.Length) + (matches / s2.Length) + ((matches - transpositions) / matches)) / 3;
    }

    /// <summary>
    ///     Calculates number of matched characters that are not in the right order.
    /// </summary>
    private static int CalculateTranspositions(string s1, string s2, bool[] s1MatchedIndeces, bool[] s2MatchedIndeces)
    {
        var transpositions = 0;
        var s2Index = 0;
        for (var s1Index = 0; s1Index < s1.Length; s1Index++)
        {
            if (s1MatchedIndeces[s1Index])
            {
                while (!s2MatchedIndeces[s2Index])
                {
                    s2Index++;
                }

                if (s1[s1Index] != s2[s2Index])
                {
                    transpositions++;
                }

                s2Index++;
            }
        }

        transpositions /= 2;
        return transpositions;
    }
}

namespace Algorithms.Strings.Similarity;

/// <summary>
///     <para>
///         Jaro–Winkler distance is a string metric measuring an edit distance between two sequences.
///         The score is normalized such that 1 means an exact match and 0 means there is no similarity.
///         Time complexity is O(a*b) where a is the length of the first string and b is the length of the second string.
///     </para>
///     <para>
///         Wikipedia: https://en.wikipedia.org/wiki/Jaro%E2%80%93Winkler_distance.
///     </para>
/// </summary>
public static class JaroWinklerDistance
{
    /// <summary>
    ///     Calculates Jaro–Winkler distance.
    /// </summary>
    /// <param name="s1">First string.</param>
    /// <param name="s2">Second string.</param>
    /// <param name="scalingFactor">Scaling factor for how much the score is adjusted upwards for having common prefixes. Default is 0.1.</param>
    /// <returns>Distance between two strings.</returns>
    public static double Calculate(string s1, string s2, double scalingFactor = 0.1)
    {
        var jaroSimilarity = JaroSimilarity.Calculate(s1, s2);
        var commonPrefixLength = s1.Zip(s2).Take(4).TakeWhile(x => x.First == x.Second).Count();
        var jaroWinklerSimilarity = jaroSimilarity + commonPrefixLength * scalingFactor * (1 - jaroSimilarity);

        return 1 - jaroWinklerSimilarity;
    }
}

namespace Algorithms.Strings.Similarity
{
    /// <summary>
    /// Provides methods to calculate the Optimal String Alignment distance between two strings.
    ///
    /// The Optimal String Alignment distance, also known as the restricted Damerau-Levenshtein distance,
    /// is a string metric used to measure the difference between two sequences. It is similar to the
    /// Levenshtein distance, but it also considers transpositions (swapping of two adjacent characters)
    /// as a single operation. This metric is particularly useful when adjacent characters are commonly
    /// transposed, such as in typographical errors.
    ///
    /// The OSA distance between two strings is defined as the minimum number of operations required to
    /// transform one string into the other, where the operations include:
    ///
    /// 1. Insertion: Adding a single character.
    /// 2. Deletion: Removing a single character.
    /// 3. Substitution: Replacing one character with another.
    /// 4. Transposition: Swapping two adjacent characters (this is what distinguishes OSA from the
    ///    traditional Levenshtein distance).
    ///
    /// The OSA distance algorithm ensures that no operation is applied more than once to the same
    /// character in the same position. This is the main difference between the OSA and the more general
    /// Damerau-Levenshtein distance, which does not have this restriction.
    ///
    /// <example>
    /// Example Usage:
    /// <code>
    /// int distance = OptimalStringAlignmentDistance("example", "exmaple");
    /// Console.WriteLine(distance); // Output: 1
    /// </code>
    /// In this example, the strings "example" and "exmaple" differ by one transposition of adjacent characters ('a' and 'm'),
    /// so the OSA distance is 1.
    ///
    /// <code>
    /// int distance = OptimalStringAlignmentDistance("kitten", "sitting");
    /// Console.WriteLine(distance); // Output: 3
    /// </code>
    /// Here, the strings "kitten" and "sitting" have three differences (substitutions 'k' to 's', 'e' to 'i', and insertion of 'g'),
    /// resulting in an OSA distance of 3.
    /// </example>
    /// </summary>
    /// <remarks>
    /// This algorithm has a time complexity of O(n * m), where n and m are the lengths of the two input strings.
    /// It is efficient for moderate-sized strings but may become computationally expensive for very long strings.
    /// </remarks>
    public static class OptimalStringAlignment
    {
        /// <summary>
        /// Calculates the Optimal String Alignment distance between two strings.
        /// </summary>
        /// <param name="firstString">The first string.</param>
        /// <param name="secondString">The second string.</param>
        /// <returns>The Optimal String Alignment distance between the two strings.</returns>
        /// <exception cref="ArgumentNullException">Thrown when either of the input strings is null.</exception>
        public static double Calculate(string firstString, string secondString)
        {
            ArgumentNullException.ThrowIfNull(nameof(firstString));
            ArgumentNullException.ThrowIfNull(nameof(secondString));

            if (firstString == secondString)
            {
                return 0.0;
            }

            if (firstString.Length == 0)
            {
                return secondString.Length;
            }

            if (secondString.Length == 0)
            {
                return firstString.Length;
            }

            var distanceMatrix = GenerateDistanceMatrix(firstString.Length, secondString.Length);
            distanceMatrix = CalculateDistance(firstString, secondString, distanceMatrix);

            return distanceMatrix[firstString.Length, secondString.Length];
        }

        /// <summary>
        /// Generates the initial distance matrix for the given lengths of the two strings.
        /// </summary>
        /// <param name="firstLength">The length of the first string.</param>
        /// <param name="secondLength">The length of the second string.</param>
        /// <returns>The initialized distance matrix.</returns>
        private static int[,] GenerateDistanceMatrix(int firstLength, int secondLength)
        {
            var distanceMatrix = new int[firstLength + 2, secondLength + 2];

            for (var i = 0; i <= firstLength; i++)
            {
                distanceMatrix[i, 0] = i;
            }

            for (var j = 0; j <= secondLength; j++)
            {
                distanceMatrix[0, j] = j;
            }

            return distanceMatrix;
        }

        /// <summary>
        /// Calculates the distance matrix for the given strings using the Optimal String Alignment algorithm.
        /// </summary>
        /// <param name="firstString">The first string.</param>
        /// <param name="secondString">The second string.</param>
        /// <param name="distanceMatrix">The initial distance matrix.</param>
        /// <returns>The calculated distance matrix.</returns>
        private static int[,] CalculateDistance(string firstString, string secondString, int[,] distanceMatrix)
        {
            for (var i = 1; i <= firstString.Length; i++)
            {
                for (var j = 1; j <= secondString.Length; j++)
                {
                    var cost = 1;

                    if (firstString[i - 1] == secondString[j - 1])
                    {
                        cost = 0;
                    }

                    distanceMatrix[i, j] = Minimum(
                        distanceMatrix[i - 1, j - 1] + cost, // substitution
                        distanceMatrix[i, j - 1] + 1, // insertion
                        distanceMatrix[i - 1, j] + 1); // deletion

                    if (i > 1 && j > 1
                        && firstString[i - 1] == secondString[j - 2]
                        && firstString[i - 2] == secondString[j - 1])
                    {
                        distanceMatrix[i, j] = Math.Min(
                            distanceMatrix[i, j],
                            distanceMatrix[i - 2, j - 2] + cost); // transposition
                    }
                }
            }

            return distanceMatrix;
        }

        /// <summary>
        /// Returns the minimum of three integers.
        /// </summary>
        /// <param name="a">The first integer.</param>
        /// <param name="b">The second integer.</param>
        /// <param name="c">The third integer.</param>
        /// <returns>The minimum of the three integers.</returns>
        private static int Minimum(int a, int b, int c)
        {
            return Math.Min(a, Math.Min(b, c));
        }
    }
}

using DataStructures.AATree;

namespace DataStructures.Tests;

internal class AaTreeTests
{
    [Test]
    public void Constructor_UseCustomComparer_FormsCorrectTree()
