        {
            1,
            2
        };

        // Act
        bag.Clear();

        // Assert
        bag.IsEmpty().Should().BeTrue();
        bag.Count.Should().Be(0);
    }

    [Test]
    public void IsEmpty_ShouldReturnTrueForEmptyBag()
    {
        // Arrange
        var bag = new Bag<int>();

        // Act & Assert
        bag.IsEmpty().Should().BeTrue();
    }

    [Test]
    public void IsEmpty_ShouldReturnFalseForNonEmptyBag()
    {
        // Arrange
        var bag = new Bag<int>
        {
            1
        };

        // Act & Assert
        bag.IsEmpty().Should().BeFalse();
    }

    [Test]
    public void GetEnumerator_ShouldIterateAllItems()
    {
        // Arrange
        var bag = new Bag<int>
        {
            1,
            2,
            1
        };

        // Act
        var items = bag.ToList();

        // Assert
        items.Count.Should().Be(3);
        items.Should().Contain(1);
        items.Should().Contain(2);
    }

    [Test]
    public void Count_ShouldReturnZeroForEmptyBag()
    {
        // Arrange
        var bag = new Bag<int>();

        // Act & Assert
        bag.Count.Should().Be(0);
    }

    [Test]
    public void Count_ShouldReturnCorrectCount()
    {
        // Arrange
        var bag = new Bag<int>
        {
            1,
            2,
            1
        };

        // Act & Assert
        bag.Count.Should().Be(3);
    }

    [Test]
    public void IEnumerableGetEnumerator_YieldsAllItemsWithCorrectMultiplicity()
    {
        // Arrange
        var bag = new Bag<string>
        {
            "apple",
            "banana",
            "apple"
        };
        var genericBag = bag as System.Collections.IEnumerable;

        // Act
        var enumerator = genericBag.GetEnumerator();
        var items = new List<object>();
        while (enumerator.MoveNext())
        {
            items.Add(enumerator.Current!);
        }

        // Assert
        items.Count(i => (string)i == "apple").Should().Be(2);
        items.Count(i => (string)i == "banana").Should().Be(1);
        items.Count.Should().Be(3);
        items.Should().BeEquivalentTo(["apple", "apple", "banana"]);
    }
}

using DataStructures.BinarySearchTree;

namespace DataStructures.Tests;

public static class BinarySearchTreeTests
{
    [Test]
    public static void Constructor_UseCustomComparer_FormsCorrectTree()
    {
        var cmpFunc = Comparer<string>.Create((x, y) => x.Length - y.Length);
        var tree = new BinarySearchTree<string>(cmpFunc);
        var elems = new[] { "z", "yy", "vvv", "bbbb", "fffff", "pppppp" };
        tree.AddRange(elems);

        Assert.That(tree.Search("vvv"), Is.Not.Null);
        Assert.That(tree.Search("vvv")!.Right, Is.Not.Null);
        Assert.That(tree.Search("vvv")!.Right!.Key, Is.EqualTo("bbbb"));
    }

    [Test]
    public static void Add_MultipleKeys_FormsCorrectBST()
    {
        var tree = new BinarySearchTree<int>();

        tree.Add(5);
        Assert.That(tree.Count, Is.EqualTo(1));

        tree.Add(3);
        Assert.That(tree.Count, Is.EqualTo(2));

        tree.Add(4);
        Assert.That(tree.Count, Is.EqualTo(3));

        tree.Add(2);
        Assert.That(tree.Count, Is.EqualTo(4));

        var rootNode = tree.Search(5);
        Assert.That(rootNode!.Key, Is.EqualTo(5));
        Assert.That(rootNode!.Left!.Key, Is.EqualTo(3));
        Assert.That(rootNode!.Right, Is.Null);

        var threeNode = tree.Search(3);
        Assert.That(threeNode!.Key, Is.EqualTo(3));
        Assert.That(threeNode!.Left!.Key, Is.EqualTo(2));
        Assert.That(threeNode!.Right!.Key, Is.EqualTo(4));

        var twoNode = tree.Search(2);
        Assert.That(twoNode!.Left, Is.Null);
        Assert.That(twoNode!.Right, Is.Null);

        var fourNode = tree.Search(4);
        Assert.That(fourNode!.Left, Is.Null);
        Assert.That(fourNode!.Right, Is.Null);
    }

