namespace DataStructures.AVLTree;

/// <summary>
///     A simple self-balancing binary tree.
/// </summary>
/// <remarks>
///     An AVL tree is a self-balancing binary search tree (BST) named after
///     its inventors: Adelson, Velsky, and Landis. It is the first self-
///     balancing BST invented. The primary property of an AVL tree is that
///     the height of both child subtrees for any node only differ by one.
///     Due to the balanced nature of the tree, its time complexities for
///     insertion, deletion, and search all have a worst-case time
///     complexity of O(log n). Which is an improvement over the worst-case
///     O(n) for a regular BST.
///     See https://en.wikipedia.org/wiki/AVL_tree for more information.
///     Visualizer: https://visualgo.net/en/bst.
/// </remarks>
/// <typeparam name="TKey">Type of key for the tree.</typeparam>
public class AvlTree<TKey>
{
    /// <summary>
    ///     Gets the number of nodes in the tree.
    /// </summary>
    public int Count { get; private set; }

    /// <summary>
    ///     Comparer to use when comparing key values.
    /// </summary>
    private readonly Comparer<TKey> comparer;

    /// <summary>
    ///     Reference to the root node.
    /// </summary>
    private AvlTreeNode<TKey>? root;

    /// <summary>
    ///     Initializes a new instance of the <see cref="AvlTree{TKey}"/>
    ///     class.
    /// </summary>
    public AvlTree()
    {
        comparer = Comparer<TKey>.Default;
    }

    /// <summary>
    ///     Initializes a new instance of the <see cref="AvlTree{TKey}"/>
    ///     class using the specified comparer.
    /// </summary>
    /// <param name="customComparer">
    /// Comparer to use when comparing keys.
    /// </param>
    public AvlTree(Comparer<TKey> customComparer)
    {
        comparer = customComparer;
    }

    /// <summary>
    ///     Add a single node to the tree.
    /// </summary>
    /// <param name="key">Key value to add.</param>
    public void Add(TKey key)
    {
        if (root is null)
        {
            root = new AvlTreeNode<TKey>(key);
        }
        else
        {
            root = Add(root, key);
        }

        Count++;
    }

    /// <summary>
    ///     Add multiple nodes to the tree.
    /// </summary>
    /// <param name="keys">Key values to add.</param>
    public void AddRange(IEnumerable<TKey> keys)
    {
        foreach (var key in keys)
        {
            Add(key);
        }
    }

    /// <summary>
    ///     Remove a node from the tree.
    /// </summary>
    /// <param name="key">Key value to remove.</param>
    public void Remove(TKey key)
    {
        root = Remove(root, key);
        Count--;
    }

    /// <summary>
    ///     Check if given node is in the tree.
    /// </summary>
    /// <param name="key">Key value to search for.</param>
    /// <returns>Whether or not the node is in the tree.</returns>
    public bool Contains(TKey key)
    {
        var node = root;
        while (node is not null)
        {
            var compareResult = comparer.Compare(key, node.Key);
            if (compareResult < 0)
            {
                node = node.Left;
            }
            else if (compareResult > 0)
            {
                node = node.Right;
            }
            else
            {
                return true;
            }
        }

        return false;
    }

    /// <summary>
    ///     Get the minimum value in the tree.
    /// </summary>
    /// <returns>Minimum value in tree.</returns>
    public TKey GetMin()
    {
        if (root is null)
        {
            throw new InvalidOperationException("AVL tree is empty.");
        }

        return GetMin(root).Key;
    }

    /// <summary>
    ///     Get the maximum value in the tree.
    /// </summary>
    /// <returns>Maximum value in tree.</returns>
    public TKey GetMax()
    {
        if (root is null)
        {
            throw new InvalidOperationException("AVL tree is empty.");
        }

        return GetMax(root).Key;
    }

    /// <summary>
    ///     Get keys in order from smallest to largest as defined by the
    ///     comparer.
    /// </summary>
    /// <returns>Keys in tree in order from smallest to largest.</returns>
    public IEnumerable<TKey> GetKeysInOrder()
    {
        List<TKey> result = [];
        InOrderWalk(root);
        return result;

        void InOrderWalk(AvlTreeNode<TKey>? node)
        {
            if (node is null)
            {
                return;
            }

            InOrderWalk(node.Left);
            result.Add(node.Key);
            InOrderWalk(node.Right);
        }
    }

    /// <summary>
    ///     Get keys in the pre-order order.
    /// </summary>
    /// <returns>Keys in pre-order order.</returns>
    public IEnumerable<TKey> GetKeysPreOrder()
    {
        var result = new List<TKey>();
        PreOrderWalk(root);
        return result;

        void PreOrderWalk(AvlTreeNode<TKey>? node)
        {
            if (node is null)
            {
                return;
            }

            result.Add(node.Key);
            PreOrderWalk(node.Left);
            PreOrderWalk(node.Right);
        }
    }

    /// <summary>
    ///     Get keys in the post-order order.
    /// </summary>
    /// <returns>Keys in the post-order order.</returns>
    public IEnumerable<TKey> GetKeysPostOrder()
    {
        var result = new List<TKey>();
        PostOrderWalk(root);
        return result;

        void PostOrderWalk(AvlTreeNode<TKey>? node)
        {
            if (node is null)
            {
                return;
            }

            PostOrderWalk(node.Left);
            PostOrderWalk(node.Right);
            result.Add(node.Key);
        }
    }

    /// <summary>
    ///     Helper function to rebalance the tree so that all nodes have a
    ///     balance factor in the range [-1, 1].
    /// </summary>
    /// <param name="node">Node to rebalance.</param>
    /// <returns>New node that has been rebalanced.</returns>
    private static AvlTreeNode<TKey> Rebalance(AvlTreeNode<TKey> node)
    {
        if (node.BalanceFactor > 1)
        {
            if (node.Right!.BalanceFactor == -1)
            {
                node.Right = RotateRight(node.Right);
            }

            return RotateLeft(node);
        }

        if (node.BalanceFactor < -1)
        {
            if (node.Left!.BalanceFactor == 1)
            {
                node.Left = RotateLeft(node.Left);
            }

            return RotateRight(node);
        }

        return node;
    }

    /// <summary>
    ///     Perform a left (counter-clockwise) rotation.
    /// </summary>
    /// <param name="node">Node to rotate about.</param>
    /// <returns>New node with rotation applied.</returns>
    private static AvlTreeNode<TKey> RotateLeft(AvlTreeNode<TKey> node)
    {
        var temp1 = node;
        var temp2 = node.Right!.Left;
        node = node.Right;
        node.Left = temp1;
        node.Left.Right = temp2;

        node.Left.UpdateBalanceFactor();
        node.UpdateBalanceFactor();

        return node;
    }

    /// <summary>
    ///     Perform a right (clockwise) rotation.
    /// </summary>
    /// <param name="node">Node to rotate about.</param>
    /// <returns>New node with rotation applied.</returns>
    private static AvlTreeNode<TKey> RotateRight(AvlTreeNode<TKey> node)
    {
        var temp1 = node;
        var temp2 = node.Left!.Right;
        node = node.Left;
        node.Right = temp1;
        node.Right.Left = temp2;

        node.Right.UpdateBalanceFactor();
        node.UpdateBalanceFactor();

        return node;
    }

    /// <summary>
    ///     Helper function to get node instance with minimum key value
    ///     in the specified subtree.
    /// </summary>
    /// <param name="node">Node specifying root of subtree.</param>
    /// <returns>Minimum value in node's subtree.</returns>
    private static AvlTreeNode<TKey> GetMin(AvlTreeNode<TKey> node)
    {
        while (node.Left is not null)
        {
            node = node.Left;
        }

        return node;
    }

    /// <summary>
    ///     Helper function to get node instance with maximum key value
    ///     in the specified subtree.
    /// </summary>
    /// <param name="node">Node specifying root of subtree.</param>
    /// <returns>Maximum value in node's subtree.</returns>
    private static AvlTreeNode<TKey> GetMax(AvlTreeNode<TKey> node)
    {
        while (node.Right is not null)
        {
            node = node.Right;
        }

        return node;
    }

    /// <summary>
    ///     Recursively function to add a node to the tree.
    /// </summary>
    /// <param name="node">Node to check for null leaf.</param>
    /// <param name="key">Key value to add.</param>
    /// <returns>New node with key inserted.</returns>
    private AvlTreeNode<TKey> Add(AvlTreeNode<TKey> node, TKey key)
    {
        // Regular binary search tree insertion
        var compareResult = comparer.Compare(key, node.Key);
        if (compareResult < 0)
        {
            if (node.Left is null)
            {
                var newNode = new AvlTreeNode<TKey>(key);
                node.Left = newNode;
            }
            else
            {
                node.Left = Add(node.Left, key);
            }
        }
        else if (compareResult > 0)
        {
            if (node.Right is null)
            {
                var newNode = new AvlTreeNode<TKey>(key);
                node.Right = newNode;
            }
            else
            {
                node.Right = Add(node.Right, key);
            }
        }
        else
        {
            throw new ArgumentException($"""Key "{key}" already exists in AVL tree.""");
        }

        // Check all of the new node's ancestors for imbalance and perform
        // necessary rotations
        node.UpdateBalanceFactor();

        return Rebalance(node);
    }

    /// <summary>
    ///     Recursive function to remove node from tree.
    /// </summary>
    /// <param name="node">Node to check for key.</param>
    /// <param name="key">Key value to remove.</param>
    /// <returns>New node with key removed.</returns>
    private AvlTreeNode<TKey>? Remove(AvlTreeNode<TKey>? node, TKey key)
    {
        if (node == null)
        {
            throw new KeyNotFoundException(
                $"""Key "{key}" is not in the AVL tree.""");
        }

        // Normal binary search tree removal
        var compareResult = comparer.Compare(key, node.Key);
        if (compareResult < 0)
        {
            node.Left = Remove(node.Left, key);
        }
        else if (compareResult > 0)
        {
            node.Right = Remove(node.Right, key);
        }
        else
        {
            if (node.Left is null && node.Right is null)
            {
                return null;
            }

            if (node.Left is null)
            {
                var successor = GetMin(node.Right!);
                node.Right = Remove(node.Right!, successor.Key);
                node.Key = successor.Key;
            }
            else
            {
                var predecessor = GetMax(node.Left!);
                node.Left = Remove(node.Left!, predecessor.Key);
                node.Key = predecessor.Key;
            }
        }

        // Check all of the removed node's ancestors for rebalance and
        // perform necessary rotations.
        node.UpdateBalanceFactor();

        return Rebalance(node);
    }
}

namespace DataStructures.AVLTree;

/// <summary>
///     Generic class to represent nodes in an <see cref="AvlTree{TKey}"/>
///     instance.
/// </summary>
/// <typeparam name="TKey">The type of key for the node.</typeparam>
/// <remarks>
///     Initializes a new instance of the
///     <see cref="AvlTreeNode{TKey}"/> class.
/// </remarks>
/// <param name="key">Key value for node.</param>
internal class AvlTreeNode<TKey>(TKey key)
{
    /// <summary>
    ///     Gets or sets key value of node.
    /// </summary>
    public TKey Key { get; set; } = key;

    /// <summary>
    ///     Gets the balance factor of the node.
    /// </summary>
    public int BalanceFactor { get; private set; }

    /// <summary>
    ///     Gets or sets the left child of the node.
    /// </summary>
    public AvlTreeNode<TKey>? Left { get; set; }

    /// <summary>
    ///     Gets or sets the right child of the node.
    /// </summary>
    public AvlTreeNode<TKey>? Right { get; set; }

    /// <summary>
    ///     Gets or sets the height of the node.
    /// </summary>
    private int Height { get; set; }

    /// <summary>
    ///     Update the node's height and balance factor.
    /// </summary>
    public void UpdateBalanceFactor()
    {
        if (Left is null && Right is null)
        {
            Height = 0;
            BalanceFactor = 0;
        }
        else if (Left is null)
        {
            Height = Right!.Height + 1;
            BalanceFactor = Height;
        }
        else if (Right is null)
        {
            Height = Left!.Height + 1;
            BalanceFactor = -Height;
        }
        else
        {
            Height = Math.Max(Left.Height, Right.Height) + 1;
            BalanceFactor = Right.Height - Left.Height;
        }
    }
}

namespace DataStructures.BTree;

/// <summary>
///     Generic class to represent nodes in a <see cref="BTree{TKey}"/>
///     instance.
/// </summary>
/// <typeparam name="TKey">The type of key for the node.</typeparam>
/// <remarks>
///     Initializes a new instance of the
///     <see cref="BTreeNode{TKey}"/> class.
/// </remarks>
/// <param name="minDegree">Minimum degree of the B-Tree.</param>
/// <param name="isLeaf">Whether this node is a leaf node.</param>
internal class BTreeNode<TKey>(int minDegree, bool isLeaf)
{
    /// <summary>
    ///     Gets the minimum degree (t) of the B-Tree.
    ///     A node can contain at most 2t-1 keys and at least t-1 keys (except root).
    /// </summary>
    public int MinDegree { get; } = minDegree;

    /// <summary>
    ///     Gets or sets a value indicating whether this node is a leaf node.
    /// </summary>
    public bool IsLeaf { get; set; } = isLeaf;

    /// <summary>
    ///     Gets or sets the current number of keys stored in this node.
    /// </summary>
    public int KeyCount { get; internal set; }

    /// <summary>
    ///     Gets the array of keys stored in this node.
    ///     Maximum size is 2*MinDegree - 1.
    /// </summary>
    public TKey[] Keys { get; } = new TKey[2 * minDegree - 1];

    /// <summary>
    ///     Gets the array of child pointers.
    ///     Maximum size is 2*MinDegree.
    /// </summary>
    public BTreeNode<TKey>?[] Children { get; } = new BTreeNode<TKey>[2 * minDegree];

    /// <summary>
    ///     Inserts a key at the specified position in the keys array.
    /// </summary>
    /// <param name="index">Position to insert the key.</param>
    /// <param name="key">Key to insert.</param>
    public void InsertKey(int index, TKey key)
    {
        Keys[index] = key;
        KeyCount++;
    }

    /// <summary>
    ///     Removes the key at the specified position in the keys array.
    /// </summary>
    /// <param name="index">Position of the key to remove.</param>
    public void RemoveKey(int index)
    {
        for (var i = index; i < KeyCount - 1; i++)
        {
            Keys[i] = Keys[i + 1];
        }

        Keys[KeyCount - 1] = default!;
        KeyCount--;
    }

    /// <summary>
    ///     Inserts a child pointer at the specified position.
    /// </summary>
    /// <param name="index">Position to insert the child.</param>
    /// <param name="child">Child node to insert.</param>
    public void InsertChild(int index, BTreeNode<TKey> child)
    {
        Children[index] = child;
    }

    /// <summary>
    ///     Checks if the node is full (contains maximum number of keys).
    /// </summary>
    /// <returns>True if the node is full, false otherwise.</returns>
    public bool IsFull() => KeyCount == 2 * MinDegree - 1;
}

using System.Collections;
using System.Collections.Generic;

namespace DataStructures.Bag;

/// <summary>
/// Implementation of a Bag (or multiset) data structure using a basic linked list.
/// </summary>
/// <remarks>
/// A bag (or multiset, or mset) is a modification of the concept of a set that, unlike a set, allows for multiple instances for each of its elements.
/// The number of instances given for each element is called the multiplicity of that element in the multiset.
/// As a consequence, an infinite number of multisets exist that contain only elements a and b, but vary in the multiplicities of their elements.
/// See https://en.wikipedia.org/wiki/Multiset for more information.
/// </remarks>
/// <typeparam name="T">Generic Type.</typeparam>
public class Bag<T> : IEnumerable<T> where T : notnull
{
    private BagNode<T>? head;
    private int totalCount;

    /// <summary>
    /// Initializes a new instance of the <see cref="Bag{T}" /> class.
    /// </summary>
    public Bag()
    {
        head = null;
        totalCount = 0;
    }

    /// <summary>
    /// Adds an item to the bag. If the item already exists, increases its multiplicity.
    /// </summary>
    public void Add(T item)
    {
        // If the bag is empty, create the first node
        if (head == null)
        {
            head = new BagNode<T>(item);
            totalCount = 1;
            return;
        }

        // Check if item already exists
        var current = head;
        BagNode<T>? previous = null;

        while (current != null)
        {
            if (EqualityComparer<T>.Default.Equals(current.Item, item))
            {
                current.Multiplicity++;
                totalCount++;
                return;
            }

            previous = current;
            current = current.Next;
        }

        previous!.Next = new BagNode<T>(item);
        totalCount++;
    }

    /// <summary>
    /// Clears the bag.
    /// </summary>
    public void Clear()
    {
        head = null;
        totalCount = 0;
    }

    /// <summary>
    /// Gets the number of items in the bag.
    /// </summary>
    public int Count => totalCount;

    /// <summary>
    /// Returns a boolean indicating whether the bag is empty.
    /// </summary>
    public bool IsEmpty() => head == null;

    /// <summary>
    /// Returns an enumerator that iterates through the bag.
    /// </summary>
    public IEnumerator<T> GetEnumerator()
    {
        var current = head;

        while (current != null)
        {
            // Yield the item as many times as its multiplicity, pretending they are separate items
            for (var i = 0; i < current.Multiplicity; i++)
            {
                yield return current.Item;
            }

            current = current.Next;
        }
    }

    /// <summary>
    /// Returns an enumerator that iterates through the bag.
    /// </summary>
    IEnumerator IEnumerable.GetEnumerator() => GetEnumerator();
}

