        var sequence2 = two.ToString();

        // for scaling of same length.
        if (one.Length != two.Length)
        {
            var tmp = new StringBuilder();
            int difference;
            if (one.Length > two.Length)
            {
                // one is greater
                difference = one.Length - two.Length;

