		lfuCache.Put("2", 2)
		lfuCache.Put("3", 3)
		lfuCache.Put("4", 4)

		got := lfuCache.Get("1")
		if got != nil {
			t.Errorf("expected: nil, got: %v", got)
		}
	})

	t.Run("test 4: Put key over capacity but recent key exists", func(t *testing.T) {
		lfuCache.Put("4", 4)
		lfuCache.Put("3", 3)
		lfuCache.Put("2", 2)
		lfuCache.Put("1", 1)

