 */
package problem5

func Problem5(limit uint) uint {
	n := limit * limit

	for {
		if isDivisible(n, limit) {
			return n
		}

		n++
	}
}

func isDivisible(n, limit uint) bool {
	for i := uint(1); i <= limit; i++ {
		if n%i != 0 {
			return false
		}
	}

	return true
}

