/**
 * @author <a href="https://github.com/siddhant2002">Siddhant Swarup Mallick</a>

 * In mathematics, the Golomb sequence is a non-decreasing integer sequence where n-th term is equal
 * to number of times n appears in the sequence.

 * <a href="https://en.wikipedia.org/wiki/Golomb_sequence">Wikipedia</a>
 * Program description - To find the Golomb sequence upto n
 */
public final class CountFriendsPairing {
    private CountFriendsPairing() {
    }

    public static boolean countFriendsPairing(int n, int[] a) {
        int[] dp = new int[n + 1];
        // array of n+1 size is created
        dp[0] = 1;
        // since 1st index position value is fixed so it's marked as 1
        for (int i = 1; i < n; i++) {
            dp[i] = 1 + dp[i - dp[dp[i - 1]]];
            // formula for ith golomb sequence is dp(i) = 1 + dp(i – dp(dp(i - 1)))
        }
        for (int i = 1; i < n; i++) {
            if (a[i - 1] != dp[i]) {
                return false;
                // checks whether the calculated answer matches with the expected answer
            }
        }
        return true;
        // returns true if calculated answer matches with the expected answer
    }
}

package com.thealgorithms.dynamicprogramming;

import java.util.HashMap;
import java.util.Map;

/**
 * Implementation of the full Damerau–Levenshtein distance algorithm.
 *
 * This algorithm calculates the minimum number of operations required
 * to transform one string into another. Supported operations are:
 * insertion, deletion, substitution, and transposition of adjacent characters.
 *
 * Unlike the restricted version (OSA), this implementation allows multiple
 * edits on the same substring, computing the true edit distance.
 *
 * Time Complexity: O(n * m * max(n, m))
 * Space Complexity: O(n * m)
 */
public final class DamerauLevenshteinDistance {

    private DamerauLevenshteinDistance() {
        // Utility class
    }

    /**
     * Computes the full Damerau–Levenshtein distance between two strings.
     *
     * @param s1 the first string
     * @param s2 the second string
     * @return the minimum edit distance between the two strings
     * @throws IllegalArgumentException if either input string is null
     */
    public static int distance(String s1, String s2) {
        validateInputs(s1, s2);

        int n = s1.length();
        int m = s2.length();

        Map<Character, Integer> charLastPosition = buildCharacterMap(s1, s2);
        int[][] dp = initializeTable(n, m);

        fillTable(s1, s2, dp, charLastPosition);

        return dp[n + 1][m + 1];
    }

    /**
     * Validates that both input strings are not null.
     *
     * @param s1 the first string to validate
     * @param s2 the second string to validate
     * @throws IllegalArgumentException if either string is null
     */
    private static void validateInputs(String s1, String s2) {
        if (s1 == null || s2 == null) {
            throw new IllegalArgumentException("Input strings must not be null.");
        }
    }

    /**
     * Builds a character map containing all unique characters from both strings.
     * Each character is initialized with a position value of 0.
     *
     * This map is used to track the last occurrence position of each character
     * during the distance computation, which is essential for handling transpositions.
     *
     * @param s1 the first string
     * @param s2 the second string
     * @return a map containing all unique characters from both strings, initialized to 0
     */
    private static Map<Character, Integer> buildCharacterMap(String s1, String s2) {
        Map<Character, Integer> charMap = new HashMap<>();
        for (char c : s1.toCharArray()) {
            charMap.putIfAbsent(c, 0);
        }
        for (char c : s2.toCharArray()) {
            charMap.putIfAbsent(c, 0);
        }
        return charMap;
    }

    /**
     * Initializes the dynamic programming table for the algorithm.
     *
     * The table has dimensions (n+2) x (m+2) where n and m are the lengths
     * of the input strings. The extra rows and columns are used to handle
     * the transposition operation correctly.
     *
     * The first row and column are initialized with the maximum possible distance,
     * while the second row and column represent the base case of transforming
     * from an empty string.
     *
     * @param n the length of the first string
     * @param m the length of the second string
     * @return an initialized DP table ready for computation
     */
    private static int[][] initializeTable(int n, int m) {
        int maxDist = n + m;
        int[][] dp = new int[n + 2][m + 2];

        dp[0][0] = maxDist;

        for (int i = 0; i <= n; i++) {
            dp[i + 1][0] = maxDist;
            dp[i + 1][1] = i;
        }

        for (int j = 0; j <= m; j++) {
            dp[0][j + 1] = maxDist;
            dp[1][j + 1] = j;
        }

        return dp;
    }

    /**
     * Fills the dynamic programming table by computing the minimum edit distance
     * for each substring pair.
     *
     * This method implements the core algorithm logic, iterating through both strings
     * and computing the minimum cost of transforming substrings. It considers all
     * four operations: insertion, deletion, substitution, and transposition.
     *
     * The character position map is updated as we progress through the first string
     * to enable efficient transposition cost calculation.
     *
     * @param s1 the first string
     * @param s2 the second string
     * @param dp the dynamic programming table to fill
     * @param charLastPosition map tracking the last position of each character in s1
     */
    private static void fillTable(String s1, String s2, int[][] dp, Map<Character, Integer> charLastPosition) {
        int n = s1.length();
        int m = s2.length();

        for (int i = 1; i <= n; i++) {
            int lastMatchCol = 0;

            for (int j = 1; j <= m; j++) {
                char char1 = s1.charAt(i - 1);
                char char2 = s2.charAt(j - 1);

                int lastMatchRow = charLastPosition.get(char2);
                int cost = (char1 == char2) ? 0 : 1;

                if (char1 == char2) {
                    lastMatchCol = j;
                }

                dp[i + 1][j + 1] = computeMinimumCost(dp, i, j, lastMatchRow, lastMatchCol, cost);
            }

            charLastPosition.put(s1.charAt(i - 1), i);
        }
    }

    /**
     * Computes the minimum cost among all possible operations at the current position.
     *
     * This method evaluates four possible operations:
     * 1. Substitution: replace character at position i with character at position j
     * 2. Insertion: insert character from s2 at position j
     * 3. Deletion: delete character from s1 at position i
     * 4. Transposition: swap characters that have been seen before
     *
     * The transposition cost accounts for the gap between the current position
     * and the last position where matching characters were found.
     *
     * @param dp the dynamic programming table
     * @param i the current position in the first string (1-indexed in the DP table)
     * @param j the current position in the second string (1-indexed in the DP table)
     * @param lastMatchRow the row index where the current character of s2 last appeared in s1
     * @param lastMatchCol the column index where the current character of s1 last matched in s2
     * @param cost the substitution cost (0 if characters match, 1 otherwise)
     * @return the minimum cost among all operations
     */
    private static int computeMinimumCost(int[][] dp, int i, int j, int lastMatchRow, int lastMatchCol, int cost) {
        int substitution = dp[i][j] + cost;
        int insertion = dp[i + 1][j] + 1;
        int deletion = dp[i][j + 1] + 1;
        int transposition = dp[lastMatchRow][lastMatchCol] + i - lastMatchRow - 1 + 1 + j - lastMatchCol - 1;

        return Math.min(Math.min(substitution, insertion), Math.min(deletion, transposition));
    }
}

package com.thealgorithms.dynamicprogramming;

// Given N dice each with M faces, numbered from 1 to M, find the number of ways to get sum X.
// X is the summation of values on each face when all the dice are thrown.

/* The Naive approach is to find all the possible combinations of values from n dice and
keep on counting the results that sum to X. This can be done using recursion. */
// The above recursion solution exhibits overlapping subproblems.

/* Hence, storing the results of the solved sub-problems saves time.
And it can be done using Dynamic Programming(DP).
// Time Complexity: O(m * n * x) where m is number of faces, n is number of dice and x is given sum.
Following is implementation of Dynamic Programming approach. */
// Code ---->
// Java program to find number of ways to get sum 'x' with 'n'
// dice where every dice has 'm' faces
final class DP {
    private DP() {
    }

    /* The main function that returns the number of ways to get sum 'x' with 'n' dice and 'm' with m
     * faces. */
    public static long findWays(int m, int n, int x) {
        /* Create a table to store the results of subproblems.
    One extra row and column are used for simplicity
    (Number of dice is directly used as row index and sum is directly used as column index).
    The entries in 0th row and 0th column are never used. */
        long[][] table = new long[n + 1][x + 1];

        /* Table entries for only one dice */
        for (int j = 1; j <= m && j <= x; j++) {
            table[1][j] = 1;
        }

        /* Fill rest of the entries in table using recursive relation
    i: number of dice, j: sum */
        for (int i = 2; i <= n; i++) {
            for (int j = 1; j <= x; j++) {
                for (int k = 1; k < j && k <= m; k++) {
                    table[i][j] += table[i - 1][j - k];
                }
            }
        }

        return table[n][x];
    }
}

package com.thealgorithms.dynamicprogramming;
import java.util.Arrays;

/**
 * A generalized template for the Digit Dynamic Programming (Digit DP)
 * technique.
 * Digit DP is used to count numbers within a range [L, R] that satisfy specific
 * digit properties.
 * This specific implementation demonstrates counting the numbers whose digit
 * sum equals a target value.
 *
 * <p>
 * Example:
 * countRangeWithDigitSum(1, 100, 5) returns 6 (numbers: 5, 14, 23, 32, 41, 50)
 */
public final class DigitDP {

    // Maximum theoretical digit sum for a 64-bit signed long integer (9 * 19 digits
    // = 171)
    private static final int MAX_DIGIT_SUM = 171;

    private DigitDP() {
        // Prevent instantiation for utility/algorithm template class
    }

    /**
     * Counts how many numbers in the range [L, R] have a digit sum equal to the
     * target.
     *
     * @param l      The lower bound of the range (inclusive).
     * @param r      The upper bound of the range (inclusive).
     * @param target The exact sum of digits required.
     * @return The count of valid integers.
     */
    public static long countRangeWithDigitSum(long l, long r, int target) {
        if (l > r || target < 0 || target > MAX_DIGIT_SUM) {
            return 0;
        }
        long countR = countWithDigitSum(r, target);
        long countLMinus1 = countWithDigitSum(l - 1, target);
        return countR - countLMinus1;
    }

    private static long countWithDigitSum(long number, int target) {
        if (number < 0) {
            return 0;
        }
        String numStr = Long.toString(number);
        int length = numStr.length();

        // dp[index][current_sum][tight]
        long[][][] dp = new long[length][MAX_DIGIT_SUM + 1][2];
        for (long[][] row : dp) {
            for (long[] col : row) {
                Arrays.fill(col, -1);
            }
        }

        return solve(0, 0, 1, numStr, target, dp);
    }

    /**
     * Recursive memoized function to explore digit placements.
     *
     * Time Complexity: O(number_of_digits * target_sum * 10)
     * Space Complexity: O(number_of_digits * target_sum * 2)
     *
     * @param index      Current digit position from left to right (most significant
     *                   first).
     * @param currentSum Cumulative sum of digits chosen so far.
     * @param tight      Flag indicating if current prefix matches the original
     *                   number boundary.
     * @param numStr     String representation of the upper ceiling limit.
     * @param target     The exact required sum of digits.
     * @param dp         Memoization matrix cache table.
     * @return Total valid combinations from the current state configuration.
     */
    private static long solve(int index, int currentSum, int tight, String numStr, int target, long[][][] dp) {
        // Base case: If we have processed all digits
        if (index == numStr.length()) {
            return currentSum == target ? 1 : 0;
        }

        // Return memoized state if already evaluated
        if (dp[index][currentSum][tight] != -1) {
            return dp[index][currentSum][tight];
        }

        long ans = 0;
        // Determine the maximum limit for the current position digit
        int limit = (tight == 1) ? (numStr.charAt(index) - '0') : 9;

        // Iterate through all possible valid digits for this position
        for (int digit = 0; digit <= limit; digit++) {
            int nextSum = currentSum + digit;

            // Optimization: If the digit sum exceeds the target, prune branch
            if (nextSum > target) {
                continue;
            }

            // Next state remains tight only if current state is tight and we place the
            // exact limit digit
            int nextTight = (tight == 1 && digit == limit) ? 1 : 0;
            ans += solve(index + 1, nextSum, nextTight, numStr, target, dp);
        }

        dp[index][currentSum][tight] = ans;
        return ans;
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * A DynamicProgramming based solution for Edit Distance problem In Java
 * Description of Edit Distance with an Example:
 *
 * <p>
 * Edit distance is a way of quantifying how dissimilar two strings (e.g.,
 * words) are to one another, by counting the minimum number of operations
 * required to transform one string into the other. The distance operations are
 * the removal, insertion, or substitution of a character in the string.
 *
 * <p>
 *
 * <p>
 * The Distance between "kitten" and "sitting" is 3. A minimal edit script that
 * transforms the former into the latter is:
 *
 * <p>
 * kitten → sitten (substitution of "s" for "k") sitten → sittin (substitution
 * of "i" for "e") sittin → sitting (insertion of "g" at the end).
 *
 * @author SUBHAM SANGHAI
 */
public final class EditDistance {
    private EditDistance() {
    }

    public static int minDistance(String word1, String word2) {
        int len1 = word1.length();
        int len2 = word2.length();
        // len1+1, len2+1, because finally return dp[len1][len2]
        int[][] dp = new int[len1 + 1][len2 + 1];
        /* If second string is empty, the only option is to
    insert all characters of first string into second*/
        for (int i = 0; i <= len1; i++) {
            dp[i][0] = i;
        }
        /* If first string is empty, the only option is to
    insert all characters of second string into first*/
        for (int j = 0; j <= len2; j++) {
            dp[0][j] = j;
        }
        // iterate though, and check last char
        for (int i = 0; i < len1; i++) {
            char c1 = word1.charAt(i);
            for (int j = 0; j < len2; j++) {
                char c2 = word2.charAt(j);
                // if last two chars equal
                if (c1 == c2) {
                    // update dp value for +1 length
                    dp[i + 1][j + 1] = dp[i][j];
                } else {
                    /* if two characters are different ,
          then take the minimum of the various operations(i.e insertion,removal,substitution)*/
                    int replace = dp[i][j] + 1;
                    int insert = dp[i][j + 1] + 1;
                    int delete = dp[i + 1][j] + 1;

                    int min = Math.min(replace, insert);
                    min = Math.min(delete, min);
                    dp[i + 1][j + 1] = min;
                }
            }
        }
        /* return the final answer , after traversing through both the strings*/
        return dp[len1][len2];
    }

    // edit distance problem
    public static int editDistance(String s1, String s2) {
        int[][] storage = new int[s1.length() + 1][s2.length() + 1];
        return editDistance(s1, s2, storage);
    }

    public static int editDistance(String s1, String s2, int[][] storage) {
        int m = s1.length();
        int n = s2.length();
        if (storage[m][n] > 0) {
            return storage[m][n];
        }
        if (m == 0) {
            storage[m][n] = n;
            return storage[m][n];
        }
        if (n == 0) {
            storage[m][n] = m;
            return storage[m][n];
        }
        if (s1.charAt(0) == s2.charAt(0)) {
            storage[m][n] = editDistance(s1.substring(1), s2.substring(1), storage);
        } else {
            int op1 = editDistance(s1, s2.substring(1), storage);
            int op2 = editDistance(s1.substring(1), s2, storage);
            int op3 = editDistance(s1.substring(1), s2.substring(1), storage);
            storage[m][n] = 1 + Math.min(op1, Math.min(op2, op3));
        }
        return storage[m][n];
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * DynamicProgramming solution for the Egg Dropping Puzzle
 */
public final class EggDropping {
    private EggDropping() {
    }

    // min trials with n eggs and m floors
    public static int minTrials(int n, int m) {
        int[][] eggFloor = new int[n + 1][m + 1];
        int result;
        int x;

        for (int i = 1; i <= n; i++) {
            eggFloor[i][0] = 0; // Zero trial for zero floor.
            eggFloor[i][1] = 1; // One trial for one floor
        }

        // j trials for only 1 egg
        for (int j = 1; j <= m; j++) {
            eggFloor[1][j] = j;
        }

        // Using bottom-up approach in DP
        for (int i = 2; i <= n; i++) {
            for (int j = 2; j <= m; j++) {
                eggFloor[i][j] = Integer.MAX_VALUE;
                for (x = 1; x <= j; x++) {
                    result = 1 + Math.max(eggFloor[i - 1][x - 1], eggFloor[i][j - x]);

                    // choose min of all values for particular x
                    if (result < eggFloor[i][j]) {
                        eggFloor[i][j] = result;
                    }
                }
            }
        }

        return eggFloor[n][m];
    }

    public static void main(String[] args) {
        int n = 2;
        int m = 4;
        // result outputs min no. of trials in worst case for n eggs and m floors
        int result = minTrials(n, m);
        System.out.println(result);
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * This class implements Kadane's Algorithm to find the maximum subarray sum
 * within a given array of integers. The algorithm efficiently computes the maximum
 * sum of a contiguous subarray in linear time.
 *
 * Author: <a href="https://github.com/siddhant2002">Siddhant Swarup Mallick</a>
 */
public final class KadaneAlgorithm {
    private KadaneAlgorithm() {
    }

    /**
     * Computes the maximum subarray sum using Kadane's Algorithm and checks
     * if it matches a predicted answer.
     *
     * @param a              The input array of integers for which the maximum
     *                       subarray sum is to be calculated.
     * @param predictedAnswer The expected maximum subarray sum to be verified
     *                       against the computed sum.
     * @return true if the computed maximum subarray sum equals the predicted
     *         answer, false otherwise.
     *
     * <p>Example:</p>
     * <pre>
     * Input: {89, 56, 98, 123, 26, 75, 12, 40, 39, 68, 91}
     * Output: true if the maximum subarray sum is equal to the
     *         predicted answer.
     * </pre>
     *
     * <p>Algorithmic Complexity:</p>
     * <ul>
     * <li>Time Complexity: O(n) - the algorithm iterates through the array once.</li>
     * <li>Auxiliary Space Complexity: O(1) - only a constant amount of additional space is used.</li>
     * </ul>
     */
    public static boolean maxSum(int[] a, int predictedAnswer) {
        int sum = a[0];
        int runningSum = 0;

        for (int k : a) {
            runningSum += k;
            sum = Math.max(sum, runningSum);
            if (runningSum < 0) {
                runningSum = 0;
            }
        }

        return sum == predictedAnswer;
    }
}

package com.thealgorithms.dynamicprogramming;

import java.util.Arrays;

/**
 * 0/1 Knapsack Problem - Dynamic Programming solution.
 *
 * This algorithm solves the classic optimization problem where we have n items,
 * each with a weight and a value. The goal is to maximize the total value
 * without exceeding the knapsack's weight capacity.
 *
 * Time Complexity: O(n * W)
 * Space Complexity: O(W)
 *
 * Example:
 * values = {60, 100, 120}
 * weights = {10, 20, 30}
 * W = 50
 * Output: 220
 *
 * @author Arpita
 * @see <a href="https://en.wikipedia.org/wiki/Knapsack_problem">Knapsack Problem</a>
 */
public final class Knapsack {

    private Knapsack() {
    }

    /**
     * Validates the input to ensure correct constraints.
     */
    private static void throwIfInvalidInput(final int weightCapacity, final int[] weights, final int[] values) {
        if (weightCapacity < 0) {
            throw new IllegalArgumentException("Weight capacity should not be negative.");
        }
        if (weights == null || values == null || weights.length != values.length) {
            throw new IllegalArgumentException("Weights and values must be non-null and of the same length.");
        }
        if (Arrays.stream(weights).anyMatch(w -> w <= 0)) {
            throw new IllegalArgumentException("Weights must be positive.");
        }
    }

    /**
     * Solves the 0/1 Knapsack problem using Dynamic Programming (bottom-up approach).
     *
     * @param weightCapacity The maximum weight capacity of the knapsack.
     * @param weights        The array of item weights.
     * @param values         The array of item values.
     * @return The maximum total value achievable without exceeding capacity.
     */
    public static int knapSack(final int weightCapacity, final int[] weights, final int[] values) {
        throwIfInvalidInput(weightCapacity, weights, values);

        int[] dp = new int[weightCapacity + 1];

        // Fill dp[] array iteratively
        for (int i = 0; i < values.length; i++) {
            for (int w = weightCapacity; w >= weights[i]; w--) {
                dp[w] = Math.max(dp[w], dp[w - weights[i]] + values[i]);
            }
        }

        return dp[weightCapacity];
    }

    /*
    // Example main method for local testing only.
    public static void main(String[] args) {
        int[] values = {60, 100, 120};
        int[] weights = {10, 20, 30};
        int weightCapacity = 50;

        int maxValue = knapSack(weightCapacity, weights, values);
        System.out.println("Maximum value = " + maxValue); // Output: 220
    }
    */
}

package com.thealgorithms.dynamicprogramming;

import java.util.Arrays;

/**
 * Recursive Solution for 0-1 knapsack with memoization
 * This method is basically an extension to the recursive approach so that we
 * can overcome the problem of calculating redundant cases and thus increased
 * complexity. We can solve this problem by simply creating a 2-D array that can
 * store a particular state (n, w) if we get it the first time.
 */
public class KnapsackMemoization {

    int knapSack(int capacity, int[] weights, int[] profits, int numOfItems) {

        // Declare the table dynamically
        int[][] dpTable = new int[numOfItems + 1][capacity + 1];

        // Loop to initially fill the table with -1
        for (int[] table : dpTable) {
            Arrays.fill(table, -1);
        }

        return solveKnapsackRecursive(capacity, weights, profits, numOfItems, dpTable);
    }

    // Returns the value of maximum profit using recursive approach
    int solveKnapsackRecursive(int capacity, int[] weights, int[] profits, int numOfItems, int[][] dpTable) {
        // Base condition
        if (numOfItems == 0 || capacity == 0) {
            return 0;
        }

        if (dpTable[numOfItems][capacity] != -1) {
            return dpTable[numOfItems][capacity];
        }

        if (weights[numOfItems - 1] > capacity) {
            // Store the value of function call stack in table
            dpTable[numOfItems][capacity] = solveKnapsackRecursive(capacity, weights, profits, numOfItems - 1, dpTable);
        } else {
            // case 1. include the item, if it is less than the capacity
            final int includeCurrentItem = profits[numOfItems - 1] + solveKnapsackRecursive(capacity - weights[numOfItems - 1], weights, profits, numOfItems - 1, dpTable);

            // case 2. exclude the item if it is more than the capacity
            final int excludeCurrentItem = solveKnapsackRecursive(capacity, weights, profits, numOfItems - 1, dpTable);

            // Store the value of function call stack in table and return
            dpTable[numOfItems][capacity] = Math.max(includeCurrentItem, excludeCurrentItem);
        }
        return dpTable[numOfItems][capacity];
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * The {@code KnapsackZeroOne} provides Recursive solution for the 0/1 Knapsack
 * problem. Solves by exploring all combinations of items using recursion. No
 * memoization or dynamic programming optimizations are applied.
 *
 * Time Complexity: O(2^n) — explores all subsets.
 * Space Complexity: O(n) — due to recursive call stack.
 *
 * Problem Reference: https://en.wikipedia.org/wiki/Knapsack_problem
 */
public final class KnapsackZeroOne {

    private KnapsackZeroOne() {
        // Prevent instantiation
    }

    /**
     * Solves the 0/1 Knapsack problem using recursion.
     *
     * @param values   the array containing values of the items
     * @param weights  the array containing weights of the items
     * @param capacity the total capacity of the knapsack
     * @param n        the number of items
     * @return the maximum total value achievable within the given weight limit
     * @throws IllegalArgumentException if input arrays are null, empty, or
     *     lengths mismatch
     */
    public static int compute(final int[] values, final int[] weights, final int capacity, final int n) {
        if (values == null || weights == null) {
            throw new IllegalArgumentException("Input arrays cannot be null.");
        }
        if (values.length != weights.length) {
            throw new IllegalArgumentException("Value and weight arrays must be of the same length.");
        }
        if (capacity < 0 || n < 0) {
            throw new IllegalArgumentException("Invalid input: arrays must be non-empty and capacity/n "
                + "non-negative.");
        }
        if (n == 0 || capacity == 0 || values.length == 0) {
            return 0;
        }

        if (weights[n - 1] <= capacity) {
            final int include = values[n - 1] + compute(values, weights, capacity - weights[n - 1], n - 1);
            final int exclude = compute(values, weights, capacity, n - 1);
            return Math.max(include, exclude);
        } else {
            return compute(values, weights, capacity, n - 1);
        }
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * Tabulation (Bottom-Up) Solution for 0-1 Knapsack Problem.
 * This method uses dynamic programming to build up a solution iteratively,
 * filling a 2-D array where each entry dp[i][w] represents the maximum value
 * achievable with the first i items and a knapsack capacity of w.
 *
 * The tabulation approach is efficient because it avoids redundant calculations
 * by solving all subproblems in advance and storing their results, ensuring
 * each subproblem is solved only once. This is a key technique in dynamic programming,
 * making it possible to solve problems that would otherwise be infeasible due to
 * exponential time complexity in naive recursive solutions.
 *
 * Time Complexity: O(n * W), where n is the number of items and W is the knapsack capacity.
 * Space Complexity: O(n * W) for the DP table.
 *
 * For more information, see:
 * https://en.wikipedia.org/wiki/Knapsack_problem#Dynamic_programming
 */
public final class KnapsackZeroOneTabulation {

    private KnapsackZeroOneTabulation() {
        // Prevent instantiation
    }

    /**
     * Solves the 0-1 Knapsack problem using the bottom-up tabulation technique.
     * @param values the values of the items
     * @param weights the weights of the items
     * @param capacity the total capacity of the knapsack
     * @param itemCount the number of items
     * @return the maximum value that can be put in the knapsack
     * @throws IllegalArgumentException if input arrays are null, of different lengths,or if capacity or itemCount is invalid
     */
    public static int compute(final int[] values, final int[] weights, final int capacity, final int itemCount) {
        if (values == null || weights == null) {
            throw new IllegalArgumentException("Values and weights arrays must not be null.");
        }
        if (values.length != weights.length) {
            throw new IllegalArgumentException("Values and weights arrays must be non-null and of same length.");
        }
        if (capacity < 0) {
            throw new IllegalArgumentException("Capacity must not be negative.");
        }
        if (itemCount < 0 || itemCount > values.length) {
            throw new IllegalArgumentException("Item count must be between 0 and the length of the values array.");
        }

        final int[][] dp = new int[itemCount + 1][capacity + 1];

        for (int i = 1; i <= itemCount; i++) {
            final int currentValue = values[i - 1];
            final int currentWeight = weights[i - 1];

            for (int w = 1; w <= capacity; w++) {
                if (currentWeight <= w) {
                    final int includeItem = currentValue + dp[i - 1][w - currentWeight];
                    final int excludeItem = dp[i - 1][w];
                    dp[i][w] = Math.max(includeItem, excludeItem);
                } else {
                    dp[i][w] = dp[i - 1][w];
                }
            }
        }

        return dp[itemCount][capacity];
    }
}

package com.thealgorithms.dynamicprogramming;

import java.util.stream.IntStream;

/**
 * Provides functions to calculate the Levenshtein distance between two strings.
 *
 * The Levenshtein distance is a measure of the similarity between two strings by calculating the minimum number of single-character
 * edits (insertions, deletions, or substitutions) required to change one string into the other.
 */
public final class LevenshteinDistance {
    private LevenshteinDistance() {
    }

    /**
     * Calculates the Levenshtein distance between two strings using a naive dynamic programming approach.
     *
     * This function computes the Levenshtein distance by constructing a dynamic programming matrix and iteratively filling it in.
     * It follows the standard top-to-bottom, left-to-right approach for filling in the matrix.
     *
     * @param string1 The first string.
     * @param string2 The second string.
     * @return The Levenshtein distance between the two input strings.
     *
     * Time complexity: O(nm),
     * Space complexity: O(nm),
     *
     * where n and m are lengths of `string1` and `string2`.
     *
     * Note that this implementation uses a straightforward dynamic programming approach without any space optimization.
     * It may consume more memory for larger input strings compared to the optimized version.
     */
    public static int naiveLevenshteinDistance(final String string1, final String string2) {
        int[][] distanceMatrix = IntStream.rangeClosed(0, string1.length()).mapToObj(i -> IntStream.rangeClosed(0, string2.length()).map(j -> (i == 0) ? j : (j == 0) ? i : 0).toArray()).toArray(int[][] ::new);

        IntStream.range(1, string1.length() + 1).forEach(i -> IntStream.range(1, string2.length() + 1).forEach(j -> {
            final int cost = (string1.charAt(i - 1) == string2.charAt(j - 1)) ? 0 : 1;
            distanceMatrix[i][j] = Math.min(distanceMatrix[i - 1][j - 1] + cost, Math.min(distanceMatrix[i][j - 1] + 1, distanceMatrix[i - 1][j] + 1));
        }));

        return distanceMatrix[string1.length()][string2.length()];
    }

    /**
     * Calculates the Levenshtein distance between two strings using an optimized dynamic programming approach.
     *
     * This edit distance is defined as 1 point per insertion, substitution, or deletion required to make the strings equal.
     *
     * @param string1 The first string.
     * @param string2 The second string.
     * @return The Levenshtein distance between the two input strings.
     *
     * Time complexity: O(nm),
     * Space complexity: O(n),
     *
     * where n and m are lengths of `string1` and `string2`.
     *
     * Note that this implementation utilizes an optimized dynamic programming approach, significantly reducing the space complexity from O(nm) to O(n), where n and m are the lengths of `string1` and `string2`.
     *
     * Additionally, it minimizes space usage by leveraging the shortest string horizontally and the longest string vertically in the computation matrix.
     */
    public static int optimizedLevenshteinDistance(final String string1, final String string2) {
        if (string1.isEmpty()) {
            return string2.length();
        }

        int[] previousDistance = IntStream.rangeClosed(0, string1.length()).toArray();

        for (int j = 1; j <= string2.length(); j++) {
            int prevSubstitutionCost = previousDistance[0];
            previousDistance[0] = j;

            for (int i = 1; i <= string1.length(); i++) {
                final int deletionCost = previousDistance[i] + 1;
                final int insertionCost = previousDistance[i - 1] + 1;
                final int substitutionCost = (string1.charAt(i - 1) == string2.charAt(j - 1)) ? prevSubstitutionCost : prevSubstitutionCost + 1;
                prevSubstitutionCost = previousDistance[i];
                previousDistance[i] = Math.min(deletionCost, Math.min(insertionCost, substitutionCost));
            }
        }

        return previousDistance[string1.length()];
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * Class for finding the length of the longest alternating subsequence in an array.
 *
 * <p>An alternating sequence is a sequence of numbers where the elements alternate
 * between increasing and decreasing. Specifically, a sequence is alternating if its elements
 * satisfy one of the following relations:
 *
 * <ul>
 *   <li>{@code x1 < x2 > x3 < x4 > x5 < ... < xn}</li>
 *   <li>{@code x1 > x2 < x3 > x4 < x5 > ... > xn}</li>
 * </ul>
 *
 * <p>This class provides a method to compute the length of the longest such subsequence
 * from a given array of integers.
 */
public final class LongestAlternatingSubsequence {
    private LongestAlternatingSubsequence() {
    }

    /**
     * Finds the length of the longest alternating subsequence in the given array.
     *
     * @param arr an array of integers where the longest alternating subsequence is to be found
     * @param n the length of the array {@code arr}
     * @return the length of the longest alternating subsequence
     *
     * <p>The method uses dynamic programming to solve the problem. It maintains a 2D array
     * {@code las} where:
     * <ul>
     *   <li>{@code las[i][0]} represents the length of the longest alternating subsequence
     *   ending at index {@code i} with the last element being greater than the previous element.</li>
     *   <li>{@code las[i][1]} represents the length of the longest alternating subsequence
     *   ending at index {@code i} with the last element being smaller than the previous element.</li>
     * </ul>
     *
     * <p>The method iterates through the array and updates the {@code las} array based on
     * whether the current element is greater or smaller than the previous elements.
     * The result is the maximum value found in the {@code las} array.
     */
    static int alternatingLength(int[] arr, int n) {
        int[][] las = new int[n][2]; // las = LongestAlternatingSubsequence

        // Initialize the dp array
        for (int i = 0; i < n; i++) {
            las[i][0] = 1;
            las[i][1] = 1;
        }

        int result = 1; // Initialize result

        // Compute values in a bottom-up manner
        for (int i = 1; i < n; i++) {
            for (int j = 0; j < i; j++) {
                // If arr[i] is greater than arr[j], update las[i][0]
                if (arr[j] < arr[i] && las[i][0] < las[j][1] + 1) {
                    las[i][0] = las[j][1] + 1;
                }

                // If arr[i] is smaller than arr[j], update las[i][1]
                if (arr[j] > arr[i] && las[i][1] < las[j][0] + 1) {
                    las[i][1] = las[j][0] + 1;
                }
            }

            // Pick the maximum of both values at index i
            result = Math.max(result, Math.max(las[i][0], las[i][1]));
        }

        return result;
    }
}

package com.thealgorithms.dynamicprogramming;

import java.util.HashMap;

@SuppressWarnings({"rawtypes", "unchecked"})
final class LongestArithmeticSubsequence {
    private LongestArithmeticSubsequence() {
    }

    /**
     * Returns the length of the longest arithmetic subsequence in the given array.
     *
     * A sequence seq is arithmetic if seq[i + 1] - seq[i] are all the same value
     * (for 0 <= i < seq.length - 1).
     *
     * @param nums the input array of integers
     * @return the length of the longest arithmetic subsequence
     */
    public static int getLongestArithmeticSubsequenceLength(int[] nums) {
        if (nums == null) {
            throw new IllegalArgumentException("Input array cannot be null");
        }

        if (nums.length <= 1) {
            return nums.length;
        }

        HashMap<Integer, Integer>[] dp = new HashMap[nums.length];
        int maxLength = 2;

        // fill the dp array
        for (int i = 0; i < nums.length; i++) {
            dp[i] = new HashMap<>();
            for (int j = 0; j < i; j++) {
                final int diff = nums[i] - nums[j];
                dp[i].put(diff, dp[j].getOrDefault(diff, 1) + 1);
                maxLength = Math.max(maxLength, dp[i].get(diff));
            }
        }

        return maxLength;
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * This class implements the Longest Common Subsequence (LCS) problem.
 * The LCS of two sequences is the longest sequence that appears in both
 * sequences
 * in the same order, but not necessarily consecutively.
 *
 * This implementation uses dynamic programming to find the LCS of two strings.
 */
final class LongestCommonSubsequence {

    private LongestCommonSubsequence() {
    }

    /**
     * Returns the Longest Common Subsequence (LCS) of two given strings.
     *
     * @param str1 The first string.
     * @param str2 The second string.
     * @return The LCS of the two strings, or null if one of the strings is null.
     */
    public static String getLCS(String str1, String str2) {
        // If either string is null, return null as LCS can't be computed.
        if (str1 == null || str2 == null) {
            return null;
        }
        // If either string is empty, return an empty string as LCS.
        if (str1.length() == 0 || str2.length() == 0) {
            return "";
        }

        // Convert the strings into arrays of characters
        String[] arr1 = str1.split("");
        String[] arr2 = str2.split("");

        // lcsMatrix[i][j] = LCS(first i characters of str1, first j characters of str2)
        int[][] lcsMatrix = new int[arr1.length + 1][arr2.length + 1];

        // Base Case: Fill the LCS matrix 0th row & 0th column with 0s
        // as LCS of any string with an empty string is 0.
        for (int i = 0; i < arr1.length + 1; i++) {
            lcsMatrix[i][0] = 0;
        }
        for (int j = 1; j < arr2.length + 1; j++) {
            lcsMatrix[0][j] = 0;
        }

        // Build the LCS matrix by comparing characters of str1 & str2
        for (int i = 1; i < arr1.length + 1; i++) {
            for (int j = 1; j < arr2.length + 1; j++) {
                // If characters match, the LCS increases by 1
                if (arr1[i - 1].equals(arr2[j - 1])) {
                    lcsMatrix[i][j] = lcsMatrix[i - 1][j - 1] + 1;
                } else {
                    // Otherwise, take the maximum of the left or above values
                    lcsMatrix[i][j] = Math.max(lcsMatrix[i - 1][j], lcsMatrix[i][j - 1]);
                }
            }
        }

        // Call helper function to reconstruct the LCS from the matrix
        return lcsString(str1, str2, lcsMatrix);
    }

    /**
     * Reconstructs the LCS string from the LCS matrix.
     *
     * @param str1      The first string.
     * @param str2      The second string.
     * @param lcsMatrix The matrix storing the lengths of LCSs
     *                  of substrings of str1 and str2.
     * @return The LCS string.
     */
    public static String lcsString(String str1, String str2, int[][] lcsMatrix) {
        StringBuilder lcs = new StringBuilder(); // Hold the LCS characters.
        int i = str1.length(); // Start from the end of str1.
        int j = str2.length(); // Start from the end of str2.

        // Trace back through the LCS matrix to reconstruct the LCS
        while (i > 0 && j > 0) {
            // If characters match, add to the LCS and move diagonally in the matrix
            if (str1.charAt(i - 1) == str2.charAt(j - 1)) {
                lcs.append(str1.charAt(i - 1));
                i--;
                j--;
            } else if (lcsMatrix[i - 1][j] > lcsMatrix[i][j - 1]) {
                // If the value above is larger, move up
                i--;
            } else {
                // If the value to the left is larger, move left
                j--;
            }
        }

        return lcs.reverse().toString(); // LCS built in reverse, so reverse it back
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * @author Afrizal Fikri (https://github.com/icalF)
 */
public final class LongestIncreasingSubsequence {
    private LongestIncreasingSubsequence() {
    }

    private static int upperBound(int[] ar, int l, int r, int key) {
        while (l < r - 1) {
            int m = (l + r) >>> 1;
            if (ar[m] >= key) {
                r = m;
            } else {
                l = m;
            }
        }

        return r;
    }

    public static int lis(int[] array) {
        int len = array.length;
        if (len == 0) {
            return 0;
        }

        int[] tail = new int[len];

        // always points empty slot in tail
        int length = 1;

        tail[0] = array[0];
        for (int i = 1; i < len; i++) {
            // new smallest value
            if (array[i] < tail[0]) {
                tail[0] = array[i];
            } // array[i] extends largest subsequence
            else if (array[i] > tail[length - 1]) {
                tail[length++] = array[i];
            } // array[i] will become end candidate of an existing subsequence or
            // Throw away larger elements in all LIS, to make room for upcoming grater elements than
            // array[i]
            // (and also, array[i] would have already appeared in one of LIS, identify the location
            // and replace it)
            else {
                tail[upperBound(tail, -1, length - 1, array[i])] = array[i];
            }
        }

        return length;
    }

    /**
     * @author Alon Firestein (https://github.com/alonfirestein)
     */
    // A function for finding the length of the LIS algorithm in O(nlogn) complexity.
    public static int findLISLen(int[] a) {
        final int size = a.length;
        if (size == 0) {
            return 0;
        }
        int[] arr = new int[size];
        arr[0] = a[0];
        int lis = 1;
        for (int i = 1; i < size; i++) {
            int index = binarySearchBetween(arr, lis - 1, a[i]);
            arr[index] = a[i];
            if (index == lis) {
                lis++;
            }
        }
        return lis;
    }

    // O(logn)

    private static int binarySearchBetween(int[] t, int end, int key) {
        int left = 0;
        int right = end;
        if (key < t[0]) {
            return 0;
        }
        if (key > t[end]) {
            return end + 1;
        }
        while (left < right - 1) {
            final int middle = (left + right) >>> 1;
            if (t[middle] < key) {
                left = middle;
            } else {
                right = middle;
            }
        }
        return right;
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * Implementation of the Longest Increasing Subsequence (LIS) problem using
 * an O(n log n) dynamic programming solution enhanced with binary search.
 *
 * @author Vusal Huseynov (https://github.com/huseynovvusal)
 */
public final class LongestIncreasingSubsequenceNLogN {
    private LongestIncreasingSubsequenceNLogN() {
    }

    /**
     * Finds the index of the smallest element in the array that is greater than
     * or equal to the target using binary search. The search is restricted to
     * the first `size` elements of the array.
     *
     * @param arr    The array to search in (assumed to be sorted up to `size`).
     * @param size   The number of valid elements in the array.
     * @param target The target value to find the lower bound for.
     * @return The index of the lower bound.
     */
    private static int lowerBound(int[] arr, int target, int size) {
        int l = 0;
        int r = size;

        while (l < r) {
            int mid = l + (r - l) / 2;

            if (target > arr[mid]) {
                // Move right if target is greater than mid element
                l = mid + 1;
            } else {
                // Move left if target is less than or equal to mid element
                r = mid;
            }
        }

        // Return the index where the target can be inserted
        return l;
    }

    /**
     * Calculates the length of the Longest Increasing Subsequence (LIS) in the given array.
     *
     * @param arr The input array of integers.
     * @return The length of the LIS.
     */
    public static int lengthOfLIS(int[] arr) {
        if (arr == null || arr.length == 0) {
            return 0; // Return 0 for empty or null arrays
        }

        // tails[i] - the smallest end element of an increasing subsequence of length i+1
        int[] tails = new int[arr.length];
        // size - the length of the longest increasing subsequence found so far
        int size = 0;

        for (int x : arr) {
            // Find the position to replace or extend the subsequence
            int index = lowerBound(tails, x, size);

            // Update the tails array with the current element
            tails[index] = x;

            // If the element extends the subsequence, increase the size
            if (index == size) {
                size++;
            }
        }

        // Return the length of the LIS
        return size;
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * Longest Palindromic Subsequence algorithm.
 * A palindromic subsequence is a subsequence that reads the same forwards and backwards.
 * This implementation finds the longest such subsequence by computing the LCS of the
 * original string and its reverse.
 *
 * @see <a href="https://en.wikipedia.org/wiki/Longest_palindromic_subsequence">Wikipedia</a>
 */
public final class LongestPalindromicSubsequence {
    private LongestPalindromicSubsequence() {
    }

    /**
     * Returns the longest palindromic subsequence of the given string.
     *
     * @param original the input string
     * @return the longest palindromic subsequence
     * @throws IllegalArgumentException if the input string is null
     */
    public static String lps(String original) {
        if (original == null) {
            throw new IllegalArgumentException("Input string must not be null");
        }
        String reverse = new StringBuilder(original).reverse().toString();
        return recursiveLPS(original, reverse);
    }

    private static String recursiveLPS(String original, String reverse) {
        if (original.isEmpty() || reverse.isEmpty()) {
            return "";
        }
        if (original.charAt(original.length() - 1) == reverse.charAt(reverse.length() - 1)) {
            String bestSubResult = recursiveLPS(original.substring(0, original.length() - 1), reverse.substring(0, reverse.length() - 1));
            return reverse.charAt(reverse.length() - 1) + bestSubResult;
        }
        String sub1 = recursiveLPS(original, reverse.substring(0, reverse.length() - 1));
        String sub2 = recursiveLPS(original.substring(0, original.length() - 1), reverse);
        return sub1.length() >= sub2.length() ? sub1 : sub2;
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * Class for finding the longest palindromic substring within a given string.
 * <p>
 * A palindromic substring is a sequence of characters that reads the same backward as forward.
 * This class uses a dynamic programming approach to efficiently find the longest palindromic substring.
 *
 */
public final class LongestPalindromicSubstring {
    private LongestPalindromicSubstring() {
    }

    public static String lps(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }
        boolean[][] arr = new boolean[input.length()][input.length()];
        int start = 0;
        int end = 0;
        for (int g = 0; g < input.length(); g++) {
            for (int i = 0, j = g; j < input.length(); i++, j++) {
                if (g == 0) {
                    arr[i][j] = true;
                } else if (g == 1) {
                    arr[i][j] = input.charAt(i) == input.charAt(j);
                } else {
                    arr[i][j] = input.charAt(i) == input.charAt(j) && arr[i + 1][j - 1];
                }

                if (arr[i][j]) {
                    start = i;
                    end = j;
                }
            }
        }
        return input.substring(start, end + 1);
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * Given a string containing just the characters '(' and ')', find the length of
 * the longest valid (well-formed) parentheses substring.
 *
 * @author Libin Yang (https://github.com/yanglbme)
 * @since 2018/10/5
 */
public final class LongestValidParentheses {
    private LongestValidParentheses() {
    }

    public static int getLongestValidParentheses(String s) {
        if (s == null || s.length() < 2) {
            return 0;
        }
        char[] chars = s.toCharArray();
        int n = chars.length;
        int[] res = new int[n];
        res[0] = 0;
        res[1] = chars[1] == ')' && chars[0] == '(' ? 2 : 0;

        int max = res[1];

        for (int i = 2; i < n; ++i) {
            if (chars[i] == ')') {
                if (chars[i - 1] == '(') {
                    res[i] = res[i - 2] + 2;
                } else {
                    int index = i - res[i - 1] - 1;
                    if (index >= 0 && chars[index] == '(') {
                        // ()(())
                        res[i] = res[i - 1] + 2 + (index - 1 >= 0 ? res[index - 1] : 0);
                    }
                }
            }
            max = Math.max(max, res[i]);
        }

        return max;
    }
}

package com.thealgorithms.dynamicprogramming;

import java.util.ArrayList;
import java.util.Arrays;

/**
 * The MatrixChainMultiplication class provides functionality to compute the
 * optimal way to multiply a sequence of matrices. The optimal multiplication
 * order is determined using dynamic programming, which minimizes the total
 * number of scalar multiplications required.
 */
public final class MatrixChainMultiplication {
    private MatrixChainMultiplication() {
    }

    // Matrices to store minimum multiplication costs and split points
    private static int[][] m;
    private static int[][] s;
    private static int[] p;

    /**
     * Calculates the optimal order for multiplying a given list of matrices.
     *
     * @param matrices an ArrayList of Matrix objects representing the matrices
     *                 to be multiplied.
     * @return a Result object containing the matrices of minimum costs and
     *         optimal splits.
     */
    public static Result calculateMatrixChainOrder(ArrayList<Matrix> matrices) {
        int size = matrices.size();
        m = new int[size + 1][size + 1];
        s = new int[size + 1][size + 1];
        p = new int[size + 1];

        for (int i = 0; i < size + 1; i++) {
            Arrays.fill(m[i], -1);
            Arrays.fill(s[i], -1);
        }

        for (int i = 0; i < p.length; i++) {
            p[i] = i == 0 ? matrices.get(i).col() : matrices.get(i - 1).row();
        }

        matrixChainOrder(size);
        return new Result(m, s);
    }

    /**
     * A helper method that computes the minimum cost of multiplying
     * the matrices using dynamic programming.
     *
     * @param size the number of matrices in the multiplication sequence.
     */
    private static void matrixChainOrder(int size) {
        for (int i = 1; i < size + 1; i++) {
            m[i][i] = 0;
        }

        for (int l = 2; l < size + 1; l++) {
            for (int i = 1; i < size - l + 2; i++) {
                int j = i + l - 1;
                m[i][j] = Integer.MAX_VALUE;

                for (int k = i; k < j; k++) {
                    int q = m[i][k] + m[k + 1][j] + p[i - 1] * p[k] * p[j];
                    if (q < m[i][j]) {
                        m[i][j] = q;
                        s[i][j] = k;
                    }
                }
            }
        }
    }

    /**
     * The Result class holds the results of the matrix chain multiplication
     * calculation, including the matrix of minimum costs and split points.
     */
    public static class Result {
        private final int[][] m;
        private final int[][] s;

        /**
         * Constructs a Result object with the specified matrices of minimum
         * costs and split points.
         *
         * @param m the matrix of minimum multiplication costs.
         * @param s the matrix of optimal split points.
         */
        public Result(int[][] m, int[][] s) {
            this.m = m;
            this.s = s;
        }

        /**
         * Returns the matrix of minimum multiplication costs.
         *
         * @return the matrix of minimum multiplication costs.
         */
        public int[][] getM() {
            return m;
        }

        /**
         * Returns the matrix of optimal split points.
         *
         * @return the matrix of optimal split points.
         */
        public int[][] getS() {
            return s;
        }
    }

    /**
     * The Matrix class represents a matrix with its dimensions and count.
     */
    public static class Matrix {
        private final int count;
        private final int col;
        private final int row;

        /**
         * Constructs a Matrix object with the specified count, number of columns,
         * and number of rows.
         *
         * @param count the identifier for the matrix.
         * @param col   the number of columns in the matrix.
         * @param row   the number of rows in the matrix.
         */
        public Matrix(int count, int col, int row) {
            this.count = count;
            this.col = col;
            this.row = row;
        }

        /**
         * Returns the identifier of the matrix.
         *
         * @return the identifier of the matrix.
         */
        public int count() {
            return count;
        }

        /**
         * Returns the number of columns in the matrix.
         *
         * @return the number of columns in the matrix.
         */
        public int col() {
            return col;
        }

        /**
         * Returns the number of rows in the matrix.
         *
         * @return the number of rows in the matrix.
         */
        public int row() {
            return row;
        }
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * The MatrixChainRecursiveTopDownMemoisation class implements the matrix-chain
 * multiplication problem using a top-down recursive approach with memoization.
 *
 * <p>Given a chain of matrices A1, A2, ..., An, where matrix Ai has dimensions
 * pi-1 × pi, this algorithm finds the optimal way to fully parenthesize the
 * product A1A2...An in a way that minimizes the total number of scalar
 * multiplications required.</p>
 *
 * <p>This implementation uses a memoization technique to store the results of
 * subproblems, which significantly reduces the number of recursive calls and
 * improves performance compared to a naive recursive approach.</p>
 */
public final class MatrixChainRecursiveTopDownMemoisation {
    private MatrixChainRecursiveTopDownMemoisation() {
    }

    /**
     * Calculates the minimum number of scalar multiplications needed to multiply
     * a chain of matrices.
     *
     * @param p an array of integers representing the dimensions of the matrices.
     *          The length of the array is n + 1, where n is the number of matrices.
     * @return the minimum number of multiplications required to multiply the chain
     *         of matrices.
     */
    static int memoizedMatrixChain(int[] p) {
        int n = p.length;
        int[][] m = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                m[i][j] = Integer.MAX_VALUE;
            }
        }
        return lookupChain(m, p, 1, n - 1);
    }

    /**
     * A recursive helper method to lookup the minimum number of multiplications
     * for multiplying matrices from index i to index j.
     *
     * @param m the memoization table storing the results of subproblems.
     * @param p an array of integers representing the dimensions of the matrices.
     * @param i the starting index of the matrix chain.
     * @param j the ending index of the matrix chain.
     * @return the minimum number of multiplications needed to multiply matrices
     *         from i to j.
     */
    static int lookupChain(int[][] m, int[] p, int i, int j) {
        if (i == j) {
            m[i][j] = 0;
            return m[i][j];
        }
        if (m[i][j] < Integer.MAX_VALUE) {
            return m[i][j];
        } else {
            for (int k = i; k < j; k++) {
                int q = lookupChain(m, p, i, k) + lookupChain(m, p, k + 1, j) + (p[i - 1] * p[k] * p[j]);
                if (q < m[i][j]) {
                    m[i][j] = q;
                }
            }
        }
        return m[i][j];
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * The MaximumProductSubarray class implements the algorithm to find the
 * maximum product of a contiguous subarray within a given array of integers.
 *
 * <p>Given an array of integers (which may contain positive numbers, negative
 * numbers, and zeros), this algorithm finds the contiguous subarray that has
 * the largest product. The algorithm handles negative numbers efficiently by
 * tracking both maximum and minimum products, since a negative number can turn
 * a minimum product into a maximum product.</p>
 *
 * <p>This implementation uses a dynamic programming approach that runs in O(n)
 * time complexity and O(1) space complexity, making it highly efficient for
 * large arrays.</p>
 */
public final class MaximumProductSubarray {

    private MaximumProductSubarray() {
        // Prevent instantiation
    }

    /**
     * Finds the maximum product of any contiguous subarray in the given array.
     *
     * @param nums an array of integers which may contain positive, negative,
     *             and zero values.
     * @return the maximum product of a contiguous subarray. Returns 0 if the
     *         array is null or empty.
     */
    public static int maxProduct(int[] nums) {
        if (nums == null || nums.length == 0) {
            return 0;
        }

        long maxProduct = nums[0];
        long currentMax = nums[0];
        long currentMin = nums[0];

        for (int i = 1; i < nums.length; i++) {
            // Swap currentMax and currentMin if current number is negative
            if (nums[i] < 0) {
                long temp = currentMax;
                currentMax = currentMin;
                currentMin = temp;
            }

            // Update currentMax and currentMin
            currentMax = Math.max(nums[i], currentMax * nums[i]);
            currentMin = Math.min(nums[i], currentMin * nums[i]);

            // Update global max product
            maxProduct = Math.max(maxProduct, currentMax);
        }

        return (int) maxProduct;
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * Class to find the maximum sum of non-adjacent elements in an array. This
 * class contains two approaches: one with O(n) space complexity and another
 * with O(1) space optimization. For more information, refer to
 * https://takeuforward.org/data-structure/maximum-sum-of-non-adjacent-elements-dp-5/
 */
final class MaximumSumOfNonAdjacentElements {

    private MaximumSumOfNonAdjacentElements() {
    }

    /**
     * Approach 1: Uses a dynamic programming array to store the maximum sum at
     * each index. Time Complexity: O(n) - where n is the length of the input
     * array. Space Complexity: O(n) - due to the additional dp array.
     * @param arr The input array of integers.
     * @return The maximum sum of non-adjacent elements.
     */
    public static int getMaxSumApproach1(int[] arr) {
        if (arr.length == 0) {
            return 0; // Check for empty array
        }

        int n = arr.length;
        int[] dp = new int[n];

        // Base case: Maximum sum if only one element is present.
        dp[0] = arr[0];

        for (int ind = 1; ind < n; ind++) {

            // Case 1: Do not take the current element, carry forward the previous max
            // sum.
            int notTake = dp[ind - 1];

            // Case 2: Take the current element, add it to the max sum up to two
            // indices before.
            int take = arr[ind];
            if (ind > 1) {
                take += dp[ind - 2];
            }

            // Store the maximum of both choices in the dp array.
            dp[ind] = Math.max(take, notTake);
        }

        return dp[n - 1];
    }

    /**
     * Approach 2: Optimized space complexity approach using two variables instead
     * of an array. Time Complexity: O(n) - where n is the length of the input
     * array. Space Complexity: O(1) - as it only uses constant space for two
     * variables.
     * @param arr The input array of integers.
     * @return The maximum sum of non-adjacent elements.
     */
    public static int getMaxSumApproach2(int[] arr) {
        if (arr.length == 0) {
            return 0; // Check for empty array
        }

        int n = arr.length;

        // Two variables to keep track of previous two results:
        // prev1 = max sum up to the last element (n-1)
        // prev2 = max sum up to the element before last (n-2)

        int prev1 = arr[0]; // Base case: Maximum sum for the first element.
        int prev2 = 0;

        for (int ind = 1; ind < n; ind++) {
            // Case 1: Do not take the current element, keep the last max sum.
            int notTake = prev1;

            // Case 2: Take the current element and add it to the result from two
            // steps back.
            int take = arr[ind];
            if (ind > 1) {
                take += prev2;
            }

            // Calculate the current maximum sum and update previous values.
            int current = Math.max(take, notTake);

            // Shift prev1 and prev2 for the next iteration.
            prev2 = prev1;
            prev1 = current;
        }

        return prev1;
    }
}

package com.thealgorithms.dynamicprogramming;

/*
Given the following grid with length m and width n:
\---\---\---\ (n)
\ 1 \ 3 \ 1 \
\---\---\---\
\ 1 \ 5 \ 1 \
\---\---\---\
\ 4 \ 2 \ 1 \
\---\---\---\
(m)
Find the path where its sum is the smallest.

The Time Complexity of your algorithm should be smaller than or equal to O(mn).
The Space Complexity of your algorithm should be smaller than or equal to O(n).
You can only move from the top left corner to the down right corner.
You can only move one step down or right.

EXAMPLE:
INPUT: grid = [[1,3,1],[1,5,1],[4,2,1]]
OUTPUT: 7
EXPLANATIONS: 1 + 3 + 1 + 1 + 1 = 7

For more information see https://www.geeksforgeeks.org/maximum-path-sum-matrix/
 */
public final class MinimumPathSum {

    private MinimumPathSum() {
    }

    public static int minimumPathSum(final int[][] grid) {
        int numRows = grid.length;
        int numCols = grid[0].length;

        if (numCols == 0) {
            return 0;
        }

        int[] dp = new int[numCols];

        // Initialize the first element of the dp array
        dp[0] = grid[0][0];

        // Calculate the minimum path sums for the first row
        for (int col = 1; col < numCols; col++) {
            dp[col] = dp[col - 1] + grid[0][col];
        }

        // Calculate the minimum path sums for the remaining rows
        for (int row = 1; row < numRows; row++) {
            // Update the minimum path sum for the first column
            dp[0] += grid[row][0];

            for (int col = 1; col < numCols; col++) {
                // Choose the minimum path sum from the left or above
                dp[col] = Math.min(dp[col - 1], dp[col]) + grid[row][col];
            }
        }

        // Return the minimum path sum for the last cell in the grid
        return dp[numCols - 1];
    }
}

package com.thealgorithms.dynamicprogramming;

import java.util.Arrays;

/*
Given an array of non-negative integers , partition the array in two subset that
difference in sum of elements for both subset minimum.
Return the minimum difference in sum of these subsets you can achieve.

Input:  array[] = {1, 6, 11, 4}
Output: 0
Explanation:
Subset1 = {1, 4, 6}, sum of Subset1 = 11
Subset2 = {11}, sum of Subset2 = 11

Input:  array[] = {36, 7, 46, 40}
Output: 23
Explanation:
Subset1 = {7, 46} ;  sum of Subset1 = 53
Subset2 = {36, 40} ; sum of Subset2  = 76
 */
public final class MinimumSumPartition {
    private MinimumSumPartition() {
    }

    private static void throwIfInvalidInput(final int[] array) {
        if (Arrays.stream(array).anyMatch(a -> a < 0)) {
            throw new IllegalArgumentException("Input array should not contain negative number(s).");
        }
    }

    public static int minimumSumPartition(final int[] array) {
        throwIfInvalidInput(array);
        int sum = Arrays.stream(array).sum();
        boolean[] dp = new boolean[sum / 2 + 1];
        dp[0] = true; // Base case , don't select any element from array

        // Find the closest sum of subset array that we can achieve which is closest to half of sum of full array
        int closestPartitionSum = 0;

        for (int i = 0; i < array.length; i++) {
            for (int j = sum / 2; j > 0; j--) {
                if (array[i] <= j) {
                    dp[j] = dp[j] || dp[j - array[i]];
                }
                if (dp[j]) {
                    closestPartitionSum = Math.max(closestPartitionSum, j);
                }
            }
        }
        /*
        Difference in sum = Big partition sum  - Small partition sum
                          = ( Total sum - Small partition sum) - Small partition sum
         */
        return sum - (2 * closestPartitionSum);
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * The Needleman–Wunsch algorithm performs global sequence alignment between two strings.
 * It computes the optimal alignment score using dynamic programming,
 * given a scoring scheme for matches, mismatches, and gaps.
 *
 * Time Complexity: O(n * m)
 * Space Complexity: O(n * m)
 */
public final class NeedlemanWunsch {

    private NeedlemanWunsch() {
        // Utility Class
    }

    /**
     * Computes the Needleman–Wunsch global alignment score between two strings.
     *
     * @param s1 the first string
     * @param s2 the second string
     * @param matchScore score for a character match
     * @param mismatchPenalty penalty for a mismatch (should be negative)
     * @param gapPenalty penalty for inserting a gap (should be negative)
     * @return the optimal alignment score
     */
    public static int align(String s1, String s2, int matchScore, int mismatchPenalty, int gapPenalty) {
        if (s1 == null || s2 == null) {
            throw new IllegalArgumentException("Input strings must not be null.");
        }

        int n = s1.length();
        int m = s2.length();

        int[][] dp = new int[n + 1][m + 1];

        // Initialize gap penalties for first row and column
        for (int i = 0; i <= n; i++) {
            dp[i][0] = i * gapPenalty;
        }
        for (int j = 0; j <= m; j++) {
            dp[0][j] = j * gapPenalty;
        }

        // Fill the DP matrix
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                int matchOrMismatch = (s1.charAt(i - 1) == s2.charAt(j - 1)) ? matchScore : mismatchPenalty;

                dp[i][j] = Math.max(Math.max(dp[i - 1][j - 1] + matchOrMismatch, // match/mismatch
                                        dp[i - 1][j] + gapPenalty // deletion (gap in s2)
                                        ),
                    dp[i][j - 1] + gapPenalty // insertion (gap in s1)
                );
            }
        }

        return dp[n][m];
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * The NewManShanksPrime class provides a method to determine whether the nth
 * New Man Shanks prime matches an expected answer.
 *
 * <p>This is based on the New Man Shanks prime sequence defined by the recurrence
 * relation:</p>
 *
 * <pre>
 * a(n) = 2 * a(n-1) + a(n-2) for n >= 2
 * a(0) = 1
 * a(1) = 1
 * </pre>
 *
 * <p>For more information on New Man Shanks primes, please refer to the
 * <a href="https://en.wikipedia.org/wiki/Newman%E2%80%93Shanks%E2%80%93Williams_prime">
 * Wikipedia article</a>.</p>
 *
 * <p>Note: The class is designed to be non-instantiable.</p>
 *
 * @author <a href="https://github.com/siddhant2002">Siddhant Swarup Mallick</a>
 */
public final class NewManShanksPrime {
    private NewManShanksPrime() {
    }

    /**
     * Calculates the nth New Man Shanks prime and checks if it equals the
     * expected answer.
     *
     * @param n the index of the New Man Shanks prime to calculate (0-based).
     * @param expectedAnswer the expected value of the nth New Man Shanks prime.
     * @return true if the calculated nth New Man Shanks prime matches the
     *         expected answer; false otherwise.
     */
    public static boolean nthManShanksPrime(int n, int expectedAnswer) {
        int[] a = new int[n + 1];
        a[0] = 1;
        a[1] = 1;

        for (int i = 2; i <= n; i++) {
            a[i] = 2 * a[i - 1] + a[i - 2];
        }

        return a[n] == expectedAnswer;
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * This class refers to the Optimal Job Scheduling problem with the following constrains:
 *  - precedence relation between the processes
 *  - machine pair dependent transportation delays
 *
 * https://en.wikipedia.org/wiki/Optimal_job_scheduling
 *
 * @author georgioct@csd.auth.gr
 */
public class OptimalJobScheduling {

    private final int numberProcesses;
    private final int numberMachines;
    private final int[][] run;
    private final int[][] transfer;
    private final int[][] cost;

    /**
     * Constructor of the class.
     * @param numberProcesses ,refers to the number of precedent processes(N)
     * @param numberMachines ,refers to the number of different machines in our disposal(M)
     * @param run , N*M matrix refers to the cost of running each process to each machine
     * @param transfer ,M*M symmetric matrix refers to the transportation delay for each pair of
     *     machines
     */
    public OptimalJobScheduling(int numberProcesses, int numberMachines, int[][] run, int[][] transfer) {
        this.numberProcesses = numberProcesses;
        this.numberMachines = numberMachines;
        this.run = run;
        this.transfer = transfer;
        this.cost = new int[numberProcesses][numberMachines];
    }

    /**
     * Function which computes the cost of process scheduling to a number of VMs.
     */
    public void execute() {
        this.calculateCost();
        this.showResults();
    }

    /**
     * Function which computes the cost of running each Process to each and every Machine
     */
    private void calculateCost() {

        for (int i = 0; i < numberProcesses; i++) { // for each Process

            for (int j = 0; j < numberMachines; j++) { // for each Machine

                cost[i][j] = runningCost(i, j);
            }
        }
    }

    /**
     * Function which returns the minimum cost of running a certain Process to a certain Machine.In
     * order for the Machine to execute the Process ,he requires the output of the previously
     * executed Process, which may have been executed to the same Machine or some other.If the
     * previous Process has been executed to another Machine,we have to transfer her result, which
     * means extra cost for transferring the data from one Machine to another(if the previous
     * Process has been executed to the same Machine, there is no transport cost).
     *
     * @param process ,refers to the Process
     * @param machine ,refers to the Machine
     * @return the minimum cost of executing the process to the certain machine.
     */
    private int runningCost(int process, int machine) {

        if (process == 0) { // refers to the first process,which does not require for a previous one
            // to have been executed
            return run[process][machine];
        } else {

            int[] runningCosts = new int[numberMachines]; // stores the costs of executing our Process depending on
            // the Machine the previous one was executed

            for (int k = 0; k < numberMachines; k++) { // computes the cost of executing the previous
                // process to each and every Machine
                runningCosts[k] = cost[process - 1][k] + transfer[k][machine] + run[process][machine]; // transferring the result to our Machine and executing
                // the Process to our Machine
            }
            return findMin(runningCosts); // returns the minimum running cost
        }
    }

    /**
     * Function used in order to return the minimum Cost.
     * @param costArr ,an Array of size M which refers to the costs of executing a Process to each
     *     Machine
     * @return the minimum cost
     */
    private int findMin(int[] costArr) {

        int min = 0;

        for (int i = 1; i < costArr.length; i++) {

            if (costArr[i] < costArr[min]) {
                min = i;
            }
        }
        return costArr[min];
    }

    /**
     * Method used in order to present the overall costs.
     */
    private void showResults() {

        for (int i = 0; i < numberProcesses; i++) {

            for (int j = 0; j < numberMachines; j++) {
                System.out.print(cost[i][j]);
                System.out.print(" ");
            }

            System.out.println();
        }
        System.out.println();
    }

    /**
     * Getter for the running Cost of i process on j machine.
     */
    public int getCost(int process, int machine) {
        return cost[process][machine];
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * Provides functionality to solve the Palindrome Partitioning II problem, which involves finding
 * the minimum number of partitions needed to divide a given string into palindromic substrings.
 *
 * <p>
 * The problem is solved using dynamic programming. The approach involves checking all possible
 * substrings and determining whether they are palindromes. The minimum number of cuts required
 * for palindrome partitioning is computed in a bottom-up manner.
 * </p>
 *
 * <p>
 * Example:
 * <ul>
 *     <li>Input: "nitik" => Output: 2 (Partitioning: "n | iti | k")</li>
 *     <li>Input: "ababbbabbababa" => Output: 3 (Partitioning: "aba | b | bbabb | ababa")</li>
 * </ul>
 * </p>
 *
 * @see <a href="https://leetcode.com/problems/palindrome-partitioning-ii/">Palindrome Partitioning II</a>
 * @see <a href="https://www.geeksforgeeks.org/palindrome-partitioning-dp-17/">Palindrome Partitioning (GeeksforGeeks)</a>
 */
public final class PalindromicPartitioning {
    private PalindromicPartitioning() {
    }

    public static int minimalPartitions(String word) {
        int len = word.length();
        /* We Make two arrays to create a bottom-up solution.
           minCuts[i] = Minimum number of cuts needed for palindrome partitioning of substring
           word[0..i] isPalindrome[i][j] = true if substring str[i..j] is palindrome Base Condition:
           C[i] is 0 if P[0][i]= true
         */
        int[] minCuts = new int[len];
        boolean[][] isPalindrome = new boolean[len][len];

        int i;
        int j;
        int subLen; // different looping variables

        // Every substring of length 1 is a palindrome
        for (i = 0; i < len; i++) {
            isPalindrome[i][i] = true;
        }

        /* subLen is substring length. Build the solution in bottom up manner by considering all
         * substrings of length starting from 2 to n. */
        for (subLen = 2; subLen <= len; subLen++) {
            // For substring of length subLen, set different possible starting indexes
            for (i = 0; i < len - subLen + 1; i++) {
                j = i + subLen - 1; // Ending index
                // If subLen is 2, then we just need to
                // compare two characters. Else need to
                // check two corner characters and value
                // of P[i+1][j-1]
                if (subLen == 2) {
                    isPalindrome[i][j] = (word.charAt(i) == word.charAt(j));
                } else {
                    isPalindrome[i][j] = (word.charAt(i) == word.charAt(j)) && isPalindrome[i + 1][j - 1];
                }
            }
        }

        // We find the minimum for each index
        for (i = 0; i < len; i++) {
            if (isPalindrome[0][i]) {
                minCuts[i] = 0;
            } else {
                minCuts[i] = Integer.MAX_VALUE;
                for (j = 0; j < i; j++) {
                    if (isPalindrome[j + 1][i] && 1 + minCuts[j] < minCuts[i]) {
                        minCuts[i] = 1 + minCuts[j];
                    }
                }
            }
        }

        // Return the min cut value for complete
        // string. i.e., str[0..n-1]
        return minCuts[len - 1];
    }
}

