/**
 * A class to check if a given number is a palindrome.
 * A palindromic number is a number that remains the same when its digits are reversed.
 *
 * @see com.thealgorithms.strings.Palindrome
 * @see com.thealgorithms.stacks.PalindromeWithStack
 * @see com.thealgorithms.bitmanipulation.BinaryPalindromeCheck
 * @see com.thealgorithms.maths.LowestBasePalindrome
 * @see com.thealgorithms.datastructures.lists.PalindromeSinglyLinkedList
 * @see com.thealgorithms.maths.PalindromePrime
 */
public final class PalindromeNumber {
    private PalindromeNumber() {
    }
    /**
     * Check if {@code n} is palindrome number or not
     *
     * @param number the number
     * @return {@code true} if {@code n} is palindrome number, otherwise
     * {@code false}
     */
    public static boolean isPalindrome(int number) {
        if (number < 0) {
            throw new IllegalArgumentException("Input parameter must not be negative!");
        }
        int numberCopy = number;
        int reverseNumber = 0;
        while (numberCopy != 0) {
            int remainder = numberCopy % 10;
            reverseNumber = reverseNumber * 10 + remainder;
            numberCopy /= 10;
        }
        return number == reverseNumber;
    }
}

package com.thealgorithms.maths;

import java.util.ArrayList;
import java.util.List;

/**
 * A class to check and generate palindromic prime numbers.
 * A palindromic prime is a prime number that is also a palindromic number.
 *
 * @see com.thealgorithms.strings.Palindrome
 * @see com.thealgorithms.stacks.PalindromeWithStack
 * @see com.thealgorithms.bitmanipulation.BinaryPalindromeCheck
 * @see com.thealgorithms.maths.LowestBasePalindrome
 * @see com.thealgorithms.datastructures.lists.PalindromeSinglyLinkedList
 * @see com.thealgorithms.maths.PalindromeNumber
 */
public final class PalindromePrime {
    private PalindromePrime() {
    }

    public static boolean prime(int num) {
        if (num < 2) {
            return false; // Handle edge case for numbers < 2
        }
        if (num == 2) {
            return true; // 2 is prime
        }
        if (num % 2 == 0) {
            return false; // Even numbers > 2 are not prime
        }

        for (int divisor = 3; divisor <= Math.sqrt(num); divisor += 2) {
            if (num % divisor == 0) {
                return false;
            }
        }
        return true;
    }

    public static int reverse(int n) {
        int reverse = 0;
        while (n != 0) {
            reverse = reverse * 10 + (n % 10);
            n /= 10;
        }
        return reverse;
    }

    public static List<Integer> generatePalindromePrimes(int n) {
        List<Integer> palindromicPrimes = new ArrayList<>();
        if (n <= 0) {
            return palindromicPrimes; // Handle case for 0 or negative input
        }

        palindromicPrimes.add(2); // 2 is the first palindromic prime
        int count = 1;
        int num = 3;

        while (count < n) {
            if (num == reverse(num) && prime(num)) {
                palindromicPrimes.add(num);
                count++;
            }
            num += 2; // Skip even numbers
        }
        return palindromicPrimes;
    }
}

package com.thealgorithms.maths;

public final class ParseInteger {
    private ParseInteger() {
    }

    private static void checkInput(final String s) {
        if (s == null) {
            throw new NumberFormatException("Input parameter must not be null!");
        }
        if (s.isEmpty()) {
            throw new NumberFormatException("Input parameter must not be empty!");
        }
    }

    private static void checkDigitAt(final String s, final int pos) {
        if (!Character.isDigit(s.charAt(pos))) {
            throw new NumberFormatException("Input parameter of incorrect format: " + s);
        }
    }

    private static int digitToInt(final char digit) {
        return digit - '0';
    }

    /**
     * Parse a string to integer
     *
     * @param s the string
     * @return the integer value represented by the argument in decimal.
     * @throws NumberFormatException if the {@code string} does not contain a
     *                               parsable integer.
     */
    public static int parseInt(final String s) {
        checkInput(s);

        final boolean isNegative = s.charAt(0) == '-';
        final boolean isPositive = s.charAt(0) == '+';
        int number = 0;
        for (int i = isNegative || isPositive ? 1 : 0, length = s.length(); i < length; ++i) {
            checkDigitAt(s, i);
            number = number * 10 + digitToInt(s.charAt(i));
        }
        return isNegative ? -number : number;
    }
}

package com.thealgorithms.maths;

public final class PascalTriangle {
    private PascalTriangle() {
    }

    /**
     *In mathematics, Pascal's triangle is a triangular array of the binomial coefficients that
     *arises in probability theory, combinatorics, and algebra. In much of the Western world, it is
     *named after the French mathematician Blaise Pascal, although other mathematicians studied it
     *centuries before him in India, Persia, China, Germany, and Italy.
     *
     * The rows of Pascal's triangle are conventionally enumerated starting with row n=0 at the top
     *(the 0th row). The entries in each row are numbered from the left beginning with k=0 and are
     *usually staggered relative to the numbers in the adjacent rows. The triangle may be
     *constructed in the following manner: In row 0 (the topmost row), there is a unique nonzero
     *entry 1. Each entry of each subsequent row is constructed by adding the number above and to
     *the left with the number above and to the right, treating blank entries as 0. For example, the
     *initial number in the first (or any other) row is 1 (the sum of 0 and 1), whereas the numbers
     *1 and 3 in the third row are added to produce the number 4 in the fourth row. *
     *
     *<p>
     *     link:-https://en.wikipedia.org/wiki/Pascal%27s_triangle
     *
     * <p>
     *     Example:-
     *                  1
     *                1   1
     *              1   2   1
     *            1   3   3   1
     *          1   4   6   4   1
     *        1   5  10   10  5   1
     *      1   6  15  20   15  6   1
     *    1   7  21  35   35  21  7   1
     *  1   8  28  56  70   56   28  8   1
     *
     */

    public static int[][] pascal(int n) {
        /*
         * @param arr  An auxiliary array to store generated pascal triangle values
         * @return
         */
        int[][] arr = new int[n][n];
        /*
         * @param line Iterate through every line and print integer(s) in it
         * @param i Represents the column number of the element we are currently on
         */
        for (int line = 0; line < n; line++) {
            /*
             *  @Every line has number of integers equal to line number
             */
            for (int i = 0; i <= line; i++) {
                // First and last values in every row are 1
                if (line == i || i == 0) {
                    arr[line][i] = 1;
                } else {
                    arr[line][i] = arr[line - 1][i - 1] + arr[line - 1][i];
                }
            }
        }

        return arr;
    }
}

