/**
 * The Perrin Sequence is a sequence of integers defined by the recurrence relation:
 * P(n) = P(n-2) + P(n-3) with initial values P(0) = 3, P(1) = 0, P(2) = 2.
 * Example: 3, 0, 2, 3, 2, 5, 5, 7, 10, 12, 17, 22, 29, 39, 51...
 *
 * Note: The Perrin Sequence uses the same recurrence relation as the Padovan Sequence
 * but has different initial values.
 *
 * @see <a href="https://en.wikipedia.org/wiki/Perrin_number">
 *     Wikipedia: Perrin Number</a>
 * @see PadovanSequence
 */
public final class PerrinNumber {

    private PerrinNumber() {
        // Utility class
    }

    /**
     * Calculates the nth term of the Perrin Sequence.
     *
     * @param n the index of the sequence (must be non-negative)
     * @return the nth term of the Perrin Sequence
     */
    public static long perrin(final int n) {
        if (n < 0) {
            throw new IllegalArgumentException("Input must be non-negative!");
        }
        if (n == 0) {
            return 3;
        }
        if (n == 1) {
            return 0;
        }
        if (n == 2) {
            return 2;
        }
        long a = 3;
        long b = 0;
        long c = 2;
        long result = 0;
        for (int i = 3; i <= n; i++) {
            result = a + b;
            a = b;
            b = c;
            c = result;
        }
        return result;
    }
}

package com.thealgorithms.maths;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;

/**
 * Implementation to calculate an estimate of the number π (Pi).
 *
 * We take a random point P with coordinates (x, y) such that 0 ≤ x ≤ 1 and 0 ≤ y ≤ 1.
 * If x² + y² ≤ 1, then the point is inside the quarter disk of radius 1,
 * else the point is outside. We know that the probability of the point being
 * inside the quarter disk is equal to π/4.
 *
 *
 * @author [Yash Rajput](https://github.com/the-yash-rajput)
 */
public final class PiApproximation {

    private PiApproximation() {
        throw new AssertionError("No instances.");
    }

    /**
     * Structure representing a point with coordinates (x, y)
     * where 0 ≤ x ≤ 1 and 0 ≤ y ≤ 1.
     */
    static class Point {
        double x;
        double y;

        Point(double x, double y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * This function uses the points in a given list (drawn at random)
     * to return an approximation of the number π.
     *
     * @param pts List of points where each point contains x and y coordinates
     * @return An estimate of the number π
     */
    public static double approximatePi(List<Point> pts) {
        double count = 0; // Points in circle

        for (Point p : pts) {
            if ((p.x * p.x) + (p.y * p.y) <= 1) {
                count++;
            }
        }

        return 4.0 * count / pts.size();
    }

    /**
     * Generates random points for testing the Pi approximation.
     *
     * @param numPoints Number of random points to generate
     * @return List of random points
     */
    public static List<Point> generateRandomPoints(int numPoints) {
        List<Point> points = new ArrayList<>();
        Random rand = new Random();

        for (int i = 0; i < numPoints; i++) {
            double x = rand.nextDouble(); // Random value between 0 and 1
            double y = rand.nextDouble(); // Random value between 0 and 1
            points.add(new Point(x, y));
        }

        return points;
    }
}

package com.thealgorithms.maths;

public final class PiNilakantha {
    private PiNilakantha() {
    }

    // Calculates Pi using Nilakantha's infinite series
    // Method 2 in the following link explains the algorithm
    // https://en.scratch-wiki.info/wiki/Calculating_Pi
    public static void main(String[] args) {
        assert calculatePi(0) == 3.0;
        assert calculatePi(10) > 3.0;
        assert calculatePi(100) < 4.0;

        System.out.println(calculatePi(500));
    }

    /**
     * @param iterations number of times the infinite series gets repeated Pi
     * get more accurate the higher the value of iterations is Values from 0 up
     * to 500 are allowed since double precision is not sufficient for more than
     * about 500 repetitions of this algorithm
     * @return the pi value of the calculation with a precision of x iteration
     */
    public static double calculatePi(int iterations) {
        if (iterations < 0 || iterations > 500) {
            throw new IllegalArgumentException("Please input Integer Number between 0 and 500");
        }

        double pi = 3;
        int divCounter = 2;

        for (int i = 0; i < iterations; i++) {
            if (i % 2 == 0) {
                pi = pi + 4.0 / (divCounter * (divCounter + 1) * (divCounter + 2));
            } else {
                pi = pi - 4.0 / (divCounter * (divCounter + 1) * (divCounter + 2));
            }

            divCounter += 2;
        }
        return pi;
    }
}

package com.thealgorithms.maths;

/*
 * Java program for pollard rho algorithm
 * The algorithm is used to factorize a number n = pq,
 * where p is a non-trivial factor.
 * Pollard's rho algorithm is an algorithm for integer factorization
 * and it takes as its inputs n, the integer to be factored;
 * and g(x), a polynomial in x computed modulo n.
 * In the original algorithm, g(x) = ((x ^ 2) − 1) mod n,
 * but nowadays it is more common to use g(x) = ((x ^ 2) + 1 ) mod n.
 * The output is either a non-trivial factor of n, or failure.
 * It performs the following steps:
 *     x ← 2
 *     y ← 2
 *     d ← 1

 *     while d = 1:
 *         x ← g(x)
 *         y ← g(g(y))
 *         d ← gcd(|x - y|, n)

 *     if d = n:
 *         return failure
 *     else:
 *         return d

 * Here x and y corresponds to xi and xj in the previous section.
 * Note that this algorithm may fail to find a nontrivial factor even when n is composite.
 * In that case, the method can be tried again, using a starting value other than 2 or a different
 g(x)
 *
 * Wikipedia: https://en.wikipedia.org/wiki/Pollard%27s_rho_algorithm
 *
 * Author: Akshay Dubey (https://github.com/itsAkshayDubey)
 *
 * */
public final class PollardRho {
    private PollardRho() {
    }

    /**
     * This method returns a polynomial in x computed modulo n
     *
     * @param base Integer base of the polynomial
     * @param modulus Integer is value which is to be used to perform modulo operation over the
     *     polynomial
     * @return Integer (((base * base) - 1) % modulus)
     */
    static int g(int base, int modulus) {
        return ((base * base) - 1) % modulus;
    }

    /**
     * This method returns a non-trivial factor of given integer number
     *
     * @param number Integer is an integer value whose non-trivial factor is to be found
     * @return Integer non-trivial factor of number
     * @throws RuntimeException object if GCD of given number cannot be found
     */
    static int pollardRho(int number) {
        int x = 2;
        int y = 2;
        int d = 1;
        while (d == 1) {
            // tortoise move
            x = g(x, number);

            // hare move
            y = g(g(y, number), number);

            // check GCD of |x-y| and number
            d = GCD.gcd(Math.abs(x - y), number);
        }
        if (d == number) {
            throw new RuntimeException("GCD cannot be found.");
        }
        return d;
    }
}

package com.thealgorithms.maths;

/**
 * A utility class for computing exponentiation (power) of integers.
 * <p>
 * This class provides a method to calculate the value of a base raised to a given exponent using a simple iterative approach.
 * For example, given a base {@code a} and an exponent {@code b}, the class computes {@code a}<sup>{@code b}</sup>.
 * </p>
 */
public final class Pow {
    private Pow() {
    }

    /**
     * Computes the value of the base raised to the power of the exponent.
     * <p>
     * The method calculates {@code a}<sup>{@code b}</sup> by iteratively multiplying the base {@code a} with itself {@code b} times.
     * If the exponent {@code b} is negative, an {@code IllegalArgumentException} is thrown.
     * </p>
     *
     * @param a the base of the exponentiation. Must be a non-negative integer.
     * @param b the exponent to which the base {@code a} is raised. Must be a non-negative integer.
     * @return the result of {@code a}<sup>{@code b}</sup> as a {@code long}.
     * @throws IllegalArgumentException if {@code b} is negative.
     */
    public static long pow(int a, int b) {
        if (b < 0) {
            throw new IllegalArgumentException("Exponent must be non-negative.");
        }
        long result = 1;
        for (int i = 1; i <= b; i++) {
            result *= a;
        }
        return result;
    }
}

package com.thealgorithms.maths;

/**
 * Utility class for checking if a number is a power of four.
 * A power of four is a number that can be expressed as 4^n where n is a non-negative integer.
 * This class provides a method to determine if a given integer is a power of four using bit manipulation.
 *
 * @author krishna-medapati (https://github.com/krishna-medapati)
 */
public final class PowerOfFour {
    private PowerOfFour() {
    }

    /**
     * Checks if the given integer is a power of four.
     *
     * A number is considered a power of four if:
     * 1. It is greater than zero
     * 2. It has exactly one '1' bit in its binary representation (power of two)
     * 3. The '1' bit is at an even position (0, 2, 4, 6, ...)
     *
     * The method uses the mask 0x55555555 (binary: 01010101010101010101010101010101)
     * to check if the set bit is at an even position.
     *
     * @param number the integer to check
     * @return true if the number is a power of four, false otherwise
     */
    public static boolean isPowerOfFour(int number) {
        if (number <= 0) {
            return false;
        }
        boolean isPowerOfTwo = (number & (number - 1)) == 0;
        boolean hasEvenBitPosition = (number & 0x55555555) != 0;
        return isPowerOfTwo && hasEvenBitPosition;
    }
}

