package com.thealgorithms.maths;

import java.util.function.BiPredicate;

public final class SecondMinMax {

    /**
     * Utility class for finding second maximum or minimum based on BiPredicate
     * @exception IllegalArgumentException => if input array is of length less than 2 also if all elements are same
     * @return the second minimum / maximum value from the input array
     * @author Bharath Sanjeevi ( https://github.com/BharathSanjeeviT )
     */

    private SecondMinMax() {
    }

    private static int secondBest(final int[] arr, final int initialVal, final BiPredicate<Integer, Integer> isBetter) {
        checkInput(arr);
        int best = initialVal;
        int secBest = initialVal;
        for (final int num : arr) {
            if (isBetter.test(num, best)) {
                secBest = best;
                best = num;
            } else if ((isBetter.test(num, secBest)) && (num != best)) {
                secBest = num;
            }
        }
        checkOutput(secBest, initialVal);
        return secBest;
    }

    /**
     * @brief Finds the Second minimum / maximum value from the array
     * @param arr the input array
     * @exception IllegalArgumentException => if input array is of length less than 2 also if all elements are same
     * @return the second minimum / maximum value from the input array
     * @author Bharath Sanjeevi ( https://github.com/BharathSanjeeviT )
     */

    public static int findSecondMin(final int[] arr) {
        return secondBest(arr, Integer.MAX_VALUE, (a, b) -> a < b);
    }

    public static int findSecondMax(final int[] arr) {
        return secondBest(arr, Integer.MIN_VALUE, (a, b) -> a > b);
    }

    private static void checkInput(final int[] arr) {
        if (arr.length < 2) {
            throw new IllegalArgumentException("Input array must have length of at least two");
        }
    }

    private static void checkOutput(final int secNum, final int initialVal) {
        if (secNum == initialVal) {
            throw new IllegalArgumentException("Input array should have at least 2 distinct elements");
        }
    }
}

package com.thealgorithms.maths;

import java.util.ArrayList;
import java.util.List;

/**
 * Implementation of the Sieve of Atkin, an optimized algorithm to generate
 * all prime numbers up to a given limit.
 *
 * The Sieve of Atkin uses quadratic forms and modular arithmetic to identify
 * prime candidates, then eliminates multiples of squares. It is more efficient
 * than the Sieve of Eratosthenes for large limits.
 */
public final class SieveOfAtkin {

    private SieveOfAtkin() {
        // Utility class; prevent instantiation
    }

    /**
     * Generates a list of all prime numbers up to the specified limit
     * using the Sieve of Atkin algorithm.
     *
     * @param limit the upper bound up to which primes are generated; must be zero or positive
     * @return a list of prime numbers up to the limit; empty if the limit is less than 2
     */
    public static List<Integer> generatePrimes(int limit) {
        if (limit < 1) {
            return List.of();
        }

        boolean[] sieve = new boolean[limit + 1];
        int sqrtLimit = (int) Math.sqrt(limit);

        markQuadraticResidues(limit, sqrtLimit, sieve);
        eliminateMultiplesOfSquares(limit, sqrtLimit, sieve);

        List<Integer> primes = new ArrayList<>();
        if (limit >= 2) {
            primes.add(2);
        }
        if (limit >= 3) {
            primes.add(3);
        }

        for (int i = 5; i <= limit; i++) {
            if (sieve[i]) {
                primes.add(i);
            }
        }

        return primes;
    }

    /**
     * Marks numbers in the sieve as prime candidates based on quadratic residues.
     *
     * This method iterates over all x and y up to sqrt(limit) and applies
     * the three quadratic forms used in the Sieve of Atkin. Numbers satisfying
     * the modulo conditions are toggled in the sieve array.
     *
     * @param limit the upper bound for primes
     * @param sqrtLimit square root of the limit
     * @param sieve boolean array representing potential primes
     */
    private static void markQuadraticResidues(int limit, int sqrtLimit, boolean[] sieve) {
        for (int x = 1; x <= sqrtLimit; x++) {
            for (int y = 1; y <= sqrtLimit; y++) {
                applyQuadraticForm(4 * x * x + y * y, limit, sieve, 1, 5);
                applyQuadraticForm(3 * x * x + y * y, limit, sieve, 7);
                applyQuadraticForm(3 * x * x - y * y, limit, sieve, 11, x > y);
            }
        }
    }

    /**
     * Toggles the sieve entry for a number if it satisfies one modulo condition.
     *
     * @param n the number to check
     * @param limit upper bound of primes
     * @param sieve boolean array representing potential primes
     * @param modulo the modulo condition number to check
     */
    private static void applyQuadraticForm(int n, int limit, boolean[] sieve, int modulo) {
        if (n <= limit && n % 12 == modulo) {
            sieve[n] ^= true;
        }
    }

    /**
     * Toggles the sieve entry for a number if it satisfies either of two modulo conditions.
     *
     * @param n the number to check
     * @param limit upper bound of primes
     * @param sieve boolean array representing potential primes
     * @param modulo1 first modulo condition number to check
     * @param modulo2 second modulo condition number to check
     */
    private static void applyQuadraticForm(int n, int limit, boolean[] sieve, int modulo1, int modulo2) {
        if (n <= limit && (n % 12 == modulo1 || n % 12 == modulo2)) {
            sieve[n] ^= true;
        }
    }

    /**
     * Toggles the sieve entry for a number if it satisfies the modulo condition and an additional boolean condition.
     *
     * This version is used for the quadratic form 3*x*x - y*y, which requires x > y.
     *
     * @param n the number to check
     * @param limit upper bound of primes
     * @param sieve boolean array representing potential primes
     * @param modulo the modulo condition number to check
     * @param condition an additional boolean condition that must be true
     */
    private static void applyQuadraticForm(int n, int limit, boolean[] sieve, int modulo, boolean condition) {
        if (condition && n <= limit && n % 12 == modulo) {
            sieve[n] ^= true;
        }
    }

    /**
     * Eliminates numbers that are multiples of squares from the sieve.
     *
     * All numbers that are multiples of i*i (where i is marked as prime) are
     * marked non-prime to finalize the sieve. This ensures only actual primes remain.
     *
     * @param limit the upper bound for primes
     * @param sqrtLimit square root of the limit
     * @param sieve boolean array representing potential primes
     */
    private static void eliminateMultiplesOfSquares(int limit, int sqrtLimit, boolean[] sieve) {
        for (int i = 5; i <= sqrtLimit; i++) {
            if (!sieve[i]) {
                continue;
            }
            int square = i * i;
            for (int j = square; j <= limit; j += square) {
                sieve[j] = false;
            }
        }
    }
}

package com.thealgorithms.maths;

import java.util.ArrayList;
import java.util.List;

/**
 * Sieve of Eratosthenes Algorithm
 * An efficient algorithm to find all prime numbers up to a given limit.
 *
 * Algorithm:
 * 1. Create a boolean array of size n+1, initially all true
 * 2. Mark 0 and 1 as not prime
 * 3. For each number i from 2 to sqrt(n):
 *    - If i is still marked as prime
 *    - Mark all multiples of i (starting from i²) as not prime
 * 4. Collect all numbers still marked as prime
 *
 * Time Complexity: O(n log log n)
 * Space Complexity: O(n)
 *
 * @author Navadeep0007
 * @see <a href="https://en.wikipedia.org/wiki/Sieve_of_Eratosthenes">Sieve of Eratosthenes</a>
 */
public final class SieveOfEratosthenes {

    private SieveOfEratosthenes() {
        // Utility class, prevent instantiation
    }

    /**
     * Finds all prime numbers up to n using the Sieve of Eratosthenes algorithm
     *
     * @param n the upper limit (inclusive)
     * @return a list of all prime numbers from 2 to n
     * @throws IllegalArgumentException if n is negative
     */
    public static List<Integer> findPrimes(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("Input must be non-negative");
        }

        if (n < 2) {
            return new ArrayList<>();
        }

        // Create boolean array, initially all true
        boolean[] isPrime = new boolean[n + 1];
        for (int i = 2; i <= n; i++) {
            isPrime[i] = true;
        }

        // Sieve process
        for (int i = 2; i * i <= n; i++) {
            if (isPrime[i]) {
                // Mark all multiples of i as not prime
                for (int j = i * i; j <= n; j += i) {
                    isPrime[j] = false;
                }
            }
        }

        // Collect all prime numbers
        List<Integer> primes = new ArrayList<>();
        for (int i = 2; i <= n; i++) {
            if (isPrime[i]) {
                primes.add(i);
            }
        }

        return primes;
    }

    /**
     * Counts the number of prime numbers up to n
     *
     * @param n the upper limit (inclusive)
     * @return count of prime numbers from 2 to n
     */
    public static int countPrimes(int n) {
        return findPrimes(n).size();
    }
}

package com.thealgorithms.maths;

/**
 * Implementation of the Sigmoid Activation function.
 * Sigmoid function is used as an activation function in machine learning and neural networks
 * for modeling binary classification problems, smoothing outputs, and introducing non-linearity
 * into models.
 *
 * @author <a href="https://github.com/crapxxi">Alikhan Turugeldiyev</a>
 */

public final class SigmoidActivation {

    private SigmoidActivation() {
    }

    /**
     * @summary Maps any real-valued number into a value between 0 and 1
     * @param x In machine learning, x could be a weighted sum of inputs in a neural network neuron or a raw score in logistic regression.
     * @return The output (range) of the sigmoid function is always strictly between 0 and 1.
     */
    public static double activate(double x) {
        // If the number x is NaN then, returning NaN to saving from unexpected output.
        if (Double.isNaN(x)) {
            return Double.NaN;
        }
        // Saving from unnecessary and heavy calculations.
        // lim x->-inf sigmoid(x) will return number very close to 0
        if (x < -745) {
            return 0.0;
        }
        // lim x->inf sigmoid(x) will return number very close to 1
        if (x > 745) {
            return 1.0;
        }
        // sigmoid function's formula
        return 1.0 / (1 + Math.exp((-1) * x));
    }

    public static double[][] activate(double[][] x) {
        // apply calculation to every value in batch.
        double[][] activatedNumbers = new double[x.length][];
        for (int i = 0; i < x.length; i++) {
            activatedNumbers[i] = new double[x[i].length];
            for (int j = 0; j < x[i].length; j++) {
                activatedNumbers[i][j] = activate(x[i][j]);
            }
        }
        return activatedNumbers;
    }

    /**
     * @summary Calculates gradients for mapped values. By the chain rule, you can calculate error.
     * @param y Activated by sigmoid function value.
     * @return The output is a gradient of the activated value.
     */
    public static double grad(double y) {
        // sigmoid function derivative is reducing to this value.
        // sigmoid'(x) = sigmoid(x) * (1-sigmoid(x))
        return y * (1 - y);
    }

    public static double[][] grad(double[][] y) {
        // apply calculation to every value in batch.
        double[][] grads = new double[y.length][];
        for (int i = 0; i < y.length; i++) {
            grads[i] = new double[y[i].length];
            for (int j = 0; j < y[i].length; j++) {
                grads[i][j] = grad(y[i][j]);
            }
        }
        return grads;
    }
}

package com.thealgorithms.maths;

import java.util.TreeMap;

public class SimpsonIntegration {

    /*
     * Calculate definite integrals by using Composite Simpson's rule.
     * Wiki: https://en.wikipedia.org/wiki/Simpson%27s_rule#Composite_Simpson's_rule
     * Given f a function and an even number N of intervals that divide the integration interval
     * e.g. [a, b], we calculate the step h = (b-a)/N and create a table that contains all the x
     * points of the real axis xi = x0 + i*h and the value f(xi) that corresponds to these xi.
     *
     * To evaluate the integral i use the formula below:
     * I = h/3 * {f(x0) + 4*f(x1) + 2*f(x2) + 4*f(x3) + ... + 2*f(xN-2) + 4*f(xN-1) + f(xN)}
     *
     */
    public static void main(String[] args) {
        SimpsonIntegration integration = new SimpsonIntegration();

        // Give random data for the example purposes
        int n = 16;
        double a = 1;
        double b = 3;

        // Check so that n is even
        if (n % 2 != 0) {
            System.out.println("n must be even number for Simpsons method. Aborted");
            System.exit(1);
        }

        // Calculate step h and evaluate the integral
        double h = (b - a) / (double) n;
        double integralEvaluation = integration.simpsonsMethod(n, h, a);
        System.out.println("The integral is equal to: " + integralEvaluation);
    }

    /*
     * @param N: Number of intervals (must be even number N=2*k)
     * @param h: Step h = (b-a)/N
     * @param a: Starting point of the interval
     * @param b: Ending point of the interval
     *
     * The interpolation points xi = x0 + i*h are stored the treeMap data
     *
     * @return result of the integral evaluation
     */
    public double simpsonsMethod(int n, double h, double a) {
        TreeMap<Integer, Double> data = new TreeMap<>(); // Key: i, Value: f(xi)
        double temp;
        double xi = a; // Initialize the variable xi = x0 + 0*h

        // Create the table of xi and yi points
        for (int i = 0; i <= n; i++) {
            temp = f(xi); // Get the value of the function at that point
            data.put(i, temp);
            xi += h; // Increase the xi to the next point
        }

        // Apply the formula
        double integralEvaluation = 0;
        for (int i = 0; i < data.size(); i++) {
            if (i == 0 || i == data.size() - 1) {
                integralEvaluation += data.get(i);
                System.out.println("Multiply f(x" + i + ") by 1");
            } else if (i % 2 != 0) {
                integralEvaluation += (double) 4 * data.get(i);
                System.out.println("Multiply f(x" + i + ") by 4");
            } else {
                integralEvaluation += (double) 2 * data.get(i);
                System.out.println("Multiply f(x" + i + ") by 2");
            }
        }

        // Multiply by h/3
        integralEvaluation = h / 3 * integralEvaluation;

        // Return the result
        return integralEvaluation;
    }

    // Sample function f
    // Function f(x) = e^(-x) * (4 - x^2)
    public double f(double x) {
        return Math.exp(-x) * (4 - Math.pow(x, 2));
        //        return Math.sqrt(x);
    }
}

package com.thealgorithms.maths;

import com.thealgorithms.maths.Prime.PrimeCheck;

/**
 * In number theory, a smith number  is a composite number for which, in a given number base,
 *  the sum of its digits is equal to the sum of the digits in its prime factorization in the same base.
 *
 * For example, in base 10, 378 = 21 X 33 X 71 is a Smith number since 3 + 7 + 8 = 2 X 1 + 3 X 3 + 7 X 1,
 * and 22 = 21 X 111 is a Smith number, because 2 + 2 = 2 X 1 + (1 + 1) X 1.
 *
 * Wiki: https://en.wikipedia.org/wiki/Smith_number
 */
public final class SmithNumber {

    private SmithNumber() {
    }

    private static int primeFactorDigitSum(int n) {
        int sum = 0;
        int num = n;

        // Factorize the number using trial division
        for (int i = 2; i * i <= num; i++) {
            while (n % i == 0) { // while i divides n
                sum += SumOfDigits.sumOfDigits(i); // add sum of digits of factor
                n /= i; // divide n by the factor
            }
        }

        // If n is still > 1, it itself is a prime factor
        if (n > 1) {
            sum += SumOfDigits.sumOfDigits(n);
        }

        return sum;
    }

    /**
     * Check if {@code number} is Smith number or not
     *
     * @param number the number
     * @return {@code true} if {@code number} is a Smith number, otherwise false
     */
    public static boolean isSmithNumber(int number) {
        if (PrimeCheck.isPrime(number)) {
            return false; // Smith numbers must be composite
        }

        return SumOfDigits.sumOfDigits(number) == primeFactorDigitSum(number);
    }
}

package com.thealgorithms.maths;

/**
 * Sociable numbers are natural numbers that form a cyclic sequence where the
 * sum of proper divisors of each number equals the next number in the sequence,
 * with the sequence eventually returning to the starting number.
 * Amicable numbers are a special case of sociable numbers with a cycle length of 2.
 * Example: (12496, 14288, 15472, 14536, 14264) is a sociable cycle of length 5.
 *
 * @author Vraj Prajapati (@Rosander0)
 * @see <a href="https://en.wikipedia.org/wiki/Sociable_number">Wikipedia: Sociable Number</a>
 * @see AmicableNumber
 */
public final class SociableNumber {

    private SociableNumber() {
        // Utility class
    }

    /**
     * Calculates the sum of proper divisors of a number
     * (all divisors excluding the number itself).
     *
     * @param number the number to calculate proper divisors sum for
     * @return sum of proper divisors, or 0 if number is less than or equal to 1
     */
    static int sumOfProperDivisors(final int number) {
        if (number <= 1) {
            return 0;
        }
        int sum = 1; // 1 is a proper divisor of every number > 1
        final int root = (int) Math.sqrt(number);
        for (int i = 2; i <= root; i++) {
            if (number % i == 0) {
                final int other = number / i;
                sum += i;
                if (other != i) {
                    sum += other;
                }
            }
        }
        return sum;
    }

    /**
     * Checks whether a number is part of a sociable cycle of a given length.
     * Starting from the given number, it follows the chain of proper divisor
     * sums and checks if it returns to the starting number in exactly cycleLength steps.
     *
     * @param number the starting number (must be positive)
     * @param cycleLength the expected cycle length (must be greater than 1)
     * @return true if the number is part of a sociable cycle of given length, false otherwise
     */
    public static boolean isSociable(final int number, final int cycleLength) {
        if (number <= 0 || cycleLength <= 1) {
            return false;
        }
        int current = number;
        for (int i = 0; i < cycleLength; i++) {
            current = sumOfProperDivisors(current);
            if (current == number) {
                return i == cycleLength - 1;
            }
        }
        return false;
    }
}

package com.thealgorithms.maths;

import java.util.Random;

/**
 * This class implements the Solovay-Strassen primality test,
 * which is a probabilistic algorithm to determine whether a number is prime.
 * The algorithm is based on properties of the Jacobi symbol and modular exponentiation.
 *
 * For more information, go to {@link https://en.wikipedia.org/wiki/Solovay%E2%80%93Strassen_primality_test}
 */
final class SolovayStrassenPrimalityTest {

    private final Random random;

    /**
     * Constructs a SolovayStrassenPrimalityTest instance with a specified seed for randomness.
     *
     * @param seed the seed for generating random numbers
     */
    private SolovayStrassenPrimalityTest(int seed) {
        random = new Random(seed);
    }

    /**
     * Factory method to create an instance of SolovayStrassenPrimalityTest.
     *
     * @param seed the seed for generating random numbers
     * @return a new instance of SolovayStrassenPrimalityTest
     */
    public static SolovayStrassenPrimalityTest getSolovayStrassenPrimalityTest(int seed) {
        return new SolovayStrassenPrimalityTest(seed);
    }

    /**
     * Calculates modular exponentiation using the method of exponentiation by squaring.
     *
     * @param base the base number
     * @param exponent the exponent
     * @param mod the modulus
     * @return (base^exponent) mod mod
     */
    private static long calculateModularExponentiation(long base, long exponent, long mod) {
        long x = 1; // This will hold the result of (base^exponent) % mod
        long y = base; // This holds the current base value being squared

        while (exponent > 0) {
            // If exponent is odd, multiply the current base (y) with x
            if (exponent % 2 == 1) {
                x = x * y % mod; // Update result with current base
            }
            // Square the base for the next iteration
            y = y * y % mod; // Update base to be y^2
            exponent = exponent / 2; // Halve the exponent for next iteration
        }

        return x % mod; // Return final result after all iterations
    }

    /**
     * Computes the Jacobi symbol (a/n), which is a generalization of the Legendre symbol.
     *
     * @param a the numerator
     * @param num the denominator (must be an odd positive integer)
     * @return the Jacobi symbol value: 1, -1, or 0
     */
    public int calculateJacobi(long a, long num) {
        // Check if num is non-positive or even; Jacobi symbol is not defined in these cases
        if (num <= 0 || num % 2 == 0) {
            return 0;
        }

        a = a % num; // Reduce a modulo num to simplify calculations
        int jacobi = 1; // Initialize Jacobi symbol value

        while (a != 0) {
            // While a is even, reduce it and adjust jacobi based on properties of num
            while (a % 2 == 0) {
                a /= 2; // Divide a by 2 until it becomes odd
                long nMod8 = num % 8; // Get num modulo 8 to check conditions for jacobi adjustment
                if (nMod8 == 3 || nMod8 == 5) {
                    jacobi = -jacobi; // Flip jacobi sign based on properties of num modulo 8
                }
            }

            long temp = a; // Temporarily store value of a
            a = num; // Set a to be num for next iteration
            num = temp; // Set num to be previous value of a

            // Adjust jacobi based on properties of both numbers when both are odd and congruent to 3 modulo 4
            if (a % 4 == 3 && num % 4 == 3) {
                jacobi = -jacobi; // Flip jacobi sign again based on congruences
            }

            a = a % num; // Reduce a modulo num for next iteration of Jacobi computation
        }

        return (num == 1) ? jacobi : 0; // If num reduces to 1, return jacobi value, otherwise return 0 (not defined)
    }

    /**
     * Performs the Solovay-Strassen primality test on a given number.
     *
     * @param num the number to be tested for primality
     * @param iterations the number of iterations to run for accuracy
     * @return true if num is likely prime, false if it is composite
     */
    public boolean solovayStrassen(long num, int iterations) {
        if (num <= 1) {
            return false; // Numbers <=1 are not prime by definition.
        }
        if (num <= 3) {
            return true; // Numbers <=3 are prime.
        }

        for (int i = 0; i < iterations; i++) {
            long r = Math.abs(random.nextLong() % (num - 1)) + 2; // Generate a non-negative random number.
            long a = r % (num - 1) + 1; // Choose random 'a' in range [1, n-1].

            long jacobi = (num + calculateJacobi(a, num)) % num;
            // Calculate Jacobi symbol and adjust it modulo n.

            long mod = calculateModularExponentiation(a, (num - 1) / 2, num);
            // Calculate modular exponentiation: a^((n-1)/2) mod n.

            if (jacobi == 0 || mod != jacobi) {
                return false; // If Jacobi symbol is zero or doesn't match modular result, n is composite.
            }
        }

        return true; // If no contradictions found after all iterations, n is likely prime.
    }
}

package com.thealgorithms.maths;

public final class SquareRootWithBabylonianMethod {
    private SquareRootWithBabylonianMethod() {
    }

    /**
     * get the value, return the square root
     *
     * @param num contains elements
     * @return the square root of num
     */
    public static float squareRoot(float num) {
        float a = num;
        float b = 1;
        double e = 0.000001;
        while (a - b > e) {
            a = (a + b) / 2;
            b = num / a;
        }
        return a;
    }
}

package com.thealgorithms.maths;

/*
 *To learn about the method, visit the link below :
 * https://en.wikipedia.org/wiki/Newton%27s_method
 *
 * To obtain the square root, no built-in functions should be used
 *
 * The formula to calculate the root is : root = 0.5(x + n/x),
 * here, n is the no. whose square root has to be calculated and
 * x has to be guessed such that, the calculation should result into
 * the square root of n.
 * And the root will be obtained when the error < 0.5 or the precision value can also
 * be changed according to the user preference.
 */

public final class SquareRootWithNewtonRaphsonMethod {
    private SquareRootWithNewtonRaphsonMethod() {
    }

    public static double squareRoot(int n) {
        double x = n; // initially taking a guess that x = n.
        double root = 0.5 * (x + n / x); // applying Newton-Raphson Method.

        while (Math.abs(root - x) > 0.0000001) { // root - x = error and error < 0.0000001, 0.0000001
                                                 // is the precision value taken over here.
            x = root; // decreasing the value of x to root, i.e. decreasing the guess.
            root = 0.5 * (x + n / x);
        }

        return root;
    }
}

package com.thealgorithms.maths;

public final class StandardDeviation {
    private StandardDeviation() {
    }

    public static double stdDev(double[] data) {
        double variance = 0;
        double avg = 0;
        for (int i = 0; i < data.length; i++) {
            avg += data[i];
        }
        avg /= data.length;
        for (int j = 0; j < data.length; j++) {
            variance += Math.pow((data[j] - avg), 2);
        }
        variance /= data.length;
        return Math.sqrt(variance);
    }
}

