}

package com.thealgorithms.maths;

import java.util.HashMap;
import java.util.Map;

/**
 * A strobogrammatic number is a number that remains the same when rotated 180 degrees.
 * In other words, the number looks the same when rotated upside down.
 * Examples of strobogrammatic numbers are "69", "88", "818", and "101".
 * Numbers like "609" or "120" are not strobogrammatic because they do not look the same when rotated.
 */
public class StrobogrammaticNumber {
    /**
     * Check if a number is strobogrammatic
     * @param number the number to be checked
     * @return true if the number is strobogrammatic, false otherwise
     */
    public boolean isStrobogrammatic(String number) {
        Map<Character, Character> strobogrammaticMap = new HashMap<>();
        strobogrammaticMap.put('0', '0');
        strobogrammaticMap.put('1', '1');
        strobogrammaticMap.put('6', '9');
        strobogrammaticMap.put('8', '8');
        strobogrammaticMap.put('9', '6');

        int left = 0;
        int right = number.length() - 1;

        while (left <= right) {
            char leftChar = number.charAt(left);
            char rightChar = number.charAt(right);

            if (!strobogrammaticMap.containsKey(leftChar) || strobogrammaticMap.get(leftChar) != rightChar) {
                return false;
            }

            left++;
            right--;
        }

        return true;
    }
}

package com.thealgorithms.maths;

/**
 * In mathematics, an arithmetic progression (AP) or arithmetic sequence is a
 * sequence of numbers such that the difference between the consecutive terms is
 * constant. Difference here means the second minus the first. For instance, the
 * sequence 5, 7, 9, 11, 13, 15, . . . is an arithmetic progression with common
 * difference of 2.
 *
 * <p>
 * Wikipedia: https://en.wikipedia.org/wiki/Arithmetic_progression
 */
public final class SumOfArithmeticSeries {
    private SumOfArithmeticSeries() {
    }

    /**
     * Calculate sum of arithmetic series
     *
     * @param firstTerm the initial term of an arithmetic series
     * @param commonDiff the common difference of an arithmetic series
     * @param numOfTerms the total terms of an arithmetic series
     * @return sum of given arithmetic series
     */
    public static double sumOfSeries(final double firstTerm, final double commonDiff, final int numOfTerms) {
        if (numOfTerms < 0) {
            throw new IllegalArgumentException("numOfTerms nonnegative.");
        }
        return (numOfTerms / 2.0 * (2 * firstTerm + (numOfTerms - 1) * commonDiff));
    }
}

package com.thealgorithms.maths;

public final class SumOfDigits {
    private SumOfDigits() {
    }

    /**
     * Calculate the sum of digits of a number
     *
     * @param number the number contains digits
     * @return sum of digits of given {@code number}
     */
    public static int sumOfDigits(int number) {
        final int base = 10;
        number = Math.abs(number);
        int sum = 0;
        while (number != 0) {
            sum += number % base;
            number /= base;
        }
        return sum;
    }

    /**
     * Calculate the sum of digits of a number using recursion
     *
     * @param number the number contains digits
     * @return sum of digits of given {@code number}
     */
    public static int sumOfDigitsRecursion(int number) {
        final int base = 10;
        number = Math.abs(number);
        return number < base ? number : number % base + sumOfDigitsRecursion(number / base);
    }

    /**
     * Calculate the sum of digits of a number using char array
     *
     * @param number the number contains digits
     * @return sum of digits of given {@code number}
     */
    public static int sumOfDigitsFast(final int number) {
        return String.valueOf(Math.abs(number)).chars().map(c -> c - '0').reduce(0, Integer::sum);
    }
}

