package com.thealgorithms.searches;

import java.util.Scanner;

// Create a SearchAlgorithm class with a generic type
abstract class SearchAlgorithm<T extends Comparable<T>> {
    // Abstract find method to be implemented by subclasses
    public abstract int find(T[] arr, T target);
}

public class RecursiveBinarySearch<T extends Comparable<T>> extends SearchAlgorithm<T> {

    // Override the find method as required
    @Override
    public int find(T[] arr, T target) {
        // Call the recursive binary search function
        return binsear(arr, 0, arr.length - 1, target);
    }

    // Recursive binary search function
    public int binsear(T[] arr, int left, int right, T target) {
        if (right < left) {
            // Element is not present in the array
            return -1;
        }
        final int mid = left + (right - left) / 2;

        // Compare the element at the middle with the target
        final int comparison = arr[mid].compareTo(target);

        // If the element is equal to the target, return its index
        if (comparison == 0) {
            return mid;
        }

        // If the element is greater than the target, search in the left subarray
        if (comparison > 0) {
            return binsear(arr, left, mid - 1, target);
        }

        // Otherwise, search in the right subarray
        return binsear(arr, mid + 1, right, target);
    }

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            // User inputs
            System.out.print("Enter the number of elements in the array: ");
            int n = sc.nextInt();

            Integer[] a = new Integer[n]; // You can change the array type as needed

            System.out.println("Enter the elements in sorted order:");

            for (int i = 0; i < n; i++) {
                a[i] = sc.nextInt();
            }

            System.out.print("Enter the target element to search for: ");
            int t = sc.nextInt();

            RecursiveBinarySearch<Integer> searcher = new RecursiveBinarySearch<>();
            int res = searcher.find(a, t);

            if (res == -1) {
                System.out.println("Element not found in the array.");
            } else {
                System.out.println("Element found at index " + res);
            }
        }
    }
}

package com.thealgorithms.searches;

import com.thealgorithms.devutils.searches.SearchAlgorithm;

/**
 * Searches for a key in a sorted array that has been rotated at an unknown pivot.
 *
 * <p>
 * Example:
 * {@code [8, 9, 10, 1, 2, 3, 4, 5, 6, 7]}
 *
 * <p>
 * This is a modified binary search. When the array contains no duplicates, the
 * time complexity is {@code O(log n)}. With duplicates, the algorithm still
 * works but may degrade to {@code O(n)} in the worst case.
 *
 * @see <a href="https://en.wikipedia.org/wiki/Search_in_rotated_sorted_array">Search in rotated sorted array</a>
 * @see SearchAlgorithm
 */
public final class RotatedBinarySearch implements SearchAlgorithm {

    @Override
    public <T extends Comparable<T>> int find(T[] array, T key) {
        int left = 0;
        int right = array.length - 1;

        while (left <= right) {
            int middle = (left + right) >>> 1;
            int cmp = key.compareTo(array[middle]);
            if (cmp == 0) {
                return middle;
            }

            // Handle duplicates: if we cannot determine which side is sorted.
            if (array[left].compareTo(array[middle]) == 0 && array[middle].compareTo(array[right]) == 0) {
                left++;
                right--;
                continue;
            }

            // Left half is sorted.
            if (array[left].compareTo(array[middle]) <= 0) {
                if (array[left].compareTo(key) <= 0 && key.compareTo(array[middle]) < 0) {
                    right = middle - 1;
                } else {
                    left = middle + 1;
                }
            } else {
                // Right half is sorted.
                if (array[middle].compareTo(key) < 0 && key.compareTo(array[right]) <= 0) {
                    left = middle + 1;
                } else {
                    right = middle - 1;
                }
            }
        }

        return -1;
    }
}

package com.thealgorithms.searches;

import com.thealgorithms.devutils.searches.MatrixSearchAlgorithm;

/**
 * The search is for any array which is sorted row and column-wise too. For ex :
 * {{10, 20, 30, 40},
 *  {15, 25, 35, 45},
 *  {18, 28, 38, 48},
 *  {21, 31, 41, 51}}
 *
 * This array is sorted in both row and column manner.
 * In this two pointers are taken, the first points to the 0th row and the second one points to end
 * column, and then the element corresponding to the pointers placed in the array is compared with
 * the target that either its equal, greater or smaller than the target. If the element is equal to
 * the target, the coordinates of that element is returned i.e. an array of the two pointers will
 * be returned, else if the target is greater than corresponding element then the pointer pointing
 * to the 0th row will be incremented by 1, else if the target is lesser than the corresponding
 * element then the pointer pointing to the end column will be decremented by 1. And if the element
 * doesn't exist in the array, an array
 * {-1, -1} will be returned.
 */
public class RowColumnWiseSorted2dArrayBinarySearch implements MatrixSearchAlgorithm {

    @Override
    public <T extends Comparable<T>> int[] find(T[][] matrix, T key) {
        return search(matrix, key);
    }

    public static <T extends Comparable<T>> int[] search(T[][] matrix, T target) {
        int rowPointer = 0; // The pointer at 0th row
        int colPointer = matrix[0].length - 1; // The pointer at end column

        while (rowPointer < matrix.length && colPointer >= 0) {
            int comp = target.compareTo(matrix[rowPointer][colPointer]);

            if (comp == 0) {
                return new int[] {rowPointer, colPointer};
            } else if (comp > 0) {
                rowPointer++; // Incrementing the row pointer if the target is greater
            } else {
                colPointer--; // Decrementing the column pointer if the target is lesser
            }
        }
        return new int[] {-1, -1}; // The not found condition
    }
}

package com.thealgorithms.searches;

/**
 * Program to perform Saddleback Search Given a sorted 2D array(elements are
 * sorted across every row and column, assuming ascending order) of size n*m we
 * can search a given element in O(n+m)
 *
 * <p>
 * we start from bottom left corner if the current element is greater than the
 * given element then we move up else we move right Sample Input: 5 5
 * ->Dimensions -10 -5 -3 4 9 -6 -2 0 5 10 -4 -1 1 6 12 2 3 7 8 13 100 120 130
 * 140 150 140 ->element to be searched output: 4 3 // first value is row,
 * second one is column
 *
 * @author Nishita Aggarwal
 */
public final class SaddlebackSearch {
    private SaddlebackSearch() {
    }

    /**
     * This method performs Saddleback Search
     *
     * @param arr The **Sorted** array in which we will search the element.
     * @param row the current row.
     * @param col the current column.
     * @param key the element that we want to search for.
     * @throws IllegalArgumentException if the array is empty.
     * @return The index(row and column) of the element if found. Else returns
     * -1 -1.
     */
    static int[] find(int[][] arr, int row, int col, int key) {
        if (arr.length == 0) {
            throw new IllegalArgumentException("Array is empty");
        }

        // array to store the answer row and column
        int[] ans = {-1, -1};
        if (row < 0 || col >= arr[row].length) {
            return ans;
        }
        if (arr[row][col] == key) {
            ans[0] = row;
            ans[1] = col;
            return ans;
        } // if the current element is greater than the given element then we move up
        else if (arr[row][col] > key) {
            return find(arr, row - 1, col, key);
        }
        // else we move right
        return find(arr, row, col + 1, key);
    }
}

package com.thealgorithms.searches;

public class SearchInARowAndColWiseSortedMatrix {
    /**
     * Search a key in row and column wise sorted matrix
     *
     * @param matrix matrix to be searched
     * @param value  Key being searched for
     * @author Sadiul Hakim : https://github.com/sadiul-hakim
     */
    public int[] search(int[][] matrix, int value) {
        int n = matrix.length;
        // This variable iterates over rows
        int i = 0;
        // This variable iterates over columns
        int j = n - 1;
        int[] result = {-1, -1};
        while (i < n && j >= 0) {
            if (matrix[i][j] == value) {
                result[0] = i;
                result[1] = j;
                return result;
            }
            if (value > matrix[i][j]) {
                i++;
            } else {
                j--;
            }
        }
        return result;
    }
}

package com.thealgorithms.searches;

import com.thealgorithms.devutils.searches.SearchAlgorithm;

/**
 * Sentinel Linear Search is a variation of linear search that eliminates the
 * need to check the array bounds in each iteration by placing the search key
 * at the end of the array as a sentinel value.
 *
 * <p>
 * The algorithm works by:
 * 1. Storing the last element of the array
 * 2. Placing the search key at the last position (sentinel)
 * 3. Searching from the beginning without bound checking
 * 4. If found before the last position, return the index
 * 5. If found at the last position, check if it was originally there
 *
 * <p>
 * Time Complexity:
 * - Best case: O(1) - when the element is at the first position
 * - Average case: O(n) - when the element is in the middle
 * - Worst case: O(n) - when the element is not present
 *
 * <p>
 * Space Complexity: O(1) - only uses constant extra space
 *
 * <p>
 * Advantages over regular linear search:
 * - Reduces the number of comparisons by eliminating bound checking
 * - Slightly more efficient in practice due to fewer conditional checks
 *
 * @author TheAlgorithms Contributors
 * @see LinearSearch
 * @see SearchAlgorithm
 */
public class SentinelLinearSearch implements SearchAlgorithm {
    /**
     * Performs sentinel linear search on the given array.
     *
     * @param array the array to search in
     * @param key the element to search for
     * @param <T> the type of elements in the array, must be Comparable
     * @return the index of the first occurrence of the key, or -1 if not found
     * @throws IllegalArgumentException if the array is null
     */
    @Override
    public <T extends Comparable<T>> int find(T[] array, T key) {
        if (array == null) {
            throw new IllegalArgumentException("Array cannot be null");
        }

        if (array.length == 0) {
            return -1;
        }

        if (key == null) {
            return findNull(array);
        }

        // Store the last element
        T lastElement = array[array.length - 1];

        // Place the sentinel (search key) at the end
        array[array.length - 1] = key;

        int i = 0;
        // Search without bound checking since sentinel guarantees we'll find the key
        // Null check for array element to prevent NPE when array contains null elements
        while (array[i] != null && array[i].compareTo(key) != 0) {
            i++;
        }

        // Restore the original last element
        array[array.length - 1] = lastElement;

        // Check if we found the key before the sentinel position
        // or if the original last element was the key we were looking for
        if (i < array.length - 1 || (lastElement != null && lastElement.compareTo(key) == 0)) {
            return i;
        }

        return -1; // Key not found
    }

    /**
     * Helper method to find null values in the array.
     *
     * @param array the array to search in
     * @param <T> the type of elements in the array
     * @return the index of the first null element, or -1 if not found
     */
    private <T extends Comparable<T>> int findNull(T[] array) {
        for (int i = 0; i < array.length; i++) {
            if (array[i] == null) {
                return i;
            }
        }
        return -1;
    }
}

package com.thealgorithms.searches;

/**
 * Given an integer x, find the square root of x. If x is not a perfect square,
 * then return floor(√x).
 * <p>
 * For example, if x = 5, The answer should be 2 which is the floor value of √5.
 * <p>
 * The approach that will be used for solving the above problem is not going to
 * be a straight forward Math.sqrt(). Instead we will be using Binary Search to
 * find the square root of a number in the most optimised way.
 *
 * @author sahil
 */
public final class SquareRootBinarySearch {
    private SquareRootBinarySearch() {
    }

    /**
     * This function calculates the floor of square root of a number. We use
     * Binary Search algorithm to calculate the square root in a more optimised
     * way.
     *
     * @param num Number
     * @return answer
     */
    static long squareRoot(long num) {
        if (num == 0 || num == 1) {
            return num;
        }
        long l = 1;
        long r = num;
        long ans = 0;
        while (l <= r) {
            long mid = l + (r - l) / 2;
            if (mid == num / mid) {
                return mid;
            } else if (mid < num / mid) {
                ans = mid;
                l = mid + 1;
            } else {
                r = mid - 1;
            }
        }
        return ans;
    }
}

package com.thealgorithms.searches;

import com.thealgorithms.devutils.searches.SearchAlgorithm;

/**
 * A ternary search algorithm is a technique in computer science for finding the
 * minimum or maximum of a unimodal function The algorithm determines either
 * that the minimum or maximum cannot be in the first third of the domain or
 * that it cannot be in the last third of the domain, then repeats on the
 * remaining third.
 *
 * <p>
 * Worst-case performance Θ(log3(N)) Best-case performance O(1) Average
 * performance Θ(log3(N)) Worst-case space complexity O(1)
 *
 * @author Podshivalov Nikita (https://github.com/nikitap492)
 * @see SearchAlgorithm
 * @see IterativeBinarySearch
 */
public class TernarySearch implements SearchAlgorithm {

    /**
     * @param arr The **Sorted** array in which we will search the element.
     * @param value The value that we want to search for.
     * @return The index of the element if found. Else returns -1.
     */
    @Override
    public <T extends Comparable<T>> int find(T[] arr, T value) {
        return ternarySearch(arr, value, 0, arr.length - 1);
    }

    /**
     * @param arr The **Sorted** array in which we will search the element.
     * @param key The value that we want to search for.
     * @param start The starting index from which we will start Searching.
     * @param end The ending index till which we will Search.
     * @return Returns the index of the Element if found. Else returns -1.
     */
    private <T extends Comparable<T>> int ternarySearch(T[] arr, T key, int start, int end) {
        if (start > end) {
            return -1;
        }
        /* First boundary: add 1/3 of length to start */
        int mid1 = start + (end - start) / 3;
        /* Second boundary: add 2/3 of length to start */
        int mid2 = start + 2 * (end - start) / 3;

        if (key.compareTo(arr[mid1]) == 0) {
            return mid1;
        } else if (key.compareTo(arr[mid2]) == 0) {
            return mid2;
        } /* Search the first (1/3) rd part of the array.*/ else if (key.compareTo(arr[mid1]) < 0) {
            return ternarySearch(arr, key, start, --mid1);
        } /* Search 3rd (1/3)rd part of the array */ else if (key.compareTo(arr[mid2]) > 0) {
            return ternarySearch(arr, key, ++mid2, end);
        } /* Search middle (1/3)rd part of the array */ else {
            return ternarySearch(arr, key, mid1, mid2);
        }
    }
}

package com.thealgorithms.searches;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * The Union-Find data structure, also known as Disjoint Set Union (DSU),
 * is a data structure that tracks a set of elements partitioned into
 * disjoint (non-overlapping) subsets. It supports two main operations:
 *
 * 1. **Find**: Determine which subset a particular element is in.
 * 2. **Union**: Join two subsets into a single subset.
 *
 * This implementation uses path compression in the `find` operation
 * and union by rank in the `union` operation for efficiency.
 */
public class UnionFind {

    private final int[] p; // Parent array
    private final int[] r; // Rank array

    /**
     * Initializes a Union-Find data structure with n elements.
     * Each element is its own parent initially.
     *
     * @param n the number of elements
     */
    public UnionFind(int n) {
        p = new int[n];
        r = new int[n];

        for (int i = 0; i < n; i++) {
            p[i] = i;
        }
    }

    /**
     * Finds the root of the set containing the element i.
     * Uses path compression to flatten the structure.
     *
     * @param i the element to find
     * @return the root of the set
     */
    public int find(int i) {
        int parent = p[i];

        if (i == parent) {
            return i;
        }

        // Path compression
        final int result = find(parent);
        p[i] = result;
        return result;
    }

    /**
     * Unites the sets containing elements x and y.
     * Uses union by rank to attach the smaller tree under the larger tree.
     *
     * @param x the first element
     * @param y the second element
     */
    public void union(int x, int y) {
        int r0 = find(x);
        int r1 = find(y);

        if (r1 == r0) {
            return;
        }

        // Union by rank
        if (r[r0] > r[r1]) {
            p[r1] = r0;
        } else if (r[r1] > r[r0]) {
            p[r0] = r1;
        } else {
            p[r1] = r0;
            r[r0]++;
        }
    }

    /**
     * Counts the number of disjoint sets.
     *
     * @return the number of disjoint sets
     */
    public int count() {
        List<Integer> parents = new ArrayList<>();
        for (int i = 0; i < p.length; i++) {
            int root = find(i);
            if (!parents.contains(root)) {
                parents.add(root);
            }
        }
        return parents.size();
    }

    @Override
    public String toString() {
        return "p " + Arrays.toString(p) + " r " + Arrays.toString(r) + "\n";
    }
}

package com.thealgorithms.searches;

import com.thealgorithms.devutils.searches.SearchAlgorithm;

/**
 * The UpperBound method is used to return an index pointing to the first
 * element in the range [first, last) which has a value greater than val, or the
 * last index if no such element exists i.e. the index of the next smallest
 * number just greater than that number. If there are multiple values that are
 * equal to val it returns the index of the first such value.
 *
 * <p>
 * This is an extension of BinarySearch.
 *
 * <p>
 * Worst-case performance O(log n) Best-case performance O(1) Average
 * performance O(log n) Worst-case space complexity O(1)
 *
 * @author Pratik Padalia (https://github.com/15pratik)
 * @see SearchAlgorithm
 * @see BinarySearch
 */
class UpperBound implements SearchAlgorithm {

    /**
     * @param array is an array where the UpperBound value is to be found
     * @param key is an element for which the UpperBound is to be found
     * @param <T> is any comparable type
     * @return index of the UpperBound element
     */
    @Override
    public <T extends Comparable<T>> int find(T[] array, T key) {
        return search(array, key, 0, array.length - 1);
    }

    /**
     * This method implements the Generic Binary Search
     *
     * @param array The array to make the binary search
     * @param key The number you are looking for
     * @param left The lower bound
     * @param right The upper bound
     * @return the location of the key
     */
    private <T extends Comparable<T>> int search(T[] array, T key, int left, int right) {
        if (right <= left) {
            return left;
        }

        // find median
        int median = (left + right) >>> 1;
        int comp = key.compareTo(array[median]);

        if (comp < 0) {
            // key is smaller, median position can be a possible solution
            return search(array, key, left, median);
        } else {
            // key we are looking is greater, so we must look on the right of median position
            return search(array, key, median + 1, right);
        }
    }
}

package com.thealgorithms.slidingwindow;

import java.util.HashMap;
import java.util.Map;

/**
 * Counts the number of distinct elements in every window of size k.
 *
 * @see <a href="https://www.geeksforgeeks.org/count-distinct-elements-in-every-window-of-size-k/">Reference</a>
 */
public final class CountDistinctElementsInWindow {

    private CountDistinctElementsInWindow() {
    }

    /**
     * Returns an array where each element is the count of distinct
     * elements in the corresponding window of size k.
     *
     * @param arr the input array
     * @param k   the window size
     * @return array of distinct element counts per window
     */
    public static int[] countDistinct(int[] arr, int k) {
        if (arr == null || arr.length == 0 || k <= 0 || k > arr.length) {
            throw new IllegalArgumentException("Invalid input");
        }

        int n = arr.length;
        int[] result = new int[n - k + 1];
        Map<Integer, Integer> freqMap = new HashMap<>();

        for (int i = 0; i < k; i++) {
            freqMap.merge(arr[i], 1, Integer::sum);
        }
        result[0] = freqMap.size();

        for (int i = k; i < n; i++) {
            freqMap.merge(arr[i], 1, Integer::sum);

            int outgoing = arr[i - k];

            Integer count = freqMap.get(outgoing);
            if (count != null) {
                if (count == 1) {
                    freqMap.remove(outgoing);
                } else {
                    freqMap.put(outgoing, count - 1);
                }
            }

            result[i - k + 1] = freqMap.size();
        }

        return result;
    }
}

package com.thealgorithms.slidingwindow;

/**
 * Counts the number of "nice subarrays".
 * A nice subarray is a contiguous subarray that contains exactly k odd numbers.
 *
 * This implementation uses the sliding window technique.
 *
 * Reference:
 * https://leetcode.com/problems/count-number-of-nice-subarrays/
 *
 * Time Complexity: O(n)
 * Space Complexity: O(n)
 */
public final class CountNiceSubarrays {

    // Private constructor to prevent instantiation
    private CountNiceSubarrays() {
    }

    /**
     * Returns the count of subarrays containing exactly k odd numbers.
     *
     * @param nums input array of integers
     * @param k    number of odd elements required in the subarray
     * @return number of nice subarrays
     */
    public static int countNiceSubarrays(int[] nums, int k) {

        int n = nums.length;

        // Left pointer of the sliding window
        int left = 0;

        // Tracks number of odd elements in the current window
        int oddCount = 0;

        // Final answer: total number of nice subarrays
        int result = 0;

        /*
         * memo[i] stores how many valid starting positions exist
         * when the left pointer is at index i.
         *
         * This avoids recomputing the same values again.
         */
        int[] memo = new int[n];

        // Right pointer moves forward to expand the window
        for (int right = 0; right < n; right++) {

            // If current element is odd, increment odd count
            if ((nums[right] & 1) == 1) {
                oddCount++;
            }

            /*
             * If oddCount exceeds k, shrink the window from the left
             * until oddCount becomes valid again.
             */
            if (oddCount > k) {
                left += memo[left];
                oddCount--;
            }

            /*
             * When the window contains exactly k odd numbers,
             * count all possible valid subarrays starting at `left`.
             */
            if (oddCount == k) {

                /*
                 * If this left index hasn't been processed before,
                 * count how many consecutive even numbers follow it.
                 */
                if (memo[left] == 0) {
                    int count = 0;
                    int temp = left;

                    // Count consecutive even numbers
                    while ((nums[temp] & 1) == 0) {
                        count++;
                        temp++;
                    }

                    /*
                     * Number of valid subarrays starting at `left`
                     * is (count of even numbers + 1)
                     */
                    memo[left] = count + 1;
                }

                // Add number of valid subarrays for this left position
                result += memo[left];
            }
        }
        return result;
    }
}

package com.thealgorithms.slidingwindow;

/**
 * The Longest Subarray with Sum Less Than or Equal to k algorithm finds the length
 * of the longest subarray whose sum is less than or equal to a given value k.
 *
 * <p>
 * Worst-case performance O(n)
 * Best-case performance O(n)
 * Average performance O(n)
 * Worst-case space complexity O(1)
 *
 * @author https://github.com/Chiefpatwal
 */
public final class LongestSubarrayWithSumLessOrEqualToK {

    // Prevent instantiation
    private LongestSubarrayWithSumLessOrEqualToK() {
    }

    /**
     * This method finds the length of the longest subarray with a sum less than or equal to k.
     *
     * @param arr is the input array
     * @param k   is the maximum sum allowed
     * @return the length of the longest subarray with sum less than or equal to k
     */
    public static int longestSubarrayWithSumLEK(int[] arr, int k) {
        int maxLength = 0; // To store the maximum length found
        int currentSum = 0; // To store the current sum of the window
        int left = 0; // Left index of the sliding window

        for (int right = 0; right < arr.length; right++) {
            currentSum += arr[right]; // Expand the window to the right

            // Shrink the window from the left if the current sum exceeds k
            while (currentSum > k && left <= right) {
                currentSum -= arr[left]; // Remove the leftmost element
                left++; // Move the left index to the right
            }

            // Update maxLength if the current window is valid
            maxLength = Math.max(maxLength, right - left + 1);
        }

        return maxLength; // Return the maximum length found
    }
}

