                fresh1.val = a[i1]; // Value is stored in the value part of the node
                if (start1 == null) {
                    start1 = fresh1;
                } else {
                    prev1.next = fresh1;
                }
                prev1 = fresh1;
            }
            Task1 kk = new Task1();
            start1 = kk.sortByInsertionSort(start1);
            // method is being called
