package com.thealgorithms.strings;

/**
 * @author Marcus
 */
public final class CountWords {
    private CountWords() {
    }

    /**
     * Counts the number of words in the input string. Words are defined as sequences of
     * characters separated by whitespace.
     *
     * @param s the input string
     * @return the number of words in the input string, or 0 if the string is null or empty
     */
    public static int wordCount(String s) {
        if (s == null || s.isEmpty()) {
            return 0;
        }
        return s.trim().split("\\s+").length;
    }

    /**
     * Removes all special characters from the input string, leaving only alphanumeric characters
     * and whitespace.
     *
     * @param s the input string
     * @return a string containing only alphanumeric characters and whitespace
     */
    private static String removeSpecialCharacters(String s) {
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (Character.isLetterOrDigit(c) || Character.isWhitespace(c)) {
                sb.append(c);
            }
        }
        return sb.toString();
    }

    /**
     * Counts the number of words in a sentence, ignoring all non-alphanumeric characters that do
     * not contribute to word formation. This method has a time complexity of O(n), where n is the
     * length of the input string.
     *
     * @param s the input string
     * @return the number of words in the input string, with special characters removed, or 0 if the string is null
     */
    public static int secondaryWordCount(String s) {
        if (s == null) {
            return 0;
        }
        return wordCount(removeSpecialCharacters(s));
    }
}

package com.thealgorithms.strings;

/**
 * Class for calculating the Hamming distance between two strings of equal length.
 * <p>
 * The Hamming distance is the number of positions at which the corresponding symbols are different.
 * It is used in information theory, coding theory, and computer science.
 * </p>
 * @see <a href="https://en.wikipedia.org/wiki/Hamming_distance">Hamming distance - Wikipedia</a>
 */
public final class HammingDistance {
    private HammingDistance() {
    }

    /**
     * Calculates the Hamming distance between two strings of equal length.
     * <p>
     * The Hamming distance is defined only for strings of equal length. If the strings are not
     * of equal length, this method throws an {@code IllegalArgumentException}.
     * </p>
     *
     * @param s1 the first string
     * @param s2 the second string
     * @return the Hamming distance between the two strings
     * @throws IllegalArgumentException if the lengths of {@code s1} and {@code s2} are not equal
     */
    public static int calculateHammingDistance(String s1, String s2) {
        if (s1 == null || s2 == null) {
            throw new IllegalArgumentException("Strings must not be null");
        }

        if (s1.length() != s2.length()) {
            throw new IllegalArgumentException("String lengths must be equal");
        }

        int distance = 0;

        for (int i = 0; i < s1.length(); i++) {
            if (s1.charAt(i) != s2.charAt(i)) {
                distance++;
            }
        }
        return distance;
    }
}

package com.thealgorithms.strings;

import java.util.HashMap;

/**
 * This class is not thread safe<br>
 * <br>
 * (From wikipedia) In computer science, the Boyer–Moore–Horspool algorithm or
 * Horspool's algorithm is an algorithm for finding substrings in strings. It
 * was published by Nigel Horspool in 1980.
 * <br>
 * <a href=https://en.wikipedia.org/wiki/Boyer%E2%80%93Moore%E2%80%93Horspool_algorithm>Wikipedia
 * page</a><br>
 * <br>
 *
 * <p>
 * An explanation:<br>
 *
 * <p>
 * The Horspool algorithm is a simplification of the Boyer-Moore algorithm in
 * that it uses only one of the two heuristic methods for increasing the number
 * of characters shifted when finding a bad match in the text. This method is
 * usually called the "bad symbol" or "bad character" shift. The bad symbol
 * shift method is classified as an input enhancement method in the theory of
 * algorithms. Input enhancement is (from wikipedia) the principle that
 * processing a given input to a problem and altering it in a specific way will
 * increase runtime efficiency or space efficiency, or both. Both algorithms try
 * to match the pattern and text comparing the pattern symbols to the text's
 * from right to left.<br>
 * <br>
 *
 * <p>
 * In the bad symbol shift method, a table is created prior to the search,
 * called the "bad symbol table". The bad symbol table contains the shift values
 * for any symbol in the text and pattern. For these symbols, the value is the
 * length of the pattern, if the symbol is not in the first (length - 1) of the
 * pattern. Else it is the distance from its rightmost occurrence in the pattern
 * to the last symbol of the pattern. In practice, we only calculate the values
 * for the ones that exist in the first (length - 1) of the pattern.<br>
 * <br>
 *
 * <p>
 * For more details on the algorithm and the more advanced Boyer-Moore I
 * recommend checking out the wikipedia page and professor Anany Levitin's book:
 * Introduction To The Design And Analysis Of Algorithms.
 */
public final class HorspoolSearch {
    private HorspoolSearch() {
    }

    private static HashMap<Character, Integer> shiftValues; // bad symbol table
    private static Integer patternLength;
    private static int comparisons = 0; // total comparisons in the current/last search

    /**
     * Case sensitive version version of the algorithm
     *
     * @param pattern the pattern to be searched for (needle)
     * @param text the text being searched in (haystack)
     * @return -1 if not found or first index of the pattern in the text
     */
    public static int findFirst(String pattern, String text) {
        return firstOccurrence(pattern, text, true);
    }

    /**
     * Case insensitive version version of the algorithm
     *
     * @param pattern the pattern to be searched for (needle)
     * @param text the text being searched in (haystack)
     * @return -1 if not found or first index of the pattern in the text
     */
    public static int findFirstInsensitive(String pattern, String text) {
        return firstOccurrence(pattern, text, false);
    }

    /**
     * Utility method that returns comparisons made by last run (mainly for
     * tests)
     *
     * @return number of character comparisons of the last search
     */
    public static Integer getLastComparisons() {
        return HorspoolSearch.comparisons;
    }

    /**
     * Fairly standard implementation of the Horspool algorithm. Only the index
     * of the last character of the pattern on the text is saved and shifted by
     * the appropriate amount when a mismatch is found. The algorithm stops at
     * the first match or when the entire text has been exhausted.
     *
     * @param pattern String to be matched in the text
     * @param text text String
     * @return index of first occurrence of the pattern in the text
     */
    private static int firstOccurrence(String pattern, String text, boolean caseSensitive) {
        shiftValues = calcShiftValues(pattern); // build the bad symbol table
        comparisons = 0; // reset comparisons

        if (pattern.length() == 0) { // return failure, if pattern empty
            return -1;
        }

        int textIndex = pattern.length() - 1; // align pattern with text start and get index of the last character

        // while pattern is not out of text bounds
        while (textIndex < text.length()) {
            // try to match pattern with current part of the text starting from last character
            int i = pattern.length() - 1;
            while (i >= 0) {
                comparisons++;
                char patternChar = pattern.charAt(i);
                char textChar = text.charAt((textIndex + i) - (pattern.length() - 1));
                if (!charEquals(patternChar, textChar, caseSensitive)) { // bad character, shift pattern
                    textIndex += getShiftValue(text.charAt(textIndex));
                    break;
                }
                i--;
            }

            // check for full match
            if (i == -1) {
                return textIndex - pattern.length() + 1;
            }
        }

        // text exhausted, return failure
        return -1;
    }

    /**
     * Compares the argument characters
     *
     * @param c1 first character
     * @param c2 second character
     * @param caseSensitive boolean determining case sensitivity of comparison
     * @return truth value of the equality comparison
     */
    private static boolean charEquals(char c1, char c2, boolean caseSensitive) {
        if (caseSensitive) {
            return c1 == c2;
        }
        return Character.toLowerCase(c1) == Character.toLowerCase(c2);
    }

    /**
     * Builds the bad symbol table required to run the algorithm. The method
     * starts from the second to last character of the pattern and moves to the
     * left. When it meets a new character, it is by definition its rightmost
     * occurrence and therefore puts the distance from the current index to the
     * index of the last character into the table. If the character is already
     * in the table, then it is not a rightmost occurrence, so it continues.
     *
     * @param pattern basis for the bad symbol table
     * @return the bad symbol table
     */
    private static HashMap<Character, Integer> calcShiftValues(String pattern) {
        patternLength = pattern.length();
        HashMap<Character, Integer> table = new HashMap<>();

        for (int i = pattern.length() - 2; i >= 0; i--) { // length - 2 is the index of the second to last character
            char c = pattern.charAt(i);
            int finalI = i;
            table.computeIfAbsent(c, k -> pattern.length() - 1 - finalI);
        }

        return table;
    }

    /**
     * Helper function that uses the bad symbol shift table to return the
     * appropriate shift value for a given character
     *
     * @param c character
     * @return shift value that corresponds to the character argument
     */
    private static Integer getShiftValue(char c) {
        if (shiftValues.get(c) != null) {
            return shiftValues.get(c);
        } else {
            return patternLength;
        }
    }
}

package com.thealgorithms.strings;

import java.util.HashSet;
import java.util.Set;

/**
 * An isogram (also called heterogram or nonpattern word) is a word in which no
 * letter of the word occurs more than once. Each character appears exactly
 * once.
 *
 * For example, the word "uncopyrightable" is the longest common English isogram
 * with 15 unique letters. Other examples include "dermatoglyphics" (15
 * letters),
 * "background" (10 letters), "python" (6 letters), and "keyboard" (8 letters).
 * But words like "hello" and "programming" are not isograms because some
 * letters
 * appear multiple times ('l' appears twice in "hello", while 'r', 'm', 'g'
 * repeat
 * in "programming").
 *
 * Isograms are particularly valuable in creating substitution ciphers and are
 * studied in recreational linguistics. A perfect pangram, which uses all 26
 * letters
 * of the alphabet exactly once, is a special type of isogram.
 *
 * Reference from https://en.wikipedia.org/wiki/Heterogram_(literature)#Isograms
 */
public final class Isogram {
    /**
     * Private constructor to prevent instantiation of utility class.
     */
    private Isogram() {
    }

    /**
     * Checks if a string is an isogram using boolean array approach.
     *
     * Time Complexity: O(n)
     * Space Complexity: O(1)
     *
     * @param str the input string
     * @return true if the string is an isogram, false otherwise
     * @throws IllegalArgumentException if the string contains non-alphabetic
     *                                  characters
     */
    public static boolean isAlphabeticIsogram(String str) {
        if (str == null || str.isEmpty()) {
            return true;
        }

        str = str.toLowerCase();

        for (int i = 0; i < str.length(); i++) {
            char ch = str.charAt(i);
            if (ch < 'a' || ch > 'z') {
                throw new IllegalArgumentException("Input contains non-alphabetic character: '" + ch + "'");
            }
        }

        boolean[] seenChars = new boolean[26];
        for (int i = 0; i < str.length(); i++) {
            char ch = str.charAt(i);
            int index = ch - 'a';
            if (seenChars[index]) {
                return false;
            }
            seenChars[index] = true;
        }
        return true;
    }

    /**
     * Checks if a string is an isogram using length comparison approach.
     * Time Complexity: O(n)
     * Space Complexity: O(k) where k is the number of unique characters
     *
     * @param str the input string
     * @return true if the string is an isogram, false otherwise
     */
    public static boolean isFullIsogram(String str) {
        if (str == null || str.isEmpty()) {
            return true;
        }
        str = str.toLowerCase();

        Set<Character> uniqueChars = new HashSet<>();
        for (char ch : str.toCharArray()) {
            uniqueChars.add(ch);
        }
        return uniqueChars.size() == str.length();
    }
}

package com.thealgorithms.strings;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/**
 * Utility class to check if two strings are isomorphic.
 *
 * <p>
 * Two strings {@code s} and {@code t} are isomorphic if the characters in {@code s}
 * can be replaced to get {@code t}, while preserving the order of characters.
 * Each character must map to exactly one character, and no two characters can map to the same character.
 * </p>
 *
 * @see <a href="https://en.wikipedia.org/wiki/Isomorphism_(computer_science)">Isomorphic Strings</a>
 */
public final class Isomorphic {

    private Isomorphic() {
    }

    /**
     * Checks if two strings are isomorphic.
     *
     * @param s the first input string
     * @param t the second input string
     * @return {@code true} if {@code s} and {@code t} are isomorphic; {@code false} otherwise
     */
    public static boolean areIsomorphic(String s, String t) {
        if (s.length() != t.length()) {
            return false;
        }

        Map<Character, Character> map = new HashMap<>();
        Set<Character> usedCharacters = new HashSet<>();

        for (int i = 0; i < s.length(); i++) {
            char sourceChar = s.charAt(i);
            char targetChar = t.charAt(i);

            if (map.containsKey(sourceChar)) {
                if (map.get(sourceChar) != targetChar) {
                    return false;
                }
            } else {
                if (usedCharacters.contains(targetChar)) {
                    return false;
                }
                map.put(sourceChar, targetChar);
                usedCharacters.add(targetChar);
            }
        }

        return true;
    }
}

package com.thealgorithms.strings;

import java.util.ArrayList;
import java.util.List;

/**
 * Implementation of Knuth–Morris–Pratt algorithm Usage: see the main function
 * for an example
 */
public final class KMP {
    private KMP() {
    }

    /**
     * find the starting index in string haystack[] that matches the search word P[]
     *
     * @param haystack The text to be searched
     * @param needle   The pattern to be searched for
     * @return A list of starting indices where the pattern is found
     */
    public static List<Integer> kmpMatcher(final String haystack, final String needle) {
        List<Integer> occurrences = new ArrayList<>();
        if (haystack == null || needle == null || needle.isEmpty()) {
            return occurrences;
        }

        final int m = haystack.length();
        final int n = needle.length();
        final int[] pi = computePrefixFunction(needle);
        int q = 0;
        for (int i = 0; i < m; i++) {
            while (q > 0 && haystack.charAt(i) != needle.charAt(q)) {
                q = pi[q - 1];
            }

            if (haystack.charAt(i) == needle.charAt(q)) {
                q++;
            }

            if (q == n) {
                occurrences.add(i + 1 - n);
                q = pi[q - 1];
            }
        }
        return occurrences;
    }

    // return the prefix function
    private static int[] computePrefixFunction(final String p) {
        final int n = p.length();
        final int[] pi = new int[n];
        pi[0] = 0;
        int q = 0;
        for (int i = 1; i < n; i++) {
            while (q > 0 && p.charAt(q) != p.charAt(i)) {
                q = pi[q - 1];
            }

            if (p.charAt(q) == p.charAt(i)) {
                q++;
            }

            pi[i] = q;
        }
        return pi;
    }
}

package com.thealgorithms.strings;

/**
 * Kasai's Algorithm for constructing the Longest Common Prefix (LCP) array.
 *
 * <p>
 * The LCP array stores the lengths of the longest common prefixes between
 * lexicographically adjacent suffixes of a string. Kasai's algorithm computes
 * this array in O(N) time given the string and its suffix array.
 * </p>
 *
 * @see <a href="https://en.wikipedia.org/wiki/LCP_array">LCP array - Wikipedia</a>
 */
public final class KasaiAlgorithm {

    private KasaiAlgorithm() {
    }

    /**
     * Computes the LCP array using Kasai's algorithm.
     *
     * @param text      the original string
     * @param suffixArr the suffix array of the string
     * @return the LCP array of length N, where LCP[i] is the length of the longest
     *         common prefix of the suffixes indexed by suffixArr[i] and suffixArr[i+1].
     *         The last element LCP[N-1] is always 0.
     * @throws IllegalArgumentException if text or suffixArr is null, or their lengths differ
     */
    public static int[] kasai(String text, int[] suffixArr) {
        if (text == null || suffixArr == null) {
            throw new IllegalArgumentException("Text and suffix array must not be null.");
        }
        int n = text.length();
        if (suffixArr.length != n) {
            throw new IllegalArgumentException("Suffix array length must match text length.");
        }
        if (n == 0) {
            return new int[0];
        }

        // Compute the inverse suffix array
        // invSuff[i] stores the index of the suffix text.substring(i) in the suffix array
        int[] invSuff = new int[n];
        for (int i = 0; i < n; i++) {
            if (suffixArr[i] < 0 || suffixArr[i] >= n) {
                throw new IllegalArgumentException("Suffix array contains out-of-bounds index.");
            }
            invSuff[suffixArr[i]] = i;
        }

        int[] lcp = new int[n];
        int k = 0; // Length of the longest common prefix

        for (int i = 0; i < n; i++) {
            // Suffix at index i has not a next suffix in suffix array
            int rank = invSuff[i];
            if (rank == n - 1) {
                k = 0;
                continue;
            }

            int nextSuffixIndex = suffixArr[rank + 1];

            // Directly match characters to find LCP
            while (i + k < n && nextSuffixIndex + k < n && text.charAt(i + k) == text.charAt(nextSuffixIndex + k)) {
                k++;
            }

            lcp[rank] = k;

            // Delete the starting character from the string
            if (k > 0) {
                k--;
            }
        }

        return lcp;
    }
}

package com.thealgorithms.strings;

/**
 * The {@code LengthOfLastWord} class provides a utility method to determine
 * the length of the last word in a given string.
 *
 * <p>A "word" is defined as a maximal substring consisting of non-space
 * characters only. Trailing spaces at the end of the string are ignored.
 *
 * <p><strong>Example:</strong>
 * <pre>{@code
 * LengthOfLastWord obj = new LengthOfLastWord();
 * System.out.println(obj.lengthOfLastWord("Hello World"));  // Output: 5
 * System.out.println(obj.lengthOfLastWord("  fly me   to   the moon  "));  // Output: 4
 * System.out.println(obj.lengthOfLastWord("luffy is still joyboy"));  // Output: 6
 * }</pre>
 *
 * <p>This implementation runs in O(n) time complexity, where n is the length
 * of the input string, and uses O(1) additional space.
 */
public class LengthOfLastWord {

    /**
     * Returns the length of the last word in the specified string.
     *
     * <p>The method iterates from the end of the string, skipping trailing
     * spaces first, and then counts the number of consecutive non-space characters
     * characters until another space (or the beginning of the string) is reached.
     *
     * @param s the input string to analyze
     * @return the length of the last word in {@code s}; returns 0 if there is no word
     * @throws NullPointerException if {@code s} is {@code null}
     */
    public int lengthOfLastWord(String s) {
        int sizeOfString = s.length() - 1;
        int lastWordLength = 0;

        // Skip trailing spaces from the end of the string
        while (sizeOfString >= 0 && s.charAt(sizeOfString) == ' ') {
            sizeOfString--;
        }

        // Count the characters of the last word
        while (sizeOfString >= 0 && s.charAt(sizeOfString) != ' ') {
            lastWordLength++;
            sizeOfString--;
        }

        return lastWordLength;
    }
}

package com.thealgorithms.strings;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public final class LetterCombinationsOfPhoneNumber {

    private static final char EMPTY = '\0';

    // Mapping of numbers to corresponding letters on a phone keypad
    private static final String[] KEYPAD = new String[] {" ", String.valueOf(EMPTY), "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};

    private LetterCombinationsOfPhoneNumber() {
    }

    /**
     * Generates a list of all possible letter combinations that the provided
     * array of numbers could represent on a phone keypad.
     *
     * @param numbers an array of integers representing the phone numbers
     * @return a list of possible letter combinations
     */
    public static List<String> getCombinations(int[] numbers) {
        if (numbers == null) {
            return List.of("");
        }
        return generateCombinations(numbers, 0, new StringBuilder());
    }

    /**
     * Recursive method to generate combinations of letters from the phone keypad.
     *
     * @param numbers the input array of phone numbers
     * @param index   the current index in the numbers array being processed
     * @param current a StringBuilder holding the current combination of letters
     * @return a list of letter combinations formed from the given numbers
     */
    private static List<String> generateCombinations(int[] numbers, int index, StringBuilder current) {
        // Base case: if we've processed all numbers, return the current combination
        if (index == numbers.length) {
            return new ArrayList<>(Collections.singletonList(current.toString()));
        }

        final var number = numbers[index];
        if (number < 0 || number > 9) {
            throw new IllegalArgumentException("Input numbers must in the range [0, 9]");
        }

        List<String> combinations = new ArrayList<>();

        // Iterate over each letter and recurse to generate further combinations
        for (char letter : KEYPAD[number].toCharArray()) {
            if (letter != EMPTY) {
                current.append(letter);
            }
            combinations.addAll(generateCombinations(numbers, index + 1, current));
            if (letter != EMPTY) {
                current.deleteCharAt(current.length() - 1); // Backtrack by removing the last appended letter
            }
        }

        return combinations;
    }
}

package com.thealgorithms.strings;

import java.util.Arrays;

/**
 * Utility class for string operations.
 * <p>
 * This class provides a method to find the longest common prefix (LCP)
 * among an array of strings.
 * </p>
 *
 * @see <a href="https://en.wikipedia.org/wiki/Longest_common_prefix">Longest Common Prefix - Wikipedia</a>
 */
public final class LongestCommonPrefix {

    private LongestCommonPrefix() {
    }

    /**
     * Finds the longest common prefix among a list of strings using lexicographical sorting.
     * The prefix is common to the first and last elements after sorting the array.
     *
     * @param strs array of input strings
     * @return the longest common prefix, or empty string if none exists
     */
    public static String longestCommonPrefix(String[] strs) {
        if (strs == null || strs.length == 0) {
            return "";
        }

        Arrays.sort(strs);
        String first = strs[0];
        String last = strs[strs.length - 1];

        int index = 0;
        while (index < first.length() && index < last.length() && first.charAt(index) == last.charAt(index)) {
            index++;
        }

        return first.substring(0, index);
    }
}

package com.thealgorithms.strings;

/**
 * Longest Common Substring finds the longest string that is a
 * contiguous substring of two input strings.
 * Example: "abcdef" and "zcdemf" -> "cde"
 *
 * @see <a href="https://en.wikipedia.org/wiki/Longest_common_substring">
 *     Wikipedia: Longest Common Substring</a>
 *
 * author: Vraj Prajapati @Rosander0
 */
public final class LongestCommonSubstring {

    private LongestCommonSubstring() {
        // Utility class
    }

    /**
     * Finds the longest common substring of two strings.
     *
     * @param a First input string
     * @param b Second input string
     * @return The longest common substring, or empty string if none exists.
     *     If multiple substrings share the maximum length, the first one found is returned.
     */
    public static String longestCommonSubstring(final String a, final String b) {
        if (a == null || b == null || a.isEmpty() || b.isEmpty()) {
            return "";
        }

        int[] dp = new int[b.length() + 1];
        int maxLength = 0;
        int endIndex = 0;

        for (int i = 1; i <= a.length(); i++) {
            for (int j = b.length(); j >= 1; j--) {
                if (a.charAt(i - 1) == b.charAt(j - 1)) {
                    dp[j] = dp[j - 1] + 1;
                    if (dp[j] > maxLength) {
                        maxLength = dp[j];
                        endIndex = i;
                    }
                } else {
                    dp[j] = 0;
                }
            }
        }

        if (maxLength == 0) {
            return "";
        }
        return a.substring(endIndex - maxLength, endIndex);
    }
}

package com.thealgorithms.strings;

import java.util.HashMap;
import java.util.Map;

/**
 * Class for finding the length of the longest substring without repeating characters.
 */
final class LongestNonRepetitiveSubstring {
    private LongestNonRepetitiveSubstring() {
    }

    /**
     * Finds the length of the longest substring without repeating characters.
     *
     * Uses the sliding window technique with a HashMap to track
     * the last seen index of each character.
     *
     * Time Complexity: O(n), where n is the length of the input string.
     * Space Complexity: O(min(n, m)), where m is the size of the character set.
     *
     * @param s the input string
     * @return the length of the longest non-repetitive substring
     */
    public static int lengthOfLongestSubstring(String s) {
        int maxLength = 0;
        int start = 0;
        Map<Character, Integer> charIndexMap = new HashMap<>();

        for (int i = 0; i < s.length(); i++) {
            char currentChar = s.charAt(i);

            // If the character is already in the map and its index is within the current window
            if (charIndexMap.containsKey(currentChar) && charIndexMap.get(currentChar) >= start) {
                // Move the start to the position right after the last occurrence of the current character
                start = charIndexMap.get(currentChar) + 1;
            }

            // Update the last seen index of the current character
            charIndexMap.put(currentChar, i);

            // Calculate the maximum length of the substring without repeating characters
            maxLength = Math.max(maxLength, i - start + 1);
        }

        return maxLength;
    }
}

package com.thealgorithms.strings;

/**
 * Finds the longest substring that occurs at least twice in a given string.
 *
 * <p>Uses the suffix array (via {@link SuffixArray}) and Kasai's algorithm
 * to build the LCP (Longest Common Prefix) array, then returns the substring
 * corresponding to the maximum LCP value.</p>
 *
 * <p>Time complexity: O(n log² n) for suffix array construction + O(n) for LCP.</p>
 *
 * @see <a href="https://en.wikipedia.org/wiki/Longest_repeated_substring_problem">Longest repeated substring problem</a>
 * @see SuffixArray
 */
public final class LongestRepeatedSubstring {

    private LongestRepeatedSubstring() {
    }

    /**
     * Returns the longest substring that appears at least twice in the given text.
     *
     * @param text the input string
     * @return the longest repeated substring, or an empty string if none exists
     */
    public static String longestRepeatedSubstring(String text) {
        if (text == null || text.length() <= 1) {
            return "";
        }

        final int[] suffixArray = SuffixArray.buildSuffixArray(text);
        final int[] lcp = buildLcpArray(text, suffixArray);

        int maxLen = 0;
        int maxIdx = 0;
        for (int i = 0; i < lcp.length; i++) {
            if (lcp[i] > maxLen) {
                maxLen = lcp[i];
                maxIdx = suffixArray[i + 1];
            }
        }

        return text.substring(maxIdx, maxIdx + maxLen);
    }

    /**
     * Builds the LCP (Longest Common Prefix) array using Kasai's algorithm.
     *
     * <p>LCP[i] is the length of the longest common prefix between the suffixes
     * at positions suffixArray[i] and suffixArray[i+1] in sorted order.</p>
     *
     * @param text the original string
     * @param suffixArray the suffix array of the string
     * @return the LCP array of length n-1
     */
    static int[] buildLcpArray(String text, int[] suffixArray) {
        final int n = text.length();
        final int[] rank = new int[n];
        final int[] lcp = new int[n - 1];

        for (int i = 0; i < n; i++) {
            rank[suffixArray[i]] = i;
        }

        int k = 0;
        for (int i = 0; i < n; i++) {
            if (rank[i] == n - 1) {
                k = 0;
                continue;
            }
            final int j = suffixArray[rank[i] + 1];
            while (i + k < n && j + k < n && text.charAt(i + k) == text.charAt(j + k)) {
                k++;
            }
            lcp[rank[i]] = k;
            if (k > 0) {
                k--;
            }
        }

        return lcp;
    }
}

