package com.thealgorithms.strings;

/**
 * Wikipedia: https://en.wikipedia.org/wiki/Longest_palindromic_substring#Manacher's_algorithm
 */
public final class Manacher {

    private Manacher() {
    }

    /**
     * Finds the longest palindromic substring using Manacher's Algorithm
     *
     * @param s The input string
     * @return The longest palindromic substring in {@code s}
     */
    public static String longestPalindrome(String s) {
        final String processedString = preprocess(s);
        int[] palindromeLengths = new int[processedString.length()];
        int center = 0;
        int rightBoundary = 0;
        int maxLen = 0;
        int centerIndex = 0;

        for (int i = 1; i < processedString.length() - 1; i++) {
            int mirror = 2 * center - i;

            if (i < rightBoundary) {
                palindromeLengths[i] = Math.min(rightBoundary - i, palindromeLengths[mirror]);
            }

            while (processedString.charAt(i + 1 + palindromeLengths[i]) == processedString.charAt(i - 1 - palindromeLengths[i])) {
                palindromeLengths[i]++;
            }

            if (i + palindromeLengths[i] > rightBoundary) {
                center = i;
                rightBoundary = i + palindromeLengths[i];
            }

            if (palindromeLengths[i] > maxLen) {
                maxLen = palindromeLengths[i];
                centerIndex = i;
            }
        }

        final int start = (centerIndex - maxLen) / 2;
        return s.substring(start, start + maxLen);
    }

    /**
     * Preprocesses the input string by inserting a special character ('#') between each character
     * and adding '^' at the start and '$' at the end to avoid boundary conditions.
     *
     * @param s The original string
     * @return The preprocessed string with additional characters
     */
    private static String preprocess(String s) {
        if (s.isEmpty()) {
            return "^$";
        }
        StringBuilder sb = new StringBuilder("^");
        for (char c : s.toCharArray()) {
            sb.append('#').append(c);
        }
        sb.append("#$");
        return sb.toString();
    }
}

package com.thealgorithms.strings;

/**
 * Moves all '#' characters to the end of the given string while preserving
 * the order of the other characters.
 *
 * Example:
 * Input  : "h#e#l#llo"
 * Output : "helllo###"
 *
 * The algorithm works by iterating through the string and collecting
 * all non-# characters first, then filling the remaining positions
 * with '#'.
 *
 * Time Complexity: O(n)
 * Space Complexity: O(n)
 *
 * @see <a href="https://www.geeksforgeeks.org/move-special-char-end-string-maintain-order-alphabets/">Move all special characters to end - GeeksForGeeks</a>
 */
public final class MoveHashToEnd {

    /**
     * Private constructor to prevent instantiation of utility class.
     */
    private MoveHashToEnd() {
    }

    /**
     * Moves all '#' characters in the input string to the end.
     *
     * @param str the input string containing characters and '#'
     * @return a new string with all '#' characters moved to the end
     */
    public static String moveHashToEnd(String str) {
        if (str == null || str.isEmpty()) {
            return str;
        }

        char[] arr = str.toCharArray();
        int insertPos = 0;

        // Place all non-# characters at the beginning
        for (char ch : arr) {
            if (ch != '#') {
                arr[insertPos++] = ch;
            }
        }

        // Fill remaining positions with '#'
        while (insertPos < arr.length) {
            arr[insertPos++] = '#';
        }

        return new String(arr);
    }
}

