import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

public class BloomFilterTest {
    private BloomFilter<String> bloomFilter;

    @BeforeEach
    void setUp() {
        bloomFilter = new BloomFilter<>(3, 100);
    }

    @Test
    public void testIntegerContains() {
        BloomFilter<Integer> bloomFilter = new BloomFilter<>(3, 10);
        bloomFilter.insert(3);
        bloomFilter.insert(17);

        Assertions.assertTrue(bloomFilter.contains(3));
        Assertions.assertTrue(bloomFilter.contains(17));
    }

    @Test
    public void testStringContains() {
        bloomFilter.insert("omar");
        bloomFilter.insert("mahamid");

        Assertions.assertTrue(bloomFilter.contains("omar"));
        Assertions.assertTrue(bloomFilter.contains("mahamid"));
    }

    @Test
    void testInsertAndContains() {
        bloomFilter.insert("hello");
        bloomFilter.insert("world");

        Assertions.assertTrue(bloomFilter.contains("hello"));
        Assertions.assertTrue(bloomFilter.contains("world"));
        Assertions.assertFalse(bloomFilter.contains("java"));
    }

    @Test
    void testFalsePositive() {
        bloomFilter.insert("apple");
        bloomFilter.insert("banana");

        Assertions.assertFalse(bloomFilter.contains("grape"));
        Assertions.assertFalse(bloomFilter.contains("orange"));
    }

    @Test
    void testMultipleInsertions() {
        for (int i = 0; i < 100; i++) {
            bloomFilter.insert("key" + i);
        }

        for (int i = 0; i < 100; i++) {
            Assertions.assertTrue(bloomFilter.contains("key" + i));
        }

        Assertions.assertFalse(bloomFilter.contains("key" + 200));
    }

    @Test
    void testEmptyFilterContains() {
        Assertions.assertFalse(bloomFilter.contains("notInserted"), "Filter should not contain any elements when empty");
        Assertions.assertFalse(bloomFilter.contains(null), "Filter should not contain null elements");
    }

    @Test
    void testDifferentTypes() {
        BloomFilter<Object> filter = new BloomFilter<>(3, 100);
        filter.insert("string");
        filter.insert(123);
        filter.insert(45.67);

        Assertions.assertTrue(filter.contains("string"), "Filter should contain the string 'string'");
        Assertions.assertTrue(filter.contains(123), "Filter should contain the integer 123");
        Assertions.assertTrue(filter.contains(45.67), "Filter should contain the double 45.67");
        Assertions.assertFalse(filter.contains("missing"), "Filter should not contain elements that were not inserted");
    }

    @Test
    void testFalsePositiveAfterInsertions() {
        bloomFilter.insert("cat");
        bloomFilter.insert("dog");
        bloomFilter.insert("fish");

        // Checking for an element that was not added
        Assertions.assertFalse(bloomFilter.contains("bird"), "Filter should not contain 'bird' which was never inserted");

        // To increase chances of false positives, we can add more items
        for (int i = 0; i < 100; i++) {
            bloomFilter.insert("item" + i);
        }

        Assertions.assertFalse(bloomFilter.contains("nonexistent"), "Filter should not contain 'nonexistent' which was never inserted");
    }

    @Test
    void testBoundaryConditions() {
        BloomFilter<String> filter = new BloomFilter<>(3, 10);
        filter.insert("a");
        filter.insert("b");
        filter.insert("c");
        filter.insert("d");

        Assertions.assertTrue(filter.contains("a"), "Filter should contain 'a'");
        Assertions.assertTrue(filter.contains("b"), "Filter should contain 'b'");
        Assertions.assertTrue(filter.contains("c"), "Filter should contain 'c'");
        Assertions.assertTrue(filter.contains("d"), "Filter should contain 'd'");
        Assertions.assertFalse(filter.contains("e"), "Filter should not contain 'e' which was not inserted");
    }

    @Test
    void testLongDataType() {
        BloomFilter<Long> filter = new BloomFilter<>(5, 1000);
        Long[] values = {Long.MIN_VALUE, Long.MAX_VALUE};

        for (Long value : values) {
            filter.insert(value);
        }

        for (Long value : values) {
            Assertions.assertTrue(filter.contains(value), "Filter should contain " + value);
        }
    }

    @Test
    void testFloatDataType() {
        BloomFilter<Float> filter = new BloomFilter<>(3, 200);
        Float[] values = {1.5f, -3.7f, 0.0f, Float.MAX_VALUE, Float.MIN_VALUE};

        for (Float value : values) {
            filter.insert(value);
        }

        for (Float value : values) {
            Assertions.assertTrue(filter.contains(value), "Filter should contain " + value);
        }

        Assertions.assertFalse(filter.contains(88.88f), "Filter should not contain uninserted value");
    }

    @Test
    void testBooleanDataType() {
        BloomFilter<Boolean> filter = new BloomFilter<>(2, 50);
        filter.insert(Boolean.TRUE);
        filter.insert(Boolean.FALSE);

        Assertions.assertTrue(filter.contains(Boolean.TRUE), "Filter should contain true");
        Assertions.assertTrue(filter.contains(Boolean.FALSE), "Filter should contain false");
    }

    @Test
    void testListDataType() {
        BloomFilter<List<String>> filter = new BloomFilter<>(4, 200);
        List<String> list1 = Arrays.asList("apple", "banana");
        List<String> list2 = Arrays.asList("cat", "dog");
        List<String> emptyList = new ArrayList<>();

        filter.insert(list1);
        filter.insert(list2);
        filter.insert(emptyList);

        Assertions.assertTrue(filter.contains(list1), "Filter should contain list1");
        Assertions.assertTrue(filter.contains(list2), "Filter should contain list2");
        Assertions.assertTrue(filter.contains(emptyList), "Filter should contain empty list");
        Assertions.assertFalse(filter.contains(Arrays.asList("elephant", "tiger")), "Filter should not contain uninserted list");
    }

    @Test
    void testMapDataType() {
        BloomFilter<Map<String, Integer>> filter = new BloomFilter<>(3, 150);
        Map<String, Integer> map1 = new HashMap<>();
        map1.put("key1", 1);
        map1.put("key2", 2);

        Map<String, Integer> map2 = new HashMap<>();
        map2.put("key3", 3);

        Map<String, Integer> emptyMap = new HashMap<>();

        filter.insert(map1);
        filter.insert(map2);
        filter.insert(emptyMap);

        Assertions.assertTrue(filter.contains(map1), "Filter should contain map1");
        Assertions.assertTrue(filter.contains(map2), "Filter should contain map2");
        Assertions.assertTrue(filter.contains(emptyMap), "Filter should contain empty map");
    }

    @Test
    void testSetDataType() {
        BloomFilter<Set<Integer>> filter = new BloomFilter<>(3, 100);
        Set<Integer> set1 = new HashSet<>(Arrays.asList(1, 2, 3));
        Set<Integer> set2 = new HashSet<>(Arrays.asList(4, 5));
        Set<Integer> emptySet = new HashSet<>();

        filter.insert(set1);
        filter.insert(set2);
        filter.insert(emptySet);

        Assertions.assertTrue(filter.contains(set1), "Filter should contain set1");
        Assertions.assertTrue(filter.contains(set2), "Filter should contain set2");
        Assertions.assertTrue(filter.contains(emptySet), "Filter should contain empty set");
        Assertions.assertFalse(filter.contains(new HashSet<>(Arrays.asList(6, 7, 8))), "Filter should not contain uninserted set");
    }

    @Test
    void testArrayDataType() {
        BloomFilter<int[]> filter = new BloomFilter<>(3, 100);
        int[] array1 = {1, 2, 3};
        int[] array2 = {4, 5};
        int[] emptyArray = {};

        filter.insert(array1);
        filter.insert(array2);
        filter.insert(emptyArray);

        Assertions.assertTrue(filter.contains(array1), "Filter should contain array1");
        Assertions.assertTrue(filter.contains(array2), "Filter should contain array2");
        Assertions.assertTrue(filter.contains(emptyArray), "Filter should contain empty array");
        Assertions.assertFalse(filter.contains(new int[] {6, 7, 8}), "Filter should not contain different array");
    }

    @Test
    void testSpecialFloatingPointValues() {
        BloomFilter<Double> filter = new BloomFilter<>(3, 100);
        Double[] specialValues = {Double.NaN, Double.POSITIVE_INFINITY, Double.NEGATIVE_INFINITY, -0.0, 0.0};

        for (Double value : specialValues) {
            filter.insert(value);
        }

        for (Double value : specialValues) {
            Assertions.assertTrue(filter.contains(value), "Filter should contain " + value);
        }
    }

    @Test
    void testVerySmallBloomFilter() {
        BloomFilter<String> smallFilter = new BloomFilter<>(1, 5);
        smallFilter.insert("test1");
        smallFilter.insert("test2");

        Assertions.assertTrue(smallFilter.contains("test1"));
        Assertions.assertTrue(smallFilter.contains("test2"));
    }
}

package com.thealgorithms.datastructures.buffers;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

class CircularBufferTest {

    @Test
    void testInitialization() {
        CircularBuffer<Integer> buffer = new CircularBuffer<>(5);
        assertTrue(buffer.isEmpty());
        assertEquals(Boolean.FALSE, buffer.isFull());
    }

    @Test
    void testPutAndGet() {
        CircularBuffer<String> buffer = new CircularBuffer<>(3);

        assertTrue(buffer.put("A"));
        assertEquals(Boolean.FALSE, buffer.isEmpty());
        assertEquals(Boolean.FALSE, buffer.isFull());

        buffer.put("B");
        buffer.put("C");
        assertTrue(buffer.isFull());

        assertEquals("A", buffer.get());
        assertEquals("B", buffer.get());
        assertEquals("C", buffer.get());
        assertTrue(buffer.isEmpty());
    }

    @Test
    void testOverwrite() {
        CircularBuffer<Integer> buffer = new CircularBuffer<>(3);

        buffer.put(1);
        buffer.put(2);
        buffer.put(3);
        assertEquals(Boolean.FALSE, buffer.put(4)); // This should overwrite 1

        assertEquals(2, buffer.get());
        assertEquals(3, buffer.get());
        assertEquals(4, buffer.get());
        assertNull(buffer.get());
    }

    @Test
    void testEmptyBuffer() {
        CircularBuffer<Double> buffer = new CircularBuffer<>(2);
        assertNull(buffer.get());
    }

    @Test
    void testFullBuffer() {
        CircularBuffer<Character> buffer = new CircularBuffer<>(2);
        buffer.put('A');
        buffer.put('B');
        assertTrue(buffer.isFull());
        assertEquals(Boolean.FALSE, buffer.put('C')); // This should overwrite 'A'
        assertEquals('B', buffer.get());
        assertEquals('C', buffer.get());
    }

    @Test
    void testIllegalArguments() {
        org.junit.jupiter.api.Assertions.assertThrows(IllegalArgumentException.class, () -> new CircularBuffer<>(0));
        org.junit.jupiter.api.Assertions.assertThrows(IllegalArgumentException.class, () -> new CircularBuffer<>(-1));

        CircularBuffer<String> buffer = new CircularBuffer<>(1);
        org.junit.jupiter.api.Assertions.assertThrows(IllegalArgumentException.class, () -> buffer.put(null));
    }

    @Test
    void testLargeBuffer() {
        CircularBuffer<Integer> buffer = new CircularBuffer<>(1000);
        for (int i = 0; i < 1000; i++) {
            buffer.put(i);
        }
        assertTrue(buffer.isFull());
        buffer.put(1000); // This should overwrite 0
        assertEquals(1, buffer.get());
    }

    @Test
    void testPutAfterGet() {
        CircularBuffer<Integer> buffer = new CircularBuffer<>(2);
        buffer.put(10);
        buffer.put(20);
        assertEquals(10, buffer.get());
        buffer.put(30);
        assertEquals(20, buffer.get());
        assertEquals(30, buffer.get());
        assertNull(buffer.get());
    }

    @Test
    void testMultipleWrapArounds() {
        CircularBuffer<Integer> buffer = new CircularBuffer<>(3);
        for (int i = 1; i <= 6; i++) {
            buffer.put(i);
            buffer.get(); // add and immediately remove
        }
        assertTrue(buffer.isEmpty());
        assertNull(buffer.get());
    }

    @Test
    void testOverwriteMultipleTimes() {
        CircularBuffer<String> buffer = new CircularBuffer<>(2);
        buffer.put("X");
        buffer.put("Y");
        buffer.put("Z"); // overwrites "X"
        buffer.put("W"); // overwrites "Y"
        assertEquals("Z", buffer.get());
        assertEquals("W", buffer.get());
        assertNull(buffer.get());
    }

    @Test
    void testIsEmptyAndIsFullTransitions() {
        CircularBuffer<Integer> buffer = new CircularBuffer<>(2);
        assertTrue(buffer.isEmpty());
        org.junit.jupiter.api.Assertions.assertFalse(buffer.isFull());

        buffer.put(1);
        org.junit.jupiter.api.Assertions.assertFalse(buffer.isEmpty());
        org.junit.jupiter.api.Assertions.assertFalse(buffer.isFull());

        buffer.put(2);
        assertTrue(buffer.isFull());

        buffer.get();
        org.junit.jupiter.api.Assertions.assertFalse(buffer.isFull());

        buffer.get();
        assertTrue(buffer.isEmpty());
    }

    @Test
    void testInterleavedPutAndGet() {
        CircularBuffer<String> buffer = new CircularBuffer<>(3);
        buffer.put("A");
        buffer.put("B");
        assertEquals("A", buffer.get());
        buffer.put("C");
        assertEquals("B", buffer.get());
        assertEquals("C", buffer.get());
        assertNull(buffer.get());
    }

    @Test
    void testRepeatedNullInsertionThrows() {
        CircularBuffer<Object> buffer = new CircularBuffer<>(5);
        for (int i = 0; i < 3; i++) {
            int finalI = i;
            org.junit.jupiter.api.Assertions.assertThrows(IllegalArgumentException.class, () -> buffer.put(null), "Iteration: " + finalI);
        }
    }
    @Test
    void testFillThenEmptyThenReuseBuffer() {
        CircularBuffer<Integer> buffer = new CircularBuffer<>(3);

        buffer.put(1);
        buffer.put(2);
        buffer.put(3);
        assertTrue(buffer.isFull());

        assertEquals(1, buffer.get());
        assertEquals(2, buffer.get());
        assertEquals(3, buffer.get());

        assertTrue(buffer.isEmpty());

        buffer.put(4);
        buffer.put(5);
        assertEquals(4, buffer.get());
        assertEquals(5, buffer.get());
        assertTrue(buffer.isEmpty());
    }

    @Test
    void testPutReturnsTrueOnlyIfPreviouslyEmpty() {
        CircularBuffer<String> buffer = new CircularBuffer<>(2);

        assertTrue(buffer.put("one")); // was empty
        org.junit.jupiter.api.Assertions.assertFalse(buffer.put("two")); // not empty
        org.junit.jupiter.api.Assertions.assertFalse(buffer.put("three")); // overwrite
    }

    @Test
    void testOverwriteAndGetAllElementsCorrectly() {
        CircularBuffer<Integer> buffer = new CircularBuffer<>(3);

        buffer.put(1);
        buffer.put(2);
        buffer.put(3);
        buffer.put(4); // Overwrites 1
        buffer.put(5); // Overwrites 2

        assertEquals(3, buffer.get());
        assertEquals(4, buffer.get());
        assertEquals(5, buffer.get());
        assertNull(buffer.get());
    }

    @Test
    void testBufferWithOneElementCapacity() {
        CircularBuffer<String> buffer = new CircularBuffer<>(1);

        assertTrue(buffer.put("first"));
        assertEquals("first", buffer.get());
        assertNull(buffer.get());

        assertTrue(buffer.put("second"));
        assertEquals("second", buffer.get());
    }

    @Test
    void testPointerWraparoundWithExactMultipleOfCapacity() {
        CircularBuffer<Integer> buffer = new CircularBuffer<>(3);
        for (int i = 0; i < 6; i++) {
            buffer.put(i);
            buffer.get(); // keep buffer size at 0
        }
        assertTrue(buffer.isEmpty());
        assertNull(buffer.get());
    }
}

package com.thealgorithms.datastructures.buffers;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.ConcurrentModificationException;
import java.util.Deque;
import java.util.Iterator;
import java.util.List;
import java.util.NoSuchElementException;
import java.util.Random;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.BinaryOperator;
import java.util.function.Function;
import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

class SlidingWindowAggregatorTest {

    private static final Comparator<Integer> NATURAL = Comparator.naturalOrder();

    private static SlidingWindowAggregator<Integer, Integer> sumWindow(int capacity) {
        return SlidingWindowAggregator.of(capacity, Integer::sum);
    }

    @Nested
    @DisplayName("construction")
    class Construction {

        @ParameterizedTest
        @ValueSource(ints = {0, -1, Integer.MIN_VALUE})
        void rejectsNonPositiveCapacity(int capacity) {
            assertThrows(IllegalArgumentException.class, () -> sumWindow(capacity));
        }

        @Test
        void rejectsNullMapper() {
            assertThrows(NullPointerException.class, () -> new SlidingWindowAggregator<Integer, Integer>(4, null, Integer::sum));
        }

        @Test
        void rejectsNullCombiner() {
            assertThrows(NullPointerException.class, () -> new SlidingWindowAggregator<Integer, Integer>(4, Function.identity(), null));
        }

        @Test
        void startsEmpty() {
            SlidingWindowAggregator<Integer, Integer> window = sumWindow(3);
            assertTrue(window.isEmpty());
            assertFalse(window.isFull());
            assertEquals(0, window.size());
            assertEquals(3, window.capacity());
            assertTrue(window.toList().isEmpty());
            assertEquals("[]", window.toString());
        }
    }

    @Nested
    @DisplayName("empty window")
    class EmptyWindow {

        private final SlidingWindowAggregator<Integer, Integer> window = sumWindow(3);

        @Test
        void aggregateThrows() {
            assertThrows(NoSuchElementException.class, window::aggregate);
        }

        @Test
        void peeksThrow() {
            assertThrows(NoSuchElementException.class, window::peekOldest);
            assertThrows(NoSuchElementException.class, window::peekNewest);
        }

        @Test
        void removeThrows() {
            assertThrows(NoSuchElementException.class, window::removeOldest);
        }

        @Test
        void getThrows() {
            assertThrows(IndexOutOfBoundsException.class, () -> window.get(0));
        }

        @Test
        void iteratorIsExhausted() {
            Iterator<Integer> iterator = window.iterator();
            assertFalse(iterator.hasNext());
            assertThrows(NoSuchElementException.class, iterator::next);
        }
    }

    @Nested
    @DisplayName("aggregation")
    class Aggregation {

        @Test
        void aggregatesWhileFilling() {
            SlidingWindowAggregator<Integer, Integer> window = sumWindow(4);
            window.add(1);
            assertEquals(1, window.aggregate());
            window.add(2);
            assertEquals(3, window.aggregate());
            window.add(3);
            assertEquals(6, window.aggregate());
            window.add(4);
            assertEquals(10, window.aggregate());
            assertTrue(window.isFull());
        }

        @Test
        void slidesOnceFull() {
            SlidingWindowAggregator<Integer, Integer> window = sumWindow(3);
            window.addAll(List.of(1, 2, 3));
            assertEquals(6, window.aggregate());

            assertEquals(1, window.add(4));
            assertEquals(9, window.aggregate());
            assertEquals(List.of(2, 3, 4), window.toList());

            assertEquals(2, window.add(5));
            assertEquals(12, window.aggregate());
        }

        @Test
        void addReturnsNullWhileTheWindowIsNotFull() {
            SlidingWindowAggregator<Integer, Integer> window = sumWindow(2);
            Assertions.assertNull(window.add(1));
            Assertions.assertNull(window.add(2));
            assertEquals(1, window.add(3));
        }

        @Test
        @DisplayName("keeps the maximum of the last three readings")
        void tracksMaximum() {
            SlidingWindowAggregator<Integer, Integer> window = SlidingWindowAggregator.maximum(3, NATURAL);
            List<Integer> observed = new ArrayList<>();
            for (int value : new int[] {1, 3, 2, 5, 0, 0, 0}) {
                window.add(value);
                observed.add(window.aggregate());
            }
            assertEquals(List.of(1, 3, 3, 5, 5, 5, 0), observed);
        }

        @Test
        void tracksMinimum() {
            SlidingWindowAggregator<Integer, Integer> window = SlidingWindowAggregator.minimum(3, NATURAL);
            window.addAll(List.of(5, 4, 6, 7, 8));
            assertEquals(6, window.aggregate());
        }

        @Test
        @DisplayName("combines oldest first, so non-commutative operators work")
        void preservesOrderForNonCommutativeOperators() {
            SlidingWindowAggregator<String, String> window = SlidingWindowAggregator.of(3, (a, b) -> a + b);
            window.addAll(List.of("a", "b", "c", "d", "e"));
            assertEquals("cde", window.aggregate());
            window.removeOldest();
            assertEquals("de", window.aggregate());
        }

        @Test
        void supportsAggregatesOfADifferentType() {
            SlidingWindowAggregator<String, Integer> lengths = new SlidingWindowAggregator<>(3, String::length, Integer::sum);
            lengths.addAll(List.of("a", "bb", "ccc", "dddd"));
            assertEquals(2 + 3 + 4, lengths.aggregate());
        }

        @Test
        void movingAverageIsSumOverSize() {
            SlidingWindowAggregator<Double, Double> window = SlidingWindowAggregator.sumOfDoubles(3);
            window.addAll(List.of(1.0, 2.0, 3.0, 6.0));
            assertEquals(11.0 / 3.0, window.aggregate() / window.size(), 1e-12);
        }

        @Test
        void sumOfLongsFactoryWorks() {
            SlidingWindowAggregator<Long, Long> window = SlidingWindowAggregator.sumOfLongs(2);
            window.addAll(List.of(1L, 2L, 3L));
            assertEquals(5L, window.aggregate());
        }

        @Test
        @DisplayName("the mapper runs exactly once per element")
        void mapperIsCalledOncePerElement() {
            AtomicInteger calls = new AtomicInteger();
            SlidingWindowAggregator<Integer, Integer> window = new SlidingWindowAggregator<>(3, value -> {
                calls.incrementAndGet();
                return value;
            }, Integer::sum);
            for (int i = 0; i < 100; i++) {
                window.add(i);
                window.aggregate();
            }
            assertEquals(100, calls.get());
        }
    }

    @Nested
    @DisplayName("null handling")
    class NullHandling {

        @Test
        void rejectsNullElements() {
            SlidingWindowAggregator<Integer, Integer> window = sumWindow(2);
            assertThrows(NullPointerException.class, () -> window.add(null));
        }

        @Test
        @DisplayName("a null hidden inside a collection is rejected, and the elements before it stay")
        void rejectsNullElementsInsideACollection() {
            SlidingWindowAggregator<Integer, Integer> window = sumWindow(2);
            List<Integer> items = new ArrayList<>();
            items.add(1);
            items.add(null);

            assertThrows(NullPointerException.class, () -> window.addAll(items));
            assertEquals(1, window.size());
            assertEquals(1, window.aggregate());
        }

        @Test
        void rejectsMappersReturningNull() {
            SlidingWindowAggregator<Integer, Integer> window = new SlidingWindowAggregator<>(2, value -> null, Integer::sum);
            assertThrows(NullPointerException.class, () -> window.add(1));
        }

        @Test
        void rejectsCombinersReturningNull() {
            SlidingWindowAggregator<Integer, Integer> window = SlidingWindowAggregator.of(2, (a, b) -> null);
            window.add(1);
            assertThrows(NullPointerException.class, () -> window.add(2));
        }
    }

    @Nested
    @DisplayName("access and iteration")
    class Access {

        @Test
        void indexedAccessStartsAtTheOldestElement() {
            SlidingWindowAggregator<Integer, Integer> window = sumWindow(3);
            window.addAll(List.of(10, 20, 30, 40));
            assertEquals(20, window.get(0));
            assertEquals(30, window.get(1));
            assertEquals(40, window.get(2));
            assertEquals(20, window.peekOldest());
            assertEquals(40, window.peekNewest());
        }

        @ParameterizedTest
        @ValueSource(ints = {-1, 3, 100})
        void rejectsOutOfBoundsIndices(int index) {
            SlidingWindowAggregator<Integer, Integer> window = sumWindow(5);
            window.addAll(List.of(1, 2, 3));
            assertThrows(IndexOutOfBoundsException.class, () -> window.get(index));
        }

        @Test
        void iteratesFromOldestToNewest() {
            SlidingWindowAggregator<Integer, Integer> window = sumWindow(3);
            window.addAll(List.of(1, 2, 3, 4, 5));
            List<Integer> seen = new ArrayList<>();
            for (int value : window) {
                seen.add(value);
            }
            assertEquals(List.of(3, 4, 5), seen);
            assertEquals("[3, 4, 5]", window.toString());
        }

        @Test
        void iteratorIsFailFast() {
            SlidingWindowAggregator<Integer, Integer> window = sumWindow(4);
            window.addAll(List.of(1, 2, 3));
            Iterator<Integer> iterator = window.iterator();
            assertEquals(1, iterator.next());
            window.add(4);
            assertThrows(ConcurrentModificationException.class, iterator::next);
        }

        @Test
        void toListIsASnapshot() {
            SlidingWindowAggregator<Integer, Integer> window = sumWindow(3);
            window.addAll(List.of(1, 2, 3));
            List<Integer> snapshot = window.toList();
            window.add(4);
            assertEquals(List.of(1, 2, 3), snapshot);
        }
    }

    @Nested
    @DisplayName("removal and reuse")
    class Removal {

        @Test
        void removeOldestShrinksTheWindow() {
            SlidingWindowAggregator<Integer, Integer> window = sumWindow(4);
            window.addAll(List.of(1, 2, 3, 4));
            assertEquals(1, window.removeOldest());
            assertEquals(9, window.aggregate());
            assertEquals(3, window.size());
            assertFalse(window.isFull());

            assertEquals(2, window.removeOldest());
            assertEquals(3, window.removeOldest());
            assertEquals(4, window.aggregate());
            assertEquals(4, window.removeOldest());
            assertTrue(window.isEmpty());
            assertThrows(NoSuchElementException.class, window::aggregate);
        }

        @Test
        void clearRestoresTheInitialState() {
            SlidingWindowAggregator<Integer, Integer> window = sumWindow(3);
            window.addAll(List.of(1, 2, 3, 4, 5));
            window.clear();
            assertTrue(window.isEmpty());
            assertEquals(0, window.size());
            assertThrows(NoSuchElementException.class, window::aggregate);

            window.addAll(List.of(7, 8));
            assertEquals(15, window.aggregate());
            assertEquals(List.of(7, 8), window.toList());
        }

        @Test
        @DisplayName("a capacity of one keeps only the latest element")
        void capacityOfOne() {
            SlidingWindowAggregator<Integer, Integer> window = sumWindow(1);
            window.add(1);
            assertEquals(1, window.aggregate());
            assertEquals(1, window.add(2));
            assertEquals(2, window.aggregate());
            assertEquals(2, window.add(3));
            assertEquals(3, window.aggregate());
            assertEquals(1, window.size());
        }

        @Test
        @DisplayName("survives far more insertions than its capacity")
        void survivesManyRotations() {
            SlidingWindowAggregator<Integer, Integer> window = sumWindow(3);
            for (int i = 1; i <= 100_000; i++) {
                window.add(i);
            }
            assertEquals(99_998 + 99_999 + 100_000, window.aggregate());
            assertEquals(3, window.size());
        }
    }

    @Nested
    @DisplayName("agreement with a brute force reference")
    class BruteForceAgreement {

        @ParameterizedTest
        @ValueSource(ints = {1, 2, 3, 5, 8, 13})
        void matchesBruteForceSum(int capacity) {
            assertMatchesBruteForce(capacity, Integer::sum);
        }

        @ParameterizedTest
        @ValueSource(ints = {1, 2, 3, 5, 8, 13})
        void matchesBruteForceMaximum(int capacity) {
            assertMatchesBruteForce(capacity, BinaryOperator.maxBy(NATURAL));
        }

        @ParameterizedTest
        @ValueSource(ints = {1, 2, 3, 5, 8, 13})
        void matchesBruteForceMinimum(int capacity) {
            assertMatchesBruteForce(capacity, BinaryOperator.minBy(NATURAL));
        }

        private void assertMatchesBruteForce(int capacity, BinaryOperator<Integer> combiner) {
            SlidingWindowAggregator<Integer, Integer> window = SlidingWindowAggregator.of(capacity, combiner);
            Deque<Integer> reference = new ArrayDeque<>();
            Random random = new Random(20240517L + capacity);

            for (int step = 0; step < 2_000; step++) {
                int value = random.nextInt(2_000) - 1_000;
                window.add(value);
                reference.addLast(value);
                if (reference.size() > capacity) {
                    reference.removeFirst();
                }
                assertEquals(fold(reference, combiner), window.aggregate(), "after step " + step);
            }
        }

        @Test
        @DisplayName("interleaved insertions and removals stay in sync with the reference")
        void matchesBruteForceUnderInterleavedOperations() {
            int capacity = 7;
            SlidingWindowAggregator<Integer, Integer> window = SlidingWindowAggregator.of(capacity, Integer::sum);
            Deque<Integer> reference = new ArrayDeque<>();
            Random random = new Random(987654321L);

            for (int step = 0; step < 20_000; step++) {
                if (reference.isEmpty() || random.nextInt(3) > 0) {
                    int value = random.nextInt(100);
                    window.add(value);
                    reference.addLast(value);
                    if (reference.size() > capacity) {
                        reference.removeFirst();
                    }
                } else {
                    assertEquals(reference.removeFirst(), window.removeOldest());
                }

                assertEquals(reference.size(), window.size());
                assertEquals(new ArrayList<>(reference), window.toList());
                if (reference.isEmpty()) {
                    assertThrows(NoSuchElementException.class, window::aggregate);
                } else {
                    assertEquals(fold(reference, Integer::sum), window.aggregate(), "after step " + step);
                }
            }
        }

        private Integer fold(Iterable<Integer> values, BinaryOperator<Integer> combiner) {
            Integer accumulator = null;
            for (Integer value : values) {
                accumulator = accumulator == null ? value : combiner.apply(accumulator, value);
            }
            return accumulator;
        }
    }

    @Test
    @DisplayName("the documented example from the class javadoc")
    void documentedExample() {
        SlidingWindowAggregator<Integer, Integer> window = SlidingWindowAggregator.maximum(3, Comparator.naturalOrder());
        List<Integer> printed = new ArrayList<>();
        for (int value : new int[] {1, 3, 2, 5, 0}) {
            window.add(value);
            printed.add(window.aggregate());
        }
        assertEquals(List.of(1, 3, 3, 5, 5), printed);
        Assertions.assertDoesNotThrow(window::clear);
    }
}

package com.thealgorithms.datastructures.caches;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.function.Executable;

class FIFOCacheTest {
    private FIFOCache<String, String> cache;
    private Set<String> evictedKeys;
    private List<String> evictedValues;

    @BeforeEach
    void setUp() {
        evictedKeys = new HashSet<>();
        evictedValues = new ArrayList<>();

        cache = new FIFOCache.Builder<String, String>(3)
                    .defaultTTL(1000)
                    .evictionListener((k, v) -> {
                        evictedKeys.add(k);
                        evictedValues.add(v);
                    })
                    .build();
    }

    @Test
    void testPutAndGet() {
        cache.put("a", "apple");
        Assertions.assertEquals("apple", cache.get("a"));
    }

    @Test
    void testOverwriteValue() {
        cache.put("a", "apple");
        cache.put("a", "avocado");
        Assertions.assertEquals("avocado", cache.get("a"));
    }

    @Test
    void testExpiration() throws InterruptedException {
        cache.put("temp", "value", 100);
        Thread.sleep(200);
        Assertions.assertNull(cache.get("temp"));
        Assertions.assertTrue(evictedKeys.contains("temp"));
    }

    @Test
    void testEvictionOnCapacity() {
        cache.put("a", "alpha");
        cache.put("b", "bravo");
        cache.put("c", "charlie");
        cache.put("d", "delta");

        int size = cache.size();
        Assertions.assertEquals(3, size);
        Assertions.assertEquals(1, evictedKeys.size());
        Assertions.assertEquals(1, evictedValues.size());
    }

    @Test
    void testEvictionListener() {
        cache.put("x", "one");
        cache.put("y", "two");
        cache.put("z", "three");
        cache.put("w", "four");

        Assertions.assertFalse(evictedKeys.isEmpty());
        Assertions.assertFalse(evictedValues.isEmpty());
    }

    @Test
    void testHitsAndMisses() {
        cache.put("a", "apple");
        Assertions.assertEquals("apple", cache.get("a"));
        Assertions.assertNull(cache.get("b"));
        Assertions.assertEquals(1, cache.getHits());
        Assertions.assertEquals(1, cache.getMisses());
    }

    @Test
    void testSizeExcludesExpired() throws InterruptedException {
        cache.put("a", "a", 100);
        cache.put("b", "b", 100);
        cache.put("c", "c", 100);
        Thread.sleep(150);
        Assertions.assertEquals(0, cache.size());
    }

    @Test
    void testSizeIncludesFresh() {
        cache.put("a", "a", 1000);
        cache.put("b", "b", 1000);
        cache.put("c", "c", 1000);
        Assertions.assertEquals(3, cache.size());
    }

    @Test
    void testToStringDoesNotExposeExpired() throws InterruptedException {
        cache.put("live", "alive");
        cache.put("dead", "gone", 100);
        Thread.sleep(150);
        String result = cache.toString();
        Assertions.assertTrue(result.contains("live"));
        Assertions.assertFalse(result.contains("dead"));
    }

    @Test
    void testNullKeyGetThrows() {
        Assertions.assertThrows(IllegalArgumentException.class, () -> cache.get(null));
    }

    @Test
    void testPutNullKeyThrows() {
        Assertions.assertThrows(IllegalArgumentException.class, () -> cache.put(null, "v"));
    }

    @Test
    void testPutNullValueThrows() {
        Assertions.assertThrows(IllegalArgumentException.class, () -> cache.put("k", null));
    }

    @Test
    void testPutNegativeTTLThrows() {
        Assertions.assertThrows(IllegalArgumentException.class, () -> cache.put("k", "v", -1));
    }

    @Test
    void testBuilderNegativeCapacityThrows() {
        Assertions.assertThrows(IllegalArgumentException.class, () -> new FIFOCache.Builder<>(0));
    }

    @Test
    void testBuilderNullEvictionListenerThrows() {
        FIFOCache.Builder<String, String> builder = new FIFOCache.Builder<>(1);
        Assertions.assertThrows(IllegalArgumentException.class, () -> builder.evictionListener(null));
    }

    @Test
    void testEvictionListenerExceptionDoesNotCrash() {
        FIFOCache<String, String> listenerCache = new FIFOCache.Builder<String, String>(1).evictionListener((k, v) -> { throw new RuntimeException("Exception"); }).build();

        listenerCache.put("a", "a");
        listenerCache.put("b", "b");
        Assertions.assertDoesNotThrow(() -> listenerCache.get("a"));
    }

    @Test
    void testTtlZeroThrowsIllegalArgumentException() {
        Executable exec = () -> new FIFOCache.Builder<String, String>(3).defaultTTL(-1).build();
        Assertions.assertThrows(IllegalArgumentException.class, exec);
    }

    @Test
    void testPeriodicEvictionStrategyEvictsAtInterval() throws InterruptedException {
        FIFOCache<String, String> periodicCache = new FIFOCache.Builder<String, String>(10).defaultTTL(50).evictionStrategy(new FIFOCache.PeriodicEvictionStrategy<>(3)).build();

        periodicCache.put("x", "1");
        Thread.sleep(100);
        int ev1 = periodicCache.getEvictionStrategy().onAccess(periodicCache);
        int ev2 = periodicCache.getEvictionStrategy().onAccess(periodicCache);
        int ev3 = periodicCache.getEvictionStrategy().onAccess(periodicCache);

        Assertions.assertEquals(0, ev1);
        Assertions.assertEquals(0, ev2);
        Assertions.assertEquals(1, ev3, "Eviction should happen on the 3rd access");
        Assertions.assertEquals(0, periodicCache.size());
    }

    @Test
    void testPeriodicEvictionStrategyThrowsExceptionIfIntervalLessThanOrEqual0() {
        Executable executable = () -> new FIFOCache.Builder<String, String>(10).defaultTTL(50).evictionStrategy(new FIFOCache.PeriodicEvictionStrategy<>(0)).build();

        Assertions.assertThrows(IllegalArgumentException.class, executable);
    }

    @Test
    void testImmediateEvictionStrategyStrategyEvictsOnEachCall() throws InterruptedException {
        FIFOCache<String, String> immediateEvictionStrategy = new FIFOCache.Builder<String, String>(10).defaultTTL(50).evictionStrategy(new FIFOCache.ImmediateEvictionStrategy<>()).build();

        immediateEvictionStrategy.put("x", "1");
        Thread.sleep(100);
        int evicted = immediateEvictionStrategy.getEvictionStrategy().onAccess(immediateEvictionStrategy);

        Assertions.assertEquals(1, evicted);
    }

    @Test
    void testBuilderThrowsExceptionIfEvictionStrategyNull() {
        Executable executable = () -> new FIFOCache.Builder<String, String>(10).defaultTTL(50).evictionStrategy(null).build();

        Assertions.assertThrows(IllegalArgumentException.class, executable);
    }

    @Test
    void testReturnsCorrectStrategyInstance() {
        FIFOCache.EvictionStrategy<String, String> strategy = new FIFOCache.ImmediateEvictionStrategy<>();

        FIFOCache<String, String> newCache = new FIFOCache.Builder<String, String>(10).defaultTTL(1000).evictionStrategy(strategy).build();

        Assertions.assertSame(strategy, newCache.getEvictionStrategy(), "Returned strategy should be the same instance");
    }

    @Test
    void testDefaultStrategyIsImmediateEvictionStrategy() {
        FIFOCache<String, String> newCache = new FIFOCache.Builder<String, String>(5).defaultTTL(1000).build();

        Assertions.assertTrue(newCache.getEvictionStrategy() instanceof FIFOCache.ImmediateEvictionStrategy<String, String>, "Default strategy should be ImmediateEvictionStrategyStrategy");
    }

    @Test
    void testGetEvictionStrategyIsNotNull() {
        FIFOCache<String, String> newCache = new FIFOCache.Builder<String, String>(5).build();

        Assertions.assertNotNull(newCache.getEvictionStrategy(), "Eviction strategy should never be null");
    }

    @Test
    void testRemoveKeyRemovesExistingKey() {
        cache.put("A", "Alpha");
        cache.put("B", "Beta");

        Assertions.assertEquals("Alpha", cache.get("A"));
        Assertions.assertEquals("Beta", cache.get("B"));

        String removed = cache.removeKey("A");
        Assertions.assertEquals("Alpha", removed);

        Assertions.assertNull(cache.get("A"));
        Assertions.assertEquals(1, cache.size());
    }

    @Test
    void testRemoveKeyReturnsNullIfKeyNotPresent() {
        cache.put("X", "X-ray");

        Assertions.assertNull(cache.removeKey("NonExistent"));
        Assertions.assertEquals(1, cache.size());
    }

    @Test
    void testRemoveKeyHandlesExpiredEntry() throws InterruptedException {
        FIFOCache<String, String> expiringCache = new FIFOCache.Builder<String, String>(2).defaultTTL(100).evictionStrategy(new FIFOCache.ImmediateEvictionStrategy<>()).build();

        expiringCache.put("T", "Temporary");

        Thread.sleep(200);

        String removed = expiringCache.removeKey("T");
        Assertions.assertEquals("Temporary", removed);
        Assertions.assertNull(expiringCache.get("T"));
    }

    @Test
    void testRemoveKeyThrowsIfKeyIsNull() {
        Assertions.assertThrows(IllegalArgumentException.class, () -> cache.removeKey(null));
    }

    @Test
    void testRemoveKeyTriggersEvictionListener() {
        AtomicInteger evictedCount = new AtomicInteger();

        FIFOCache<String, String> localCache = new FIFOCache.Builder<String, String>(2).evictionListener((key, value) -> evictedCount.incrementAndGet()).build();

        localCache.put("A", "Apple");
        localCache.put("B", "Banana");

        localCache.removeKey("A");

        Assertions.assertEquals(1, evictedCount.get(), "Eviction listener should have been called once");
    }

    @Test
    void testRemoveKeyDoestNotAffectOtherKeys() {
        cache.put("A", "Alpha");
        cache.put("B", "Beta");
        cache.put("C", "Gamma");

        cache.removeKey("B");

        Assertions.assertEquals("Alpha", cache.get("A"));
        Assertions.assertNull(cache.get("B"));
        Assertions.assertEquals("Gamma", cache.get("C"));
    }

    @Test
    void testEvictionListenerExceptionDoesNotPropagate() {
        FIFOCache<String, String> localCache = new FIFOCache.Builder<String, String>(1).evictionListener((key, value) -> { throw new RuntimeException(); }).build();

        localCache.put("A", "Apple");

        Assertions.assertDoesNotThrow(() -> localCache.put("B", "Beta"));
    }

    @Test
    void testGetKeysReturnsAllFreshKeys() {
        cache.put("A", "Alpha");
        cache.put("B", "Beta");
        cache.put("G", "Gamma");

        Set<String> expectedKeys = Set.of("A", "B", "G");
        Assertions.assertEquals(expectedKeys, cache.getAllKeys());
    }

    @Test
    void testGetKeysIgnoresExpiredKeys() throws InterruptedException {
        cache.put("A", "Alpha");
        cache.put("B", "Beta");
        cache.put("G", "Gamma", 100);

        Set<String> expectedKeys = Set.of("A", "B");
        Thread.sleep(200);
        Assertions.assertEquals(expectedKeys, cache.getAllKeys());
    }

    @Test
    void testClearRemovesAllEntries() {
        cache.put("A", "Alpha");
        cache.put("B", "Beta");
        cache.put("G", "Gamma");

        cache.clear();
        Assertions.assertEquals(0, cache.size());
    }
}

package com.thealgorithms.datastructures.caches;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;

import org.junit.jupiter.api.Test;

class LFUCacheTest {

    @Test
    void testLFUCacheWithIntegerValueShouldPass() {
        LFUCache<Integer, Integer> lfuCache = new LFUCache<>(5);
        lfuCache.put(1, 10);
        lfuCache.put(2, 20);
        lfuCache.put(3, 30);
        lfuCache.put(4, 40);
        lfuCache.put(5, 50);

        // get method call will increase frequency of key 1 by 1
        assertEquals(10, lfuCache.get(1));

        // this operation will remove value with key as 2
        lfuCache.put(6, 60);

        // will return null as value with key 2 is now evicted
        assertNull(lfuCache.get(2));

        // should return 60
        assertEquals(60, lfuCache.get(6));

        // this operation will remove value with key as 3
        lfuCache.put(7, 70);

        assertNull(lfuCache.get(2));
        assertEquals(70, lfuCache.get(7));
    }

    @Test
    void testLFUCacheWithStringValueShouldPass() {
        LFUCache<Integer, String> lfuCache = new LFUCache<>(5);
        lfuCache.put(1, "Alpha");
        lfuCache.put(2, "Beta");
        lfuCache.put(3, "Gamma");
        lfuCache.put(4, "Delta");
        lfuCache.put(5, "Epsilon");

        // get method call will increase frequency of key 1 by 1
        assertEquals("Alpha", lfuCache.get(1));

        // this operation will remove value with key as 2
        lfuCache.put(6, "Digamma");

        // will return null as value with key 2 is now evicted
        assertNull(lfuCache.get(2));

        // should return string Digamma
        assertEquals("Digamma", lfuCache.get(6));

        // this operation will remove value with key as 3
        lfuCache.put(7, "Zeta");

        assertNull(lfuCache.get(2));
        assertEquals("Zeta", lfuCache.get(7));
    }

    @Test
    void testUpdateValueShouldPreserveFrequency() {
        LFUCache<Integer, String> lfuCache = new LFUCache<>(3);
        lfuCache.put(1, "A");
        lfuCache.put(2, "B");
        lfuCache.put(3, "C");

        assertEquals("A", lfuCache.get(1)); // Accessing key 1
        lfuCache.put(4, "D"); // This should evict key 2

        assertNull(lfuCache.get(2)); // Key 2 should be evicted
        assertEquals("C", lfuCache.get(3)); // Key 3 should still exist
        assertEquals("A", lfuCache.get(1)); // Key 1 should still exist

        lfuCache.put(1, "Updated A"); // Update the value of key 1
        assertEquals("Updated A", lfuCache.get(1)); // Check if the update was successful
    }

    @Test
    void testEvictionPolicyWhenFull() {
        LFUCache<Integer, String> lfuCache = new LFUCache<>(2);
        lfuCache.put(1, "One");
        lfuCache.put(2, "Two");

        assertEquals("One", lfuCache.get(1)); // Access key 1
        lfuCache.put(3, "Three"); // This should evict key 2 (least frequently used)

        assertNull(lfuCache.get(2)); // Key 2 should be evicted
        assertEquals("One", lfuCache.get(1)); // Key 1 should still exist
        assertEquals("Three", lfuCache.get(3)); // Check if key 3 exists
    }

    @Test
    void testGetFromEmptyCacheShouldReturnNull() {
        LFUCache<Integer, String> lfuCache = new LFUCache<>(3);
        assertNull(lfuCache.get(1)); // Should return null as the cache is empty
    }

    @Test
    void testPutNullValueShouldStoreNull() {
        LFUCache<Integer, String> lfuCache = new LFUCache<>(3);
        lfuCache.put(1, null); // Store a null value

        assertNull(lfuCache.get(1)); // Should return null
    }

    @Test
    void testInvalidCacheCapacityShouldThrowException() {
        assertThrows(IllegalArgumentException.class, () -> new LFUCache<>(0));
        assertThrows(IllegalArgumentException.class, () -> new LFUCache<>(-1));
    }

    @Test
    void testMultipleAccessPatterns() {
        LFUCache<Integer, String> lfuCache = new LFUCache<>(5);
        lfuCache.put(1, "A");
        lfuCache.put(2, "B");
        lfuCache.put(3, "C");
        lfuCache.put(4, "D");

        assertEquals("A", lfuCache.get(1)); // Access 1
        lfuCache.put(5, "E"); // Should not evict anything yet
        lfuCache.put(6, "F"); // Evict B

        assertNull(lfuCache.get(2)); // B should be evicted
        assertEquals("C", lfuCache.get(3)); // C should still exist
        assertEquals("D", lfuCache.get(4)); // D should still exist
        assertEquals("A", lfuCache.get(1)); // A should still exist
        assertEquals("E", lfuCache.get(5)); // E should exist
        assertEquals("F", lfuCache.get(6)); // F should exist
    }
}

package com.thealgorithms.datastructures.caches;

