    }

    @Test
    void testLookupEarlierTimestampsTrue() {
        LWWElementSet<String> set = new LWWElementSet<>();

        set.addSet.put("A", new Element<>("A", Instant.now()));
        set.removeSet.put("A", new Element<>("A", Instant.now().minusSeconds(10)));

