    }

    @Test
    void testLookupWithConcurrentTimestamps() {
        LWWElementSet<String> set = new LWWElementSet<>();
        Instant now = Instant.now();
        set.addSet.put("A", new Element<>("A", now));
        set.removeSet.put("A", new Element<>("A", now));
        assertFalse(set.lookup("A"));
    }

    @Test
