        assertEquals(1, array.getSize());
        assertEquals("Bob", array.get(0));

        assertEquals("Bob", array.remove(0));
        assertTrue(array.isEmpty());
        assertThrows(IndexOutOfBoundsException.class, () -> array.get(0));
    }

    @Test
    public void testIsEmpty() {
