    void testTwoDisconnectedComponents() {
        Graph<Integer> graph = new Graph<>();
        // Component 1: 1-2-3
        graph.addEdge(1, 2);
        graph.addEdge(2, 3);
        // Component 2: 4-5
        graph.addEdge(4, 5);

        assertEquals(2, graph.countGraphs());
    }

