    void testThreeDisconnectedComponents() {
        Graph<Character> graph = new Graph<>();
        // Component 1: a-b-c-d-e
        graph.addEdge('a', 'b');
        graph.addEdge('a', 'e');
        graph.addEdge('b', 'e');
        graph.addEdge('b', 'c');
        graph.addEdge('c', 'd');
        graph.addEdge('d', 'a');
        // Component 2: x-y-z
        graph.addEdge('x', 'y');
        graph.addEdge('x', 'z');
        // Component 3: w (self-loop)
        graph.addEdge('w', 'w');

        assertEquals(3, graph.countGraphs());
    }

    @Test
    void testSingleNodeSelfLoop() {
        Graph<Integer> graph = new Graph<>();
        graph.addEdge(1, 1);

        assertEquals(1, graph.countGraphs());
    }

    @Test
    void testLinearChain() {
        Graph<Integer> graph = new Graph<>();
        graph.addEdge(1, 2);
        graph.addEdge(2, 3);
        graph.addEdge(3, 4);
        graph.addEdge(4, 5);

        assertEquals(1, graph.countGraphs());
    }

    @Test
    void testStarTopology() {
        // Star graph with center node 0 connected to nodes 1, 2, 3, 4
        Graph<Integer> graph = new Graph<>();
        graph.addEdge(0, 1);
        graph.addEdge(0, 2);
        graph.addEdge(0, 3);
        graph.addEdge(0, 4);

        assertEquals(1, graph.countGraphs());
    }

    @Test
    void testCompleteGraph() {
        // Complete graph K4: every node connected to every other node
        Graph<Integer> graph = new Graph<>();
        graph.addEdge(1, 2);
        graph.addEdge(1, 3);
        graph.addEdge(1, 4);
        graph.addEdge(2, 3);
        graph.addEdge(2, 4);
        graph.addEdge(3, 4);

        assertEquals(1, graph.countGraphs());
    }

    @Test
    void testStringVertices() {
