        graph.addEdge("New York", "Los Angeles");
        graph.addEdge("Los Angeles", "Chicago");
        // Component 2
        graph.addEdge("London", "Paris");
        // Component 3
        graph.addEdge("Tokyo", "Tokyo");

        assertEquals(3, graph.countGraphs());
    }

    @Test
    void testEmptyGraph() {
