        int[][] cap = new int[3][3];
        cap[0][1] = 3;
        cap[1][0] = 3;
        cap[1][2] = 2;
        cap[2][1] = 2;
        cap[0][2] = 4;
        cap[2][0] = 4;

        int[][] tree = GomoryHuTree.buildTree(cap);
        // validate all pairs via path-min-edge equals maxflow
        validateAllPairs(cap, tree);
    }

    @Test
    @DisplayName("Random small undirected graphs compare to EdmondsKarp")
    void randomSmallGraphs() {
        Random rng = new Random(42);
        for (int n = 2; n <= 6; n++) {
            for (int iter = 0; iter < 10; iter++) {
                int[][] cap = randSymmetricMatrix(n, 0, 5, rng);
                int[][] tree = GomoryHuTree.buildTree(cap);
                validateAllPairs(cap, tree);
            }
        }
    }

    private static int[][] randSymmetricMatrix(int n, int lo, int hi, RandomGenerator rng) {
        int[][] a = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int w = rng.nextInt(hi - lo + 1) + lo;
                a[i][j] = w;
                a[j][i] = w;
            }
        }
        // zero diagonal
        for (int i = 0; i < n; i++) {
            a[i][i] = 0;
        }
        return a;
    }

    private static void validateAllPairs(int[][] cap, int[][] tree) {
        int n = cap.length;
        int[] parent = tree[0];
        int[] weight = tree[1];

        // build adjacency list of tree without generic array creation
        List<List<int[]>> g = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            g.add(new ArrayList<>());
        }
        for (int v = 1; v < n; v++) {
            int u = parent[v];
            int w = weight[v];
            g.get(u).add(new int[] {v, w});
            g.get(v).add(new int[] {u, w});
        }

        for (int s = 0; s < n; s++) {
            for (int t = s + 1; t < n; t++) {
                int treeVal = minEdgeOnPath(g, s, t);
                int flowVal = EdmondsKarp.maxFlow(cap, s, t);
                assertEquals(flowVal, treeVal, "pair (" + s + "," + t + ")");
            }
        }
    }

    private static int minEdgeOnPath(List<List<int[]>> g, int s, int t) {
        // BFS to record parent and edge weight along the path, since it's a tree, unique path exists
        int n = g.size();
        int[] parent = new int[n];
        int[] edgeW = new int[n];
        Arrays.fill(parent, -1);
        Queue<Integer> q = new ArrayDeque<>();
        q.add(s);
        parent[s] = s;
        while (!q.isEmpty()) {
            int u = q.poll();
            if (u == t) {
                break;
            }
            for (int[] e : g.get(u)) {
                int v = e[0];
                int w = e[1];
                if (parent[v] == -1) {
                    parent[v] = u;
                    edgeW[v] = w;
                    q.add(v);
                }
            }
        }
        int cur = t;
        int ans = Integer.MAX_VALUE;
        while (cur != s) {
            ans = Math.min(ans, edgeW[cur]);
            cur = parent[cur];
        }
        return ans == Integer.MAX_VALUE ? 0 : ans;
    }
}

package com.thealgorithms.graph;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;

public class HierholzerAlgorithmTest {

    @Test
    public void testFindsEulerianCircuitInSimpleTriangleGraph() {
        Map<Integer, LinkedList<Integer>> graph = new HashMap<>();
        graph.put(0, new LinkedList<>(Arrays.asList(1, 2)));
        graph.put(1, new LinkedList<>(Arrays.asList(0, 2)));
        graph.put(2, new LinkedList<>(Arrays.asList(0, 1)));
        HierholzerAlgorithm algorithm = new HierholzerAlgorithm(graph);
        assertTrue(algorithm.hasEulerianCircuit());
        List<Integer> circuit = algorithm.findEulerianCircuit();
        assertEquals(4, circuit.size());
        assertEquals(circuit.get(0), circuit.get(circuit.size() - 1));
    }

    @Test
    public void testFailsForGraphWithOddDegreeVertices() {
        Map<Integer, LinkedList<Integer>> graph = new HashMap<>();
        graph.put(0, new LinkedList<>(Collections.singletonList(1)));
        graph.put(1, new LinkedList<>(Collections.singletonList(0)));
        HierholzerAlgorithm algorithm = new HierholzerAlgorithm(graph);
        assertFalse(algorithm.hasEulerianCircuit());
        assertTrue(algorithm.findEulerianCircuit().isEmpty());
    }

    @Test
    public void testFailsForDisconnectedGraph() {
        Map<Integer, LinkedList<Integer>> graph = new HashMap<>();
        graph.put(0, new LinkedList<>(Arrays.asList(1, 2)));
        graph.put(1, new LinkedList<>(Arrays.asList(0, 2)));
        graph.put(2, new LinkedList<>(Arrays.asList(0, 1)));
        graph.put(3, new LinkedList<>(Arrays.asList(4, 5)));
        graph.put(4, new LinkedList<>(Arrays.asList(3, 5)));
        graph.put(5, new LinkedList<>(Arrays.asList(3, 4)));
        HierholzerAlgorithm algorithm = new HierholzerAlgorithm(graph);
        assertFalse(algorithm.hasEulerianCircuit());
    }

    @Test
    public void testHandlesEmptyGraph() {
        Map<Integer, LinkedList<Integer>> graph = new HashMap<>();
        HierholzerAlgorithm algorithm = new HierholzerAlgorithm(graph);
        assertTrue(algorithm.hasEulerianCircuit());
        assertTrue(algorithm.findEulerianCircuit().isEmpty());
    }
}

package com.thealgorithms.graph;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.jupiter.api.Test;

/**
 * Unit tests for {@link HierholzerEulerianPath}.
 *
 * This test suite validates Hierholzer's Algorithm implementation
 * for finding Eulerian Paths and Circuits in directed graphs.
 *
 * <p>Coverage includes:
 * <ul>
 *   <li>Basic Eulerian Circuit</li>
 *   <li>Eulerian Path</li>
 *   <li>Disconnected graphs</li>
 *   <li>Single-node graphs</li>
 *   <li>Graphs with no edges</li>
 *   <li>Graphs that do not have any Eulerian Path/Circuit</li>
 * </ul>
 * </p>
 */
class HierholzerEulerianPathTest {

    @Test
    void testSimpleEulerianCircuit() {
        HierholzerEulerianPath.Graph graph = new HierholzerEulerianPath.Graph(3);
        graph.addEdge(0, 1);
        graph.addEdge(1, 2);
        graph.addEdge(2, 0);

        HierholzerEulerianPath solver = new HierholzerEulerianPath(graph);
        List<Integer> result = solver.findEulerianPath();

        // Eulerian Circuit: [0, 1, 2, 0]
        List<Integer> expected = Arrays.asList(0, 1, 2, 0);
        assertEquals(expected, result);
    }

    @Test
    void testEulerianPathDifferentStartEnd() {
        HierholzerEulerianPath.Graph graph = new HierholzerEulerianPath.Graph(4);
        graph.addEdge(0, 1);
        graph.addEdge(1, 2);
        graph.addEdge(2, 3);
        graph.addEdge(3, 1);

        HierholzerEulerianPath solver = new HierholzerEulerianPath(graph);
        List<Integer> result = solver.findEulerianPath();

        // Eulerian Path: [0, 1, 2, 3, 1]
        List<Integer> expected = Arrays.asList(0, 1, 2, 3, 1);
        assertEquals(expected, result);
    }

    @Test
    void testNoEulerianPathExists() {
        HierholzerEulerianPath.Graph graph = new HierholzerEulerianPath.Graph(3);
        graph.addEdge(0, 1);
        graph.addEdge(1, 2);
        // Edge 2->0 missing, so it's not Eulerian Circuit

        HierholzerEulerianPath solver = new HierholzerEulerianPath(graph);
        List<Integer> result = solver.findEulerianPath();

        assertEquals(result, Arrays.asList(0, 1, 2));
    }

    @Test
    void testDisconnectedGraph() {
        HierholzerEulerianPath.Graph graph = new HierholzerEulerianPath.Graph(4);
        graph.addEdge(0, 1);
        graph.addEdge(2, 3); // disconnected component

        HierholzerEulerianPath solver = new HierholzerEulerianPath(graph);
        List<Integer> result = solver.findEulerianPath();

        // Disconnected graph cannot have an Eulerian path
        assertTrue(result.isEmpty());
    }

    @Test
    void testGraphWithSelfLoop() {
        HierholzerEulerianPath.Graph graph = new HierholzerEulerianPath.Graph(3);
        graph.addEdge(0, 0); // self loop
        graph.addEdge(0, 1);
        graph.addEdge(1, 2);
        graph.addEdge(2, 0);

        HierholzerEulerianPath solver = new HierholzerEulerianPath(graph);
        List<Integer> result = solver.findEulerianPath();

        // Eulerian Circuit with self-loop included: [0, 0, 1, 2, 0]
        assertEquals(Arrays.asList(0, 0, 1, 2, 0), result);
    }

    @Test
    void testSingleNodeNoEdges() {
        HierholzerEulerianPath.Graph graph = new HierholzerEulerianPath.Graph(1);

        HierholzerEulerianPath solver = new HierholzerEulerianPath(graph);
        List<Integer> result = solver.findEulerianPath();

        // Only one vertex and no edges
        assertEquals(Collections.singletonList(0), result);
    }

    @Test
    void testSingleNodeWithLoop() {
        HierholzerEulerianPath.Graph graph = new HierholzerEulerianPath.Graph(1);
        graph.addEdge(0, 0);

        HierholzerEulerianPath solver = new HierholzerEulerianPath(graph);
        List<Integer> result = solver.findEulerianPath();

        // Eulerian circuit on a single node with a self-loop
        assertEquals(Arrays.asList(0, 0), result);
    }

    @Test
    void testComplexEulerianCircuit() {
        HierholzerEulerianPath.Graph graph = new HierholzerEulerianPath.Graph(5);
        graph.addEdge(0, 1);
        graph.addEdge(1, 2);
        graph.addEdge(2, 3);
        graph.addEdge(3, 4);
        graph.addEdge(4, 0);
        graph.addEdge(1, 3);
        graph.addEdge(3, 1);

        HierholzerEulerianPath solver = new HierholzerEulerianPath(graph);
        List<Integer> result = solver.findEulerianPath();

        // Verify all edges are used
        int totalEdges = 7;
        assertEquals(totalEdges + 1, result.size(), "Path must contain all edges + 1 vertices");
        assertEquals(result.get(0), result.get(result.size() - 1), "Must form a circuit");
    }

    @Test
    void testMultipleEdgesBetweenSameNodes() {
        HierholzerEulerianPath.Graph graph = new HierholzerEulerianPath.Graph(3);
        graph.addEdge(0, 1);
        graph.addEdge(0, 1);
        graph.addEdge(1, 2);
        graph.addEdge(2, 0);

        HierholzerEulerianPath solver = new HierholzerEulerianPath(graph);
        List<Integer> result = solver.findEulerianPath();

        // Has an Eulerian Path but not an Eulerian Circuit
        assertEquals(result, Arrays.asList(0, 1, 2, 0, 1));
    }

    @Test
    void testCoverageForEmptyGraph() {
        HierholzerEulerianPath.Graph graph = new HierholzerEulerianPath.Graph(0);
        HierholzerEulerianPath solver = new HierholzerEulerianPath(graph);
        List<Integer> result = solver.findEulerianPath();

        // Empty graph has no vertices or path
        assertTrue(result.isEmpty());
    }
}

package com.thealgorithms.graph;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

/**
 * Unit tests for Hopcroft–Karp algorithm.
 *
 * @author ptzecher
 */
class HopcroftKarpTest {

    private static List<List<Integer>> adj(int nLeft) {
        List<List<Integer>> g = new ArrayList<>(nLeft);
        for (int i = 0; i < nLeft; i++) { // braces required by Checkstyle
            g.add(new ArrayList<>());
        }
        return g;
    }

    @Test
    @DisplayName("Empty graph has matching 0")
    void emptyGraph() {
        List<List<Integer>> g = adj(3);
        HopcroftKarp hk = new HopcroftKarp(3, 4, g);
        assertEquals(0, hk.maxMatching());
    }

    @Test
    @DisplayName("Single edge gives matching 1")
    void singleEdge() {
        List<List<Integer>> g = adj(1);
        g.get(0).add(0);
        HopcroftKarp hk = new HopcroftKarp(1, 1, g);
        assertEquals(1, hk.maxMatching());

        int[] leftMatch = hk.getLeftMatches();
        int[] rightMatch = hk.getRightMatches();
        assertEquals(0, leftMatch[0]);
        assertEquals(0, rightMatch[0]);
    }

    @Test
    @DisplayName("Disjoint edges match perfectly")
    void disjointEdges() {
        // L0-R0, L1-R1, L2-R2
        List<List<Integer>> g = adj(3);
        g.get(0).add(0);
        g.get(1).add(1);
        g.get(2).add(2);

        HopcroftKarp hk = new HopcroftKarp(3, 3, g);
        assertEquals(3, hk.maxMatching());

        int[] leftMatch = hk.getLeftMatches();
        int[] rightMatch = hk.getRightMatches();
        for (int i = 0; i < 3; i++) {
            assertEquals(i, leftMatch[i]);
            assertEquals(i, rightMatch[i]);
        }
    }

    @Test
    @DisplayName("Complete bipartite K(3,4) matches min(3,4)=3")
    void completeK34() {
        int nLeft = 3;
        int nRight = 4; // split declarations
        List<List<Integer>> g = adj(nLeft);
        for (int u = 0; u < nLeft; u++) {
            g.get(u).addAll(Arrays.asList(0, 1, 2, 3));
        }
        HopcroftKarp hk = new HopcroftKarp(nLeft, nRight, g);
        assertEquals(3, hk.maxMatching());

        // sanity: no two left vertices share the same matched right vertex
        int[] leftMatch = hk.getLeftMatches();
        boolean[] used = new boolean[nRight];
        for (int u = 0; u < nLeft; u++) {
            int v = leftMatch[u];
            if (v != -1) {
                assertFalse(used[v]);
                used[v] = true;
            }
        }
    }

    @Test
    @DisplayName("Rectangular, sparse graph")
    void rectangularSparse() {
        // Left: 5, Right: 2
        // edges: L0-R0, L1-R1, L2-R0, L3-R1  (max matching = 2)
        List<List<Integer>> g = adj(5);
        g.get(0).add(0);
        g.get(1).add(1);
        g.get(2).add(0);
        g.get(3).add(1);
        // L4 isolated

        HopcroftKarp hk = new HopcroftKarp(5, 2, g);
        assertEquals(2, hk.maxMatching());

        int[] leftMatch = hk.getLeftMatches();
        int[] rightMatch = hk.getRightMatches();

        // Check consistency: if leftMatch[u]=v then rightMatch[v]=u
        for (int u = 0; u < 5; u++) {
            int v = leftMatch[u];
            if (v != -1) {
                assertEquals(u, rightMatch[v]);
            }
        }
    }

    @Test
    @DisplayName("Layering advantage case (short augmenting paths)")
    void layeringAdvantage() {
        // Left 4, Right 4
        List<List<Integer>> g = adj(4);
        g.get(0).addAll(Arrays.asList(0, 1));
        g.get(1).addAll(Arrays.asList(1, 2));
        g.get(2).addAll(Arrays.asList(2, 3));
        g.get(3).addAll(Arrays.asList(0, 3));

        HopcroftKarp hk = new HopcroftKarp(4, 4, g);
        assertEquals(4, hk.maxMatching()); // perfect matching exists
    }
}

package com.thealgorithms.graph;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

class HungarianAlgorithmTest {

    @Test
    @DisplayName("Classic 3x3 example: minimal cost 5 with assignment [1,0,2]")
    void classicSquareExample() {
        int[][] cost = {{4, 1, 3}, {2, 0, 5}, {3, 2, 2}};
        HungarianAlgorithm.Result res = HungarianAlgorithm.solve(cost);
        assertEquals(5, res.minCost);
        assertArrayEquals(new int[] {1, 0, 2}, res.assignment);
    }

    @Test
    @DisplayName("Rectangular (more rows than cols): pads to square and returns -1 for unassigned rows")
    void rectangularMoreRows() {
        int[][] cost = {{7, 3}, {2, 8}, {5, 1}};
        // Optimal selects any 2 rows: choose row1->col0 (2) and row2->col1 (1) => total 3
        HungarianAlgorithm.Result res = HungarianAlgorithm.solve(cost);
        assertEquals(3, res.minCost);
        // Two rows assigned to 2 columns; one row remains -1.
        int assigned = 0;
        for (int a : res.assignment) {
            if (a >= 0) {
                assigned++;
            }
        }
        assertEquals(2, assigned);
    }

    @Test
    @DisplayName("Zero diagonal yields zero total cost")
    void zeroDiagonal() {
        int[][] cost = {{0, 5, 9}, {4, 0, 7}, {3, 6, 0}};
        HungarianAlgorithm.Result res = HungarianAlgorithm.solve(cost);
        assertEquals(0, res.minCost);
    }
}

package com.thealgorithms.graph;

import static org.assertj.core.api.Assertions.assertThat;
import static org.junit.jupiter.api.Assertions.assertThrows;

import com.thealgorithms.graph.PredecessorConstrainedDfs.TraversalEvent;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;

class PredecessorConstrainedDfsTest {

    // A -> B, A -> C, B -> D, C -> D   (classic diamond)
    private static Map<String, List<String>> diamond() {
        Map<String, List<String>> g = new LinkedHashMap<>();
        g.put("A", List.of("B", "C"));
        g.put("B", List.of("D"));
        g.put("C", List.of("D"));
        g.put("D", List.of());
        return g;
    }

    @Test
    void dfsRecursiveOrderEmitsSkipUntilAllParentsVisited() {
        List<TraversalEvent<String>> events = PredecessorConstrainedDfs.dfsRecursiveOrder(diamond(), "A");

        // Expect visits in order and a skip for first time we meet D (via B) before C is visited.
        var visits = events.stream().filter(TraversalEvent::isVisit).toList();
        var skips = events.stream().filter(TraversalEvent::isSkip).toList();

        // Visits should be A(0), B(1), C(2), D(3) in some deterministic order given adjacency
        assertThat(visits).hasSize(4);
        assertThat(visits.get(0).node()).isEqualTo("A");
        assertThat(visits.get(0).order()).isEqualTo(0);
        assertThat(visits.get(1).node()).isEqualTo("B");
        assertThat(visits.get(1).order()).isEqualTo(1);
        assertThat(visits.get(2).node()).isEqualTo("C");
        assertThat(visits.get(2).order()).isEqualTo(2);
        assertThat(visits.get(3).node()).isEqualTo("D");
        assertThat(visits.get(3).order()).isEqualTo(3);

        // One skip when we first encountered D from B (before C was visited)
        assertThat(skips).hasSize(1);
        assertThat(skips.get(0).node()).isEqualTo("D");
        assertThat(skips.get(0).note()).contains("not all parents");
    }

    @Test
    void returnsEmptyWhenStartNotInGraph() {
        Map<Integer, List<Integer>> graph = Map.of(1, List.of(2), 2, List.of(1));
        assertThat(PredecessorConstrainedDfs.dfsRecursiveOrder(graph, 99)).isEmpty();
    }

    @Test
    void nullSuccessorsThrows() {
        assertThrows(IllegalArgumentException.class, () -> PredecessorConstrainedDfs.dfsRecursiveOrder(null, "A"));
    }

    @Test
    void worksWithExplicitPredecessors() {
        Map<Integer, List<Integer>> successors = new HashMap<>();
        successors.put(10, List.of(20));
        successors.put(20, List.of(30));
        successors.put(30, List.of());

        Map<Integer, List<Integer>> predecessors = new HashMap<>();
        predecessors.put(10, List.of());
        predecessors.put(20, List.of(10));
        predecessors.put(30, List.of(20));

        var events = PredecessorConstrainedDfs.dfsRecursiveOrder(successors, predecessors, 10);
        var visitNodes = events.stream().filter(TraversalEvent::isVisit).map(TraversalEvent::node).toList();
        assertThat(visitNodes).containsExactly(10, 20, 30);
    }

    @Test
    void cycleProducesSkipsButNoInfiniteRecursion() {
        Map<String, List<String>> successors = new LinkedHashMap<>();
        successors.put("X", List.of("Y"));
        successors.put("Y", List.of("X")); // 2-cycle

        var events = PredecessorConstrainedDfs.dfsRecursiveOrder(successors, "X");
        // Only X is visited; encountering Y from X causes skip because Y's parent X is visited,
        // but when recursing to Y we'd hit back to X (already visited) and stop; no infinite loop.
        assertThat(events.stream().anyMatch(TraversalEvent::isVisit)).isTrue();
        assertThat(events.stream().filter(TraversalEvent::isVisit).map(TraversalEvent::node)).contains("X");
    }
}

