    }

    @Test
    public void testAlternatingBits() {
        String a = "10101010";
        String b = "01010101";
        String expected = "11111111";
        assertEquals(expected, binaryAddition.addBinary(a, b));
    }
}

package com.thealgorithms.greedyalgorithms;

