     * 4! + 0! + 5! + 8! + 5! = 24 + 1 + 120 + 40320 + 120 = 40585
     */
    @Test
    void testIsKrishnamurthyWithLargestKrishnamurthyNumber() {
        assertTrue(KrishnamurthyNumber.isKrishnamurthy(40585));
    }

    /**
