        array = InsertDeleteInArray.insertElement(array, 2, 1);
        assertArrayEquals(new int[] {1, 2, 3, 5}, array);
        array = InsertDeleteInArray.insertElement(array, 4, 3);
        assertArrayEquals(new int[] {1, 2, 3, 4, 5}, array);
